window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[8]={"800":{"example:800:exzh":"The current situation is not very good.","example:800:exzh2":"He is not used to this situation yet.","example:800:exzh3":"We need to improve the situation.","example:800:exzh4":"Let's think about how to deal with that situation.","example:800:exzh5":"If the situation changes, our actions change too."},"801":{"example:801:exzh":"I work at that company.","example:801:exzh2":"I'm looking forward to going to the office.","example:801:exzh3":"That company started a new project.","example:801:exzh4":"I want to start a company with my friends.","example:801:exzh5":"The company's benefits are very good.","grammar:801:ex:trans":"I work at that company.","grammar:801:ex:structure":"〜で働いています","grammar:801:ex:explain":"This sentence follows the 「〜で働く」 (to work at…) frame, with the workplace marked by 「で」 because working is an action. 「その会社で働いています」 means “work at that company,” and 「〜ています」 expresses an ongoing state. 「は」 marks the topic 「私」. The whole sentence means “I work at that company.” Using 「で」 for a workplace is a common exam point—don't mistakenly use 「に」, which marks existence.","grammar:801:ex:words:0:zh":"I","grammar:801:ex:words:0:note":"わたし","grammar:801:ex:words:0:pos":"pronoun","grammar:801:ex:words:1:zh":"(topic)","grammar:801:ex:words:1:pos":"particle","grammar:801:ex:words:2:zh":"that","grammar:801:ex:words:2:pos":"pre-noun adjectival","grammar:801:ex:words:3:zh":"company","grammar:801:ex:words:3:note":"かいしゃ","grammar:801:ex:words:3:pos":"noun","grammar:801:ex:words:4:zh":"(place)","grammar:801:ex:words:4:pos":"particle","grammar:801:ex:words:5:zh":"is working","grammar:801:ex:words:5:note":"はたらいています","grammar:801:ex:words:5:pos":"verb","grammar:801:ex:points:0":"❗〜で働く: to work at… (で marks place).","grammar:801:ex:points:1":"その会社: that company.","grammar:801:ex2:trans":"I'm looking forward to going to the office.","grammar:801:ex2:structure":"〜のが楽しみです","grammar:801:ex2:words:0:zh":"company","grammar:801:ex2:words:0:note":"かいしゃ","grammar:801:ex2:words:0:pos":"noun","grammar:801:ex2:words:1:zh":"(destination)","grammar:801:ex2:words:1:pos":"particle","grammar:801:ex2:words:2:zh":"go","grammar:801:ex2:words:2:note":"いく","grammar:801:ex2:words:2:pos":"verb","grammar:801:ex2:words:3:zh":"(nominalizer)","grammar:801:ex2:words:3:pos":"particle","grammar:801:ex2:words:4:zh":"(nominative)","grammar:801:ex2:words:4:pos":"particle","grammar:801:ex2:words:5:zh":"look forward to","grammar:801:ex2:words:5:note":"たのしみ","grammar:801:ex2:words:5:pos":"noun","grammar:801:ex2:words:6:zh":"(polite form)","grammar:801:ex2:words:6:pos":"copula","grammar:801:ex2:points:0":"会社に行く: to go to the office.","grammar:801:ex2:points:1":"〜のが楽しみ: to look forward to doing….","grammar:801:ex3:trans":"That company started a new project.","grammar:801:ex3:structure":"〜を始めました","grammar:801:ex3:words:0:zh":"that","grammar:801:ex3:words:0:pos":"pre-noun adjectival","grammar:801:ex3:words:1:zh":"company","grammar:801:ex3:words:1:note":"かいしゃ","grammar:801:ex3:words:1:pos":"noun","grammar:801:ex3:words:2:zh":"(topic)","grammar:801:ex3:words:2:pos":"particle","grammar:801:ex3:words:3:zh":"new","grammar:801:ex3:words:3:note":"あたらしい","grammar:801:ex3:words:3:pos":"adjective","grammar:801:ex3:words:4:zh":"project","grammar:801:ex3:words:4:note":"loanword","grammar:801:ex3:words:4:pos":"noun","grammar:801:ex3:words:5:zh":"(object marker)","grammar:801:ex3:words:5:pos":"particle","grammar:801:ex3:words:6:zh":"started","grammar:801:ex3:words:6:note":"はじめました","grammar:801:ex3:words:6:pos":"verb","grammar:801:ex3:points:0":"プロジェクトを始める: to start a project.","grammar:801:ex3:points:1":"始める → 始めました.","grammar:801:ex4:trans":"I want to start a company with a friend.","grammar:801:ex4:structure":"〜を作りたいです","grammar:801:ex4:words:0:zh":"friend","grammar:801:ex4:words:0:note":"ともだち","grammar:801:ex4:words:0:pos":"noun","grammar:801:ex4:words:1:zh":"with","grammar:801:ex4:words:1:pos":"particle","grammar:801:ex4:words:2:zh":"together","grammar:801:ex4:words:2:note":"いっしょに","grammar:801:ex4:words:2:pos":"adverb","grammar:801:ex4:words:3:zh":"company","grammar:801:ex4:words:3:note":"かいしゃ","grammar:801:ex4:words:3:pos":"noun","grammar:801:ex4:words:4:zh":"(object marker)","grammar:801:ex4:words:4:pos":"particle","grammar:801:ex4:words:5:zh":"want to found","grammar:801:ex4:words:5:note":"つくりたい","grammar:801:ex4:words:5:pos":"verb","grammar:801:ex4:words:6:zh":"(polite form)","grammar:801:ex4:words:6:pos":"copula","grammar:801:ex4:points:0":"❗会社を作る: to found a company, to start a business.","grammar:801:ex4:points:1":"〜たい: to want to ….","grammar:801:ex5:trans":"The company's benefits are very good.","grammar:801:ex5:structure":"〜はとても良いです","grammar:801:ex5:words:0:zh":"company","grammar:801:ex5:words:0:note":"かいしゃ","grammar:801:ex5:words:0:pos":"noun","grammar:801:ex5:words:1:zh":"'s","grammar:801:ex5:words:1:pos":"particle","grammar:801:ex5:words:2:zh":"benefits","grammar:801:ex5:words:2:note":"ふくりこうせい","grammar:801:ex5:words:2:pos":"noun","grammar:801:ex5:words:3:zh":"(topic)","grammar:801:ex5:words:3:pos":"particle","grammar:801:ex5:words:4:zh":"extremely","grammar:801:ex5:words:4:pos":"adverb","grammar:801:ex5:words:5:zh":"good","grammar:801:ex5:words:5:note":"いい","grammar:801:ex5:words:5:pos":"adjective","grammar:801:ex5:words:6:zh":"(polite form)","grammar:801:ex5:words:6:pos":"copula","grammar:801:ex5:points:0":"福利厚生: benefits, welfare program.","grammar:801:ex5:points:1":"会社の福利厚生: company benefits.","exam:801:zh":"My older brother is an employee of a company that makes cars, and he gets his salary from there every month.","exam:801:why":"What makes cars and employs staff is a 「会社」. A 「銀行」 is also a workplace, but its business isn't making cars."},"802":{"example:802:exzh":"It's my turn.","example:802:exzh2":"It's your turn next.","example:802:exzh3":"May I ask what number you are?","example:802:exzh4":"What should we do while we wait for our turn?","example:802:exzh5":"That's my favorite color.","grammar:802:ex:trans":"It's my turn.","grammar:802:ex:structure":"〜の番が来ました","grammar:802:ex:explain":"The key here is the idiomatic expression 「番が来る」. 「番（ばん）」 means order or turn, so 「私の番」 is my turn; with the past polite form of 「来る」, 「来ました」, it literally says “my turn has come,” which is how Japanese says “It's my turn.” The subject 「番」 takes 「が」 because this is new information being presented, not a contrast with something else. The sentence as a whole is a common expression in everyday situations like waiting in line or taking turns.","grammar:802:ex:words:0:zh":"I","grammar:802:ex:words:0:note":"わたし","grammar:802:ex:words:0:pos":"pronoun","grammar:802:ex:words:1:zh":"'s","grammar:802:ex:words:1:pos":"particle","grammar:802:ex:words:2:zh":"one's turn","grammar:802:ex:words:2:note":"ばん","grammar:802:ex:words:2:pos":"noun","grammar:802:ex:words:3:zh":"(nominative)","grammar:802:ex:words:3:pos":"particle","grammar:802:ex:words:4:zh":"came","grammar:802:ex:words:4:note":"きました","grammar:802:ex:words:4:pos":"verb","grammar:802:ex:points:0":"❗番（ばん）: order, turn; 番が来る = to be one's turn.","grammar:802:ex:points:1":"私の番: my turn.","grammar:802:ex2:trans":"Next it's your turn.","grammar:802:ex2:structure":"〜は〜の番です","grammar:802:ex2:words:0:zh":"next","grammar:802:ex2:words:0:note":"つぎ","grammar:802:ex2:words:0:pos":"noun","grammar:802:ex2:words:1:zh":"(topic)","grammar:802:ex2:words:1:pos":"particle","grammar:802:ex2:words:2:zh":"you","grammar:802:ex2:words:2:pos":"pronoun","grammar:802:ex2:words:3:zh":"'s","grammar:802:ex2:words:3:pos":"particle","grammar:802:ex2:words:4:zh":"one's turn","grammar:802:ex2:words:4:note":"ばん","grammar:802:ex2:words:4:pos":"noun","grammar:802:ex2:words:5:zh":"is","grammar:802:ex2:words:5:pos":"copula","grammar:802:ex2:points:0":"あなたの番: your turn.","grammar:802:ex2:points:1":"次は: next.","grammar:802:ex3:trans":"May I ask what number you are?","grammar:802:ex3:structure":"〜てもいいですか","grammar:802:ex3:words:0:zh":"what number","grammar:802:ex3:words:0:note":"なんばん","grammar:802:ex3:words:0:pos":"question word","grammar:802:ex3:words:1:zh":"(quotation, casual speech)","grammar:802:ex3:words:1:pos":"particle","grammar:802:ex3:words:2:zh":"ask","grammar:802:ex3:words:2:note":"きいて","grammar:802:ex3:words:2:pos":"verb","grammar:802:ex3:words:3:zh":"(also)","grammar:802:ex3:words:3:pos":"particle","grammar:802:ex3:words:4:zh":"good","grammar:802:ex3:words:4:pos":"adjective","grammar:802:ex3:words:5:zh":"is","grammar:802:ex3:words:5:pos":"copula","grammar:802:ex3:words:6:zh":"(question)","grammar:802:ex3:words:6:pos":"particle","grammar:802:ex3:points:0":"❗番（ばん）: number (何番 = what number).","grammar:802:ex3:points:1":"〜てもいいですか: may I…?","grammar:802:ex4:trans":"What should we do while we wait for our turn?","grammar:802:ex4:structure":"〜間、何をしましょうか","grammar:802:ex4:words:0:zh":"turn","grammar:802:ex4:words:0:note":"ばん","grammar:802:ex4:words:0:pos":"noun","grammar:802:ex4:words:1:zh":"(object marker)","grammar:802:ex4:words:1:pos":"particle","grammar:802:ex4:words:2:zh":"waiting","grammar:802:ex4:words:2:note":"まっている","grammar:802:ex4:words:2:pos":"verb","grammar:802:ex4:words:3:zh":"period, duration","grammar:802:ex4:words:3:note":"あいだ","grammar:802:ex4:words:3:pos":"noun","grammar:802:ex4:words:4:zh":"what","grammar:802:ex4:words:4:note":"なに","grammar:802:ex4:words:4:pos":"question word","grammar:802:ex4:words:5:zh":"(object marker)","grammar:802:ex4:words:5:pos":"particle","grammar:802:ex4:words:6:zh":"let's do","grammar:802:ex4:words:6:pos":"verb","grammar:802:ex4:words:7:zh":"(question)","grammar:802:ex4:words:7:pos":"particle","grammar:802:ex4:points:0":"〜ている間: while….","grammar:802:ex4:points:1":"何をしましょうか: what should we do?","grammar:802:ex5:trans":"That's my favorite color.","grammar:802:ex5:structure":"それは〜の一番好きな色です","grammar:802:ex5:explain":"「それは」 introduces the topic, and 「私の一番好きな」 modifies 「色」 as a whole, meaning the color I like best. The 「私の」 here can be understood as 「私が」: the person who likes the color is me. 「一番」 expresses the highest degree, and 「好き」 needs 「な」 to modify a noun. Finally 「です」 politely states what color it is.","grammar:802:ex5:words:0:zh":"that","grammar:802:ex5:words:0:pos":"pronoun","grammar:802:ex5:words:1:zh":"(topic)","grammar:802:ex5:words:1:pos":"particle","grammar:802:ex5:words:2:zh":"I","grammar:802:ex5:words:2:note":"わたし","grammar:802:ex5:words:2:pos":"pronoun","grammar:802:ex5:words:3:zh":"(subject in a modifying clause)","grammar:802:ex5:words:3:pos":"particle","grammar:802:ex5:words:4:zh":"the most","grammar:802:ex5:words:4:note":"いちばん","grammar:802:ex5:words:4:pos":"adverb","grammar:802:ex5:words:5:zh":"to like","grammar:802:ex5:words:5:note":"すき","grammar:802:ex5:words:5:pos":"na-adjective","grammar:802:ex5:words:6:zh":"(links a na-adjective to a noun)","grammar:802:ex5:words:6:pos":"auxiliary verb","grammar:802:ex5:words:7:zh":"color","grammar:802:ex5:words:7:note":"いろ","grammar:802:ex5:words:7:pos":"noun","grammar:802:ex5:words:8:zh":"is (polite tone)","grammar:802:ex5:words:8:pos":"auxiliary verb","grammar:802:ex5:points:0":"「一番」 comes before an adjective to mean “most,” so 「一番好き」 means “like the most.”","grammar:802:ex5:points:1":"「好き」 is a na-adjective; when it modifies a noun, you use 「好きな＋noun」.","grammar:802:ex5:points:2":"In a clause that modifies a noun, the subject particle 「が」 can sometimes be replaced by 「の」, as in 「私の好きな色」."},"803":{"example:803:exzh":"That is a mistake.","example:803:exzh2":"Correct the mistake.","example:803:exzh3":"He made a mistake.","example:803:exzh4":"We can learn from our mistakes.","example:803:exzh5":"Don't be afraid of making mistakes, just give it a try.","grammar:803:ex:trans":"That's a mistake.","grammar:803:ex:structure":"〜は間違いです","grammar:803:ex:explain":"「間違い（まちがい）」 is a noun formed from the verb 「間違う」 (to get something wrong) by dropping its ending, meaning a mistake or error. The sentence 「それは間違いです」 uses the most basic 「AはBです」 judgment pattern: the topic 「それ」 is presented with 「は」, then linked to the noun 「間違い」 with the copula 「です」, which is like saying “That's a mistake.” Japanese often uses the noun 「間違い」 to pass judgment, which sounds calmer and more objective than saying 「間違っている」 directly.","grammar:803:ex:words:0:zh":"that","grammar:803:ex:words:0:pos":"pronoun","grammar:803:ex:words:1:zh":"(topic)","grammar:803:ex:words:1:pos":"particle","grammar:803:ex:words:2:zh":"mistake","grammar:803:ex:words:2:note":"まちがい","grammar:803:ex:words:2:pos":"noun","grammar:803:ex:words:3:zh":"is","grammar:803:ex:words:3:pos":"copula","grammar:803:ex:points:0":"間違い（まちがい）: mistake (the noun form of 間違う).","grammar:803:ex:points:1":"それは間違い: that's wrong.","grammar:803:ex2:trans":"Please correct the mistake.","grammar:803:ex2:structure":"〜を〜なさい","grammar:803:ex2:words:0:zh":"mistake","grammar:803:ex2:words:0:note":"まちがい","grammar:803:ex2:words:0:pos":"noun","grammar:803:ex2:words:1:zh":"(object marker)","grammar:803:ex2:words:1:pos":"particle","grammar:803:ex2:words:2:zh":"correct it","grammar:803:ex2:words:2:note":"ただしなさい","grammar:803:ex2:words:2:pos":"verb","grammar:803:ex2:points:0":"❗〜なさい: (mild command) please do….","grammar:803:ex2:points:1":"間違いを正す: to correct a mistake.","grammar:803:ex3:trans":"He made a mistake.","grammar:803:ex3:structure":"〜を犯しました","grammar:803:ex3:words:0:zh":"he","grammar:803:ex3:words:0:note":"かれ","grammar:803:ex3:words:0:pos":"pronoun","grammar:803:ex3:words:1:zh":"(topic)","grammar:803:ex3:words:1:pos":"particle","grammar:803:ex3:words:2:zh":"mistake","grammar:803:ex3:words:2:note":"まちがい","grammar:803:ex3:words:2:pos":"noun","grammar:803:ex3:words:3:zh":"(object marker)","grammar:803:ex3:words:3:pos":"particle","grammar:803:ex3:words:4:zh":"made","grammar:803:ex3:words:4:note":"おかしました","grammar:803:ex3:words:4:pos":"verb","grammar:803:ex3:points:0":"❗間違いを犯す: to make a mistake (fixed expression using 犯す).","grammar:803:ex3:points:1":"犯す → 犯しました.","grammar:803:ex4:trans":"We can learn from mistakes.","grammar:803:ex4:structure":"〜から〜ことができます","grammar:803:ex4:words:0:zh":"we","grammar:803:ex4:words:0:note":"わたしたち","grammar:803:ex4:words:0:pos":"pronoun","grammar:803:ex4:words:1:zh":"(topic)","grammar:803:ex4:words:1:pos":"particle","grammar:803:ex4:words:2:zh":"mistake","grammar:803:ex4:words:2:note":"まちがい","grammar:803:ex4:words:2:pos":"noun","grammar:803:ex4:words:3:zh":"from","grammar:803:ex4:words:3:pos":"particle","grammar:803:ex4:words:4:zh":"study","grammar:803:ex4:words:4:note":"まなぶ","grammar:803:ex4:words:4:pos":"verb","grammar:803:ex4:words:5:zh":"(nominalizer)","grammar:803:ex4:words:5:pos":"noun","grammar:803:ex4:words:6:zh":"(nominative)","grammar:803:ex4:words:6:pos":"particle","grammar:803:ex4:words:7:zh":"be able to","grammar:803:ex4:words:7:pos":"verb","grammar:803:ex4:points:0":"〜から学ぶ: to learn from….","grammar:803:ex4:points:1":"〜ことができる: to be able to…","grammar:803:ex5:trans":"Don't be afraid of mistakes—take on the challenge.","grammar:803:ex5:structure":"〜ずに〜てください","grammar:803:ex5:words:0:zh":"mistake","grammar:803:ex5:words:0:note":"まちがい","grammar:803:ex5:words:0:pos":"noun","grammar:803:ex5:words:1:zh":"(object marker)","grammar:803:ex5:words:1:pos":"particle","grammar:803:ex5:words:2:zh":"not afraid of","grammar:803:ex5:words:2:note":"おそれず","grammar:803:ex5:words:2:pos":"verb","grammar:803:ex5:words:3:zh":"(a state)","grammar:803:ex5:words:3:pos":"particle","grammar:803:ex5:words:4:zh":"challenge; try","grammar:803:ex5:words:4:note":"ちょうせんして","grammar:803:ex5:words:4:pos":"verb","grammar:803:ex5:words:5:zh":"please","grammar:803:ex5:words:5:pos":"auxiliary verb","grammar:803:ex5:points:0":"❗〜ずに: without doing… (恐れずに = without fear).","grammar:803:ex5:points:1":"挑戦する: to take on a challenge."},"804":{"example:804:exzh":"I don't like this job.","example:804:exzh2":"I have bad memories of him.","example:804:exzh3":"I want to forget the unpleasant things.","example:804:exzh4":"I don't want to hear about the things you dislike.","example:804:exzh5":"It's hard to talk about unpleasant feelings.","grammar:804:ex:trans":"I don't like this job.","grammar:804:ex:structure":"〜は嫌です","grammar:804:ex:explain":"「嫌（いや）」 is a na-adjective meaning dislike or unwillingness. Here it works as a predicate and takes 「です」 for the polite form; 「この仕事は嫌です」 literally says “this job is unpleasant to me.” The topic 「は」 brings up 「この仕事」 for comment. Note that 「嫌」 carries a subjective feeling—it's the speaker's like or dislike, not a claim that the job itself is bad. Also, since it's a na-adjective, it needs 「な」 before a noun: 「嫌な仕事」, not 「嫌い仕事」.","grammar:804:ex:words:0:zh":"this","grammar:804:ex:words:0:pos":"pre-noun adjectival","grammar:804:ex:words:1:zh":"work","grammar:804:ex:words:1:note":"しごと","grammar:804:ex:words:1:pos":"noun","grammar:804:ex:words:2:zh":"(topic)","grammar:804:ex:words:2:pos":"particle","grammar:804:ex:words:3:zh":"unpleasant, annoying","grammar:804:ex:words:3:note":"いや","grammar:804:ex:words:3:pos":"na-adjective","grammar:804:ex:words:4:zh":"(polite form)","grammar:804:ex:words:4:pos":"copula","grammar:804:ex:points:0":"❗嫌（いや）: dislike, unwilling (na-adjective).","grammar:804:ex:points:1":"この仕事は嫌: I don't like this job.","grammar:804:ex2:trans":"I have bad memories of him.","grammar:804:ex2:structure":"〜とは嫌な〜があります","grammar:804:ex2:words:0:zh":"he","grammar:804:ex2:words:0:note":"かれ","grammar:804:ex2:words:0:pos":"pronoun","grammar:804:ex2:words:1:zh":"with","grammar:804:ex2:words:1:pos":"particle","grammar:804:ex2:words:2:zh":"(contrast)","grammar:804:ex2:words:2:pos":"particle","grammar:804:ex2:words:3:zh":"unpleasant, annoying","grammar:804:ex2:words:3:note":"いや","grammar:804:ex2:words:3:pos":"na-adjective","grammar:804:ex2:words:4:zh":"(attributive form)","grammar:804:ex2:words:4:pos":"auxiliary verb","grammar:804:ex2:words:5:zh":"memories","grammar:804:ex2:words:5:note":"おもいで","grammar:804:ex2:words:5:pos":"noun","grammar:804:ex2:words:6:zh":"(nominative)","grammar:804:ex2:words:6:pos":"particle","grammar:804:ex2:words:7:zh":"there is / are","grammar:804:ex2:words:7:pos":"verb","grammar:804:ex2:points:0":"嫌な思い出: bad memories (な + noun).","grammar:804:ex2:points:1":"彼とは: with him (in relation to him).","grammar:804:ex3:trans":"I want to forget unpleasant things.","grammar:804:ex3:structure":"嫌な〜は〜たいです","grammar:804:ex3:words:0:zh":"unpleasant, annoying","grammar:804:ex3:words:0:note":"いや","grammar:804:ex3:words:0:pos":"na-adjective","grammar:804:ex3:words:1:zh":"(attributive form)","grammar:804:ex3:words:1:pos":"auxiliary verb","grammar:804:ex3:words:2:zh":"thing / matter","grammar:804:ex3:words:2:pos":"noun","grammar:804:ex3:words:3:zh":"(topic)","grammar:804:ex3:words:3:pos":"particle","grammar:804:ex3:words:4:zh":"want to forget","grammar:804:ex3:words:4:note":"わすれたい","grammar:804:ex3:words:4:pos":"verb","grammar:804:ex3:words:5:zh":"(polite form)","grammar:804:ex3:words:5:pos":"copula","grammar:804:ex3:points:0":"嫌なこと: things you dislike, unpleasant things.","grammar:804:ex3:points:1":"〜たい: to want to ….","grammar:804:ex4:trans":"I don't want to hear about the things you dislike.","grammar:804:ex4:structure":"〜を〜たくないです","grammar:804:ex4:words:0:zh":"you","grammar:804:ex4:words:0:pos":"pronoun","grammar:804:ex4:words:1:zh":"'s","grammar:804:ex4:words:1:pos":"particle","grammar:804:ex4:words:2:zh":"unpleasant, annoying","grammar:804:ex4:words:2:note":"いや","grammar:804:ex4:words:2:pos":"na-adjective","grammar:804:ex4:words:3:zh":"(attributive form)","grammar:804:ex4:words:3:pos":"auxiliary verb","grammar:804:ex4:words:4:zh":"thing / matter","grammar:804:ex4:words:4:pos":"noun","grammar:804:ex4:words:5:zh":"(object marker)","grammar:804:ex4:words:5:pos":"particle","grammar:804:ex4:words:6:zh":"don't want to hear","grammar:804:ex4:words:6:note":"ききたくない","grammar:804:ex4:words:6:pos":"verb","grammar:804:ex4:words:7:zh":"(polite form)","grammar:804:ex4:words:7:pos":"copula","grammar:804:ex4:points:0":"〜たくない: to not want to….","grammar:804:ex4:points:1":"嫌なこと: things you dislike, unpleasant things.","grammar:804:ex5:trans":"It's hard to talk about unpleasant feelings.","grammar:804:ex5:structure":"〜のは難しいです","grammar:804:ex5:words:0:zh":"unpleasant, annoying","grammar:804:ex5:words:0:note":"いや","grammar:804:ex5:words:0:pos":"na-adjective","grammar:804:ex5:words:1:zh":"(attributive form)","grammar:804:ex5:words:1:pos":"auxiliary verb","grammar:804:ex5:words:2:zh":"feelings","grammar:804:ex5:words:2:note":"きもち","grammar:804:ex5:words:2:pos":"noun","grammar:804:ex5:words:3:zh":"(object marker)","grammar:804:ex5:words:3:pos":"particle","grammar:804:ex5:words:4:zh":"tell","grammar:804:ex5:words:4:note":"はなす","grammar:804:ex5:words:4:pos":"verb","grammar:804:ex5:words:5:zh":"(nominalizer)","grammar:804:ex5:words:5:pos":"particle","grammar:804:ex5:words:6:zh":"(topic)","grammar:804:ex5:words:6:pos":"particle","grammar:804:ex5:words:7:zh":"difficult","grammar:804:ex5:words:7:note":"むずかしい","grammar:804:ex5:words:7:pos":"adjective","grammar:804:ex5:words:8:zh":"(polite form)","grammar:804:ex5:words:8:pos":"copula","grammar:804:ex5:points:0":"嫌な気持ち: unpleasant feelings.","grammar:804:ex5:points:1":"〜のは難しい: it is hard to…"},"805":{"example:805:exzh":"This problem is very important.","example:805:exzh2":"Time management is important.","example:805:exzh3":"I think her opinion is important.","example:805:exzh4":"I checked the important data.","example:805:exzh5":"Health is the most important thing in life."},"806":{"example:806:exzh":"He caught the cat.","example:806:exzh2":"Please catch that ball.","example:806:exzh3":"Catching the criminal was difficult.","example:806:exzh4":"I'm going to grab this chance.","example:806:exzh5":"She is good at catching birds."},"807":{"example:807:exzh":"This is a classroom.","example:807:exzh2":"My bedroom is spacious.","example:807:exzh3":"The company's office is very bright.","example:807:exzh4":"He is sleeping in the bedroom.","example:807:exzh5":"This room has many windows.","grammar:807:ex:trans":"This is a classroom.","grammar:807:ex:structure":"これは〜です","grammar:807:ex:explain":"「これ」 refers to the thing the speaker is pointing at, 「は」 makes it the topic, and 「教室です」 says that it is a classroom. The 「室」 in 「教室」 is read 「しつ」 and means room; the whole word is read 「きょうしつ」.","grammar:807:ex:words:0:zh":"this","grammar:807:ex:words:0:pos":"pronoun","grammar:807:ex:words:1:zh":"(topic)","grammar:807:ex:words:1:pos":"particle","grammar:807:ex:words:2:zh":"classroom","grammar:807:ex:words:2:note":"きょうしつ","grammar:807:ex:words:2:pos":"noun","grammar:807:ex:words:3:zh":"is (polite tone)","grammar:807:ex:words:3:pos":"auxiliary verb","grammar:807:ex:points:0":"「AはBです」 is used to explain what A is.","grammar:807:ex:points:1":"「これ」 can be used on its own, while 「この」 must be followed by a noun, as in 「この教室」.","grammar:807:ex2:trans":"My bedroom is spacious.","grammar:807:ex2:structure":"〜の寝室は広いです","grammar:807:ex2:explain":"「私の寝室」 means my bedroom, and 「は」 presents it as the topic to be described. 「広い」 is an i-adjective describing a roomy space, and it can be followed directly by 「です」. 「広いです」 itself contains no word meaning “very”—that nuance just comes out naturally in English.","grammar:807:ex2:words:0:zh":"I","grammar:807:ex2:words:0:note":"わたし","grammar:807:ex2:words:0:pos":"pronoun","grammar:807:ex2:words:1:zh":"(possession)","grammar:807:ex2:words:1:pos":"particle","grammar:807:ex2:words:2:zh":"bedroom","grammar:807:ex2:words:2:note":"しんしつ","grammar:807:ex2:words:2:pos":"noun","grammar:807:ex2:words:3:zh":"(topic)","grammar:807:ex2:words:3:pos":"particle","grammar:807:ex2:words:4:zh":"spacious","grammar:807:ex2:words:4:note":"ひろい","grammar:807:ex2:words:4:pos":"i-adjective","grammar:807:ex2:words:5:zh":"(polite tone)","grammar:807:ex2:words:5:pos":"auxiliary verb","grammar:807:ex2:points:0":"「noun + の + noun」 can show possession, so 「私の寝室」 means “my bedroom.”","grammar:807:ex2:points:1":"An i-adjective can be followed directly by 「です」 to make the polite form; you don't need to add 「だ」.","grammar:807:ex3:trans":"The room at the company is very bright.","grammar:807:ex3:structure":"〜はとても明るいです","grammar:807:ex3:words:0:zh":"company","grammar:807:ex3:words:0:note":"かいしゃ","grammar:807:ex3:words:0:pos":"noun","grammar:807:ex3:words:1:zh":"'s","grammar:807:ex3:words:1:pos":"particle","grammar:807:ex3:words:2:zh":"office","grammar:807:ex3:words:2:note":"しつ","grammar:807:ex3:words:2:pos":"noun","grammar:807:ex3:words:3:zh":"(topic)","grammar:807:ex3:words:3:pos":"particle","grammar:807:ex3:words:4:zh":"extremely","grammar:807:ex3:words:4:pos":"adverb","grammar:807:ex3:words:5:zh":"bright","grammar:807:ex3:words:5:note":"あかるい","grammar:807:ex3:words:5:pos":"adjective","grammar:807:ex3:words:6:zh":"(polite form)","grammar:807:ex3:words:6:pos":"copula","grammar:807:ex3:points:0":"※ A natural way to say it is 「会社の部屋／オフィス」.","grammar:807:ex3:points:1":"明るい: bright.","grammar:807:ex4:trans":"He is sleeping in the bedroom.","grammar:807:ex4:structure":"〜で寝ています","grammar:807:ex4:words:0:zh":"he","grammar:807:ex4:words:0:note":"かれ","grammar:807:ex4:words:0:pos":"pronoun","grammar:807:ex4:words:1:zh":"(topic)","grammar:807:ex4:words:1:pos":"particle","grammar:807:ex4:words:2:zh":"bedroom","grammar:807:ex4:words:2:note":"しんしつ","grammar:807:ex4:words:2:pos":"noun","grammar:807:ex4:words:3:zh":"(place)","grammar:807:ex4:words:3:pos":"particle","grammar:807:ex4:words:4:zh":"asleep","grammar:807:ex4:words:4:note":"ねています","grammar:807:ex4:words:4:pos":"verb","grammar:807:ex4:points:0":"寝室（しんしつ）: bedroom (寝 + 室).","grammar:807:ex4:points:1":"〜で寝る: to sleep in….","grammar:807:ex5:trans":"There are lots of windows in this room.","grammar:807:ex5:structure":"〜には〜があります (〜 has 〜)","grammar:807:ex5:words:0:zh":"this","grammar:807:ex5:words:0:pos":"pre-noun adjectival","grammar:807:ex5:words:1:zh":"room","grammar:807:ex5:words:1:note":"しつ","grammar:807:ex5:words:1:pos":"noun","grammar:807:ex5:words:2:zh":"(location of existence)","grammar:807:ex5:words:2:pos":"particle","grammar:807:ex5:words:3:zh":"(contrast)","grammar:807:ex5:words:3:pos":"particle","grammar:807:ex5:words:4:zh":"window","grammar:807:ex5:words:4:note":"まど","grammar:807:ex5:words:4:pos":"noun","grammar:807:ex5:words:5:zh":"(nominative)","grammar:807:ex5:words:5:pos":"particle","grammar:807:ex5:words:6:zh":"a lot","grammar:807:ex5:words:6:pos":"adverb","grammar:807:ex5:words:7:zh":"there is / are","grammar:807:ex5:words:7:pos":"verb","grammar:807:ex5:points:0":"この室: this room (「部屋」 is the natural choice).","grammar:807:ex5:points:1":"〜には〜がある: … has…, there is… in…"},"809":{"example:809:exzh":"I meet my friends every week.","example:809:exzh2":"Next week I'm going on a trip for a week.","example:809:exzh3":"I meet my friends every week.","example:809:exzh4":"She took a week off.","example:809:exzh5":"What are the plans for this week?","grammar:809:ex:trans":"I meet friends every week.","grammar:809:ex:structure":"毎週、〜と会います","grammar:809:ex:explain":"The key is the frequency adverb 「毎週（まいしゅう）」, meaning every week, which is different from 「週間」, used for counting a length of time (as in 「一週間」 = one week)—don't mix them up. In the verb phrase 「友達と会う」, 「と」 marks doing a mutual action together with someone; meeting always involves another person, so 「と」 is used. The polite 「会います」 expresses a habitual action, so the whole sentence means “I meet friends every week.”","grammar:809:ex:words:0:zh":"every week","grammar:809:ex:words:0:note":"まいしゅう","grammar:809:ex:words:0:pos":"adverb","grammar:809:ex:words:1:zh":"friend","grammar:809:ex:words:1:note":"ともだち","grammar:809:ex:words:1:pos":"noun","grammar:809:ex:words:2:zh":"with","grammar:809:ex:words:2:pos":"particle","grammar:809:ex:words:3:zh":"meet","grammar:809:ex:words:3:note":"あいます","grammar:809:ex:words:3:pos":"verb","grammar:809:ex:points:1":"友達と会う: to meet a friend.","grammar:809:ex2:trans":"Next week I'm going on a trip for a week.","grammar:809:ex2:structure":"来週は〜週間、旅行に行きます","grammar:809:ex2:explain":"「来週は」 sets next week as the time topic. 「一週間」 shows the length of the trip, and no particle is needed here. 「旅行に行きます」 means to go on a trip, and with the time clue 「来週」, 「行きます」 is understood as a future plan.","grammar:809:ex2:words:0:zh":"next week","grammar:809:ex2:words:0:note":"らいしゅう","grammar:809:ex2:words:0:pos":"noun","grammar:809:ex2:words:1:zh":"(time topic)","grammar:809:ex2:words:1:pos":"particle","grammar:809:ex2:words:2:zh":"one","grammar:809:ex2:words:2:note":"いっ","grammar:809:ex2:words:2:pos":"numeral","grammar:809:ex2:words:3:zh":"week (duration)","grammar:809:ex2:words:3:note":"しゅうかん","grammar:809:ex2:words:3:pos":"suffix","grammar:809:ex2:words:4:zh":"travel / trip","grammar:809:ex2:words:4:note":"りょこう","grammar:809:ex2:words:4:pos":"noun","grammar:809:ex2:words:5:zh":"(purpose of movement)","grammar:809:ex2:words:5:pos":"particle","grammar:809:ex2:words:6:zh":"go","grammar:809:ex2:words:6:note":"いき","grammar:809:ex2:words:6:pos":"verb","grammar:809:ex2:words:7:zh":"(polite tone)","grammar:809:ex2:words:7:pos":"auxiliary verb","grammar:809:ex2:points:0":"A time expression showing how long something lasts can directly modify a verb, as in 「一週間、旅行に行きます」.","grammar:809:ex2:points:1":"The 「に」 in 「旅行に行く」 marks the purpose of movement, meaning “to go on a trip.”","grammar:809:ex2:points:2":"Relative time words like 「来週」 usually don't take the time-point particle 「に」.","grammar:809:ex3:trans":"I meet friends every week.","grammar:809:ex3:structure":"(better as 毎週) 〜と会います","grammar:809:ex3:words:0:zh":"every week","grammar:809:ex3:words:0:note":"まいしゅうかん","grammar:809:ex3:words:0:pos":"noun","grammar:809:ex3:words:1:zh":"friend","grammar:809:ex3:words:1:note":"ともだち","grammar:809:ex3:words:1:pos":"noun","grammar:809:ex3:words:2:zh":"with","grammar:809:ex3:words:2:pos":"particle","grammar:809:ex3:words:3:zh":"meet","grammar:809:ex3:words:3:note":"あいます","grammar:809:ex3:words:3:pos":"verb","grammar:809:ex3:points:0":"❗「毎週間」 is unnatural: for every week you should say 「毎週（まいしゅう）」.","grammar:809:ex4:trans":"She took a week off.","grammar:809:ex4:structure":"〜週間〜を取りました","grammar:809:ex4:words:0:zh":"she","grammar:809:ex4:words:0:note":"かのじょ","grammar:809:ex4:words:0:pos":"pronoun","grammar:809:ex4:words:1:zh":"(topic)","grammar:809:ex4:words:1:pos":"particle","grammar:809:ex4:words:2:zh":"one week","grammar:809:ex4:words:2:note":"いっしゅうかん","grammar:809:ex4:words:2:pos":"noun","grammar:809:ex4:words:3:zh":"time off","grammar:809:ex4:words:3:note":"やすみ","grammar:809:ex4:words:3:pos":"noun","grammar:809:ex4:words:4:zh":"(object marker)","grammar:809:ex4:words:4:pos":"particle","grammar:809:ex4:words:5:zh":"took","grammar:809:ex4:words:5:note":"とりました","grammar:809:ex4:words:5:pos":"verb","grammar:809:ex4:points:0":"❗一週間（いっしゅうかん）: one week (週間 = the unit for a week-long period).","grammar:809:ex4:points:1":"休みを取る: to take time off.","grammar:809:ex5:trans":"What's the plan for this week?","grammar:809:ex5:structure":"この〜の予定は何ですか","grammar:809:ex5:explain":"「この一週間」 refers to the week being talked about, and 「の」 links that span of time to 「予定」, giving “the plans for this week.” 「は」 presents the topic and 「何ですか」 asks what the plans are. 「予定」 usually means a schedule or plans arranged in advance.","grammar:809:ex5:words:0:zh":"this","grammar:809:ex5:words:0:pos":"pre-noun adjectival","grammar:809:ex5:words:1:zh":"one","grammar:809:ex5:words:1:note":"いっ","grammar:809:ex5:words:1:pos":"numeral","grammar:809:ex5:words:2:zh":"week (duration)","grammar:809:ex5:words:2:note":"しゅうかん","grammar:809:ex5:words:2:pos":"suffix","grammar:809:ex5:words:3:zh":"(modifying a time range)","grammar:809:ex5:words:3:pos":"particle","grammar:809:ex5:words:4:zh":"plan, schedule","grammar:809:ex5:words:4:note":"よてい","grammar:809:ex5:words:4:pos":"noun","grammar:809:ex5:words:5:zh":"(topic)","grammar:809:ex5:words:5:pos":"particle","grammar:809:ex5:words:6:zh":"what","grammar:809:ex5:words:6:note":"なん","grammar:809:ex5:words:6:pos":"pronoun","grammar:809:ex5:words:7:zh":"is (polite tone)","grammar:809:ex5:words:7:pos":"auxiliary verb","grammar:809:ex5:words:8:zh":"(question)","grammar:809:ex5:words:8:pos":"particle","grammar:809:ex5:points:0":"「time span + の + 予定」 shows the plans for that period.","grammar:809:ex5:points:1":"「何」 is read 「なん」 in 「何ですか」."},"810":{"example:810:exzh":"My mother is a good cook.","example:810:exzh2":"I'll go shopping with my mother.","example:810:exzh3":"My mother wakes me up every day.","example:810:exzh4":"My mother is my best friend.","example:810:exzh5":"I'm grateful to my mother.","grammar:810:ex:trans":"My mother is good at cooking.","grammar:810:ex:structure":"〜は〜が上手です","grammar:810:ex:explain":"The core pattern is 「〜は〜が上手です」, which says that someone is good at something. The thing you're good at takes 「が」 rather than 「を」 — this is the fixed Japanese way to express ability, likes, and dislikes. 「上手（じょうず）」 is a na-adjective. Also watch the kinship term: 「お母さん」 is the respectful form used for someone else's mother or when addressing your own mother directly; when you talk about your own mother to an outsider, you should use the humble 「母（はは）」. Using 「おかあさん」 here sounds a little casual.","grammar:810:ex:words:0:zh":"I","grammar:810:ex:words:0:note":"わたし","grammar:810:ex:words:0:pos":"pronoun","grammar:810:ex:words:1:zh":"'s","grammar:810:ex:words:1:pos":"particle","grammar:810:ex:words:2:zh":"mother","grammar:810:ex:words:2:pos":"noun","grammar:810:ex:words:3:zh":"(topic)","grammar:810:ex:words:3:pos":"particle","grammar:810:ex:words:4:zh":"cooking","grammar:810:ex:words:4:note":"りょうり","grammar:810:ex:words:4:pos":"noun","grammar:810:ex:words:5:zh":"(object)","grammar:810:ex:words:5:pos":"particle","grammar:810:ex:words:6:zh":"good at","grammar:810:ex:words:6:note":"じょうず","grammar:810:ex:words:6:pos":"na-adjective","grammar:810:ex:words:7:zh":"(polite form)","grammar:810:ex:words:7:pos":"copula","grammar:810:ex:points:0":"❗お母さん（おかあさん）: mother (respectful); for your own mother, the humble 「母（はは）」.","grammar:810:ex:points:1":"With 上手, the thing you're good at takes が.","grammar:810:ex2:trans":"I'll go shopping with my mother.","grammar:810:ex2:structure":"〜と買い物に行きます","grammar:810:ex2:words:0:zh":"mother","grammar:810:ex2:words:0:pos":"noun","grammar:810:ex2:words:1:zh":"with","grammar:810:ex2:words:1:pos":"particle","grammar:810:ex2:words:2:zh":"together","grammar:810:ex2:words:2:note":"いっしょに","grammar:810:ex2:words:2:pos":"adverb","grammar:810:ex2:words:3:zh":"shopping","grammar:810:ex2:words:3:note":"かいもの","grammar:810:ex2:words:3:pos":"noun","grammar:810:ex2:words:4:zh":"(purpose)","grammar:810:ex2:words:4:pos":"particle","grammar:810:ex2:words:5:zh":"go","grammar:810:ex2:words:5:pos":"verb","grammar:810:ex2:points:0":"買い物に行く: to go shopping.","grammar:810:ex2:points:1":"おかあさんと一緒に: together with mom.","grammar:810:ex3:trans":"Every day it's my mother who wakes me up.","grammar:810:ex3:structure":"〜を〜てくれます","grammar:810:ex3:words:0:zh":"every day","grammar:810:ex3:words:0:note":"まいにち","grammar:810:ex3:words:0:pos":"adverb","grammar:810:ex3:words:1:zh":"mother","grammar:810:ex3:words:1:pos":"noun","grammar:810:ex3:words:2:zh":"(nominative)","grammar:810:ex3:words:2:pos":"particle","grammar:810:ex3:words:3:zh":"I","grammar:810:ex3:words:3:note":"わたし","grammar:810:ex3:words:3:pos":"pronoun","grammar:810:ex3:words:4:zh":"(object marker)","grammar:810:ex3:words:4:pos":"particle","grammar:810:ex3:words:5:zh":"wake up","grammar:810:ex3:words:5:note":"おこして","grammar:810:ex3:words:5:pos":"verb","grammar:810:ex3:words:6:zh":"(for me)","grammar:810:ex3:words:6:pos":"auxiliary verb","grammar:810:ex3:points:0":"❗〜てくれる: (someone) does … for me (giving and receiving).","grammar:810:ex3:points:1":"起こす: to wake (someone) up (transitive verb).","grammar:810:ex4:trans":"My mother is my best friend.","grammar:810:ex4:structure":"〜は一番の〜です","grammar:810:ex4:words:0:zh":"mother","grammar:810:ex4:words:0:pos":"noun","grammar:810:ex4:words:1:zh":"(topic)","grammar:810:ex4:words:1:pos":"particle","grammar:810:ex4:words:2:zh":"I","grammar:810:ex4:words:2:note":"わたし","grammar:810:ex4:words:2:pos":"pronoun","grammar:810:ex4:words:3:zh":"'s","grammar:810:ex4:words:3:pos":"particle","grammar:810:ex4:words:4:zh":"the most","grammar:810:ex4:words:4:note":"いちばん","grammar:810:ex4:words:4:pos":"noun","grammar:810:ex4:words:5:zh":"'s","grammar:810:ex4:words:5:pos":"particle","grammar:810:ex4:words:6:zh":"friend","grammar:810:ex4:words:6:note":"ともだち","grammar:810:ex4:words:6:pos":"noun","grammar:810:ex4:words:7:zh":"is","grammar:810:ex4:words:7:pos":"copula","grammar:810:ex4:points:0":"一番の友達: best friend.","grammar:810:ex4:points:1":"おかあさん: mom.","grammar:810:ex5:trans":"I'm very grateful to my mother.","grammar:810:ex5:structure":"〜に感謝しています","grammar:810:ex5:words:0:zh":"mother","grammar:810:ex5:words:0:pos":"noun","grammar:810:ex5:words:1:zh":"(object)","grammar:810:ex5:words:1:pos":"particle","grammar:810:ex5:words:2:zh":"am grateful","grammar:810:ex5:words:2:note":"かんしゃしています","grammar:810:ex5:words:2:pos":"verb","grammar:810:ex5:points:0":"〜に感謝する: to be grateful for …","grammar:810:ex5:points:1":"おかあさんに: to mom.","exam:810:zh":"The woman who gave birth to Tanaka is Tanaka's mother.","exam:810:why":"The woman who gives birth to someone is their 「お母さん」. 「お姉さん」 means older sister, which doesn't match the parent-child relationship described in the sentence."},"811":{"example:811:exzh":"Where is the source of this information?","example:811:exzh2":"We need to check the source.","example:811:exzh3":"My friend told me the original story.","example:811:exzh4":"Let's review the original plan again.","example:811:exzh5":"This source is very important."},"812":{"example:812:exzh":"She likes to travel freely.","example:812:exzh2":"Freedom is a right.","example:812:exzh3":"Having free time lets me relax.","example:812:exzh4":"Expressing your opinions freely is important.","example:812:exzh5":"Freedom is respected in this country.","grammar:812:ex:trans":"She likes to travel freely.","grammar:812:ex:structure":"〜に〜ことが好きです","grammar:812:ex:explain":"This sentence has two key points. First, 「自由に」: the na-adjective 「自由」 plus 「に」 becomes an adverb that modifies a verb, meaning in a free manner. Second, 「〜ことが好き」: the verb 「旅行する」 is followed by the formal noun 「こと」, which turns the whole action into a noun; then 「が」 marks the object of like or dislike and pairs with the na-adjective 「好き」, giving the sense of liking to do something. Put together, it means she likes traveling freely and as she pleases.","grammar:812:ex:words:0:zh":"she","grammar:812:ex:words:0:note":"かのじょ","grammar:812:ex:words:0:pos":"pronoun","grammar:812:ex:words:1:zh":"(topic)","grammar:812:ex:words:1:pos":"particle","grammar:812:ex:words:2:zh":"freedom","grammar:812:ex:words:2:note":"じゆう","grammar:812:ex:words:2:pos":"na-adjective","grammar:812:ex:words:3:zh":"(made adverbial)","grammar:812:ex:words:3:pos":"particle","grammar:812:ex:words:4:zh":"travel / trip","grammar:812:ex:words:4:note":"りょこうする","grammar:812:ex:words:4:pos":"verb","grammar:812:ex:words:5:zh":"(nominalizer)","grammar:812:ex:words:5:pos":"noun","grammar:812:ex:words:6:zh":"(object)","grammar:812:ex:words:6:pos":"particle","grammar:812:ex:words:7:zh":"to like","grammar:812:ex:words:7:note":"すき","grammar:812:ex:words:7:pos":"na-adjective","grammar:812:ex:words:8:zh":"(polite form)","grammar:812:ex:words:8:pos":"copula","grammar:812:ex:points:0":"❗自由に: freely (na-adjective + に makes an adverb).","grammar:812:ex:points:1":"〜ことが好き: to like doing ….","grammar:812:ex2:trans":"Freedom is a right.","grammar:812:ex2:structure":"〜は〜です","grammar:812:ex2:words:0:zh":"freedom","grammar:812:ex2:words:0:note":"じゆう","grammar:812:ex2:words:0:pos":"noun","grammar:812:ex2:words:1:zh":"(topic)","grammar:812:ex2:words:1:pos":"particle","grammar:812:ex2:words:2:zh":"rights","grammar:812:ex2:words:2:note":"けんり","grammar:812:ex2:words:2:pos":"noun","grammar:812:ex2:words:3:zh":"is","grammar:812:ex2:words:3:pos":"copula","grammar:812:ex2:points:0":"自由（じゆう）: freedom.","grammar:812:ex2:points:1":"権利: rights.","grammar:812:ex3:trans":"Having free time lets me relax.","grammar:812:ex3:structure":"〜があると〜できます","grammar:812:ex3:words:0:zh":"freedom","grammar:812:ex3:words:0:note":"じゆう","grammar:812:ex3:words:0:pos":"na-adjective","grammar:812:ex3:words:1:zh":"(attributive form)","grammar:812:ex3:words:1:pos":"auxiliary verb","grammar:812:ex3:words:2:zh":"time","grammar:812:ex3:words:2:note":"じかん","grammar:812:ex3:words:2:pos":"noun","grammar:812:ex3:words:3:zh":"(nominative)","grammar:812:ex3:words:3:pos":"particle","grammar:812:ex3:words:4:zh":"there is / are","grammar:812:ex3:words:4:pos":"verb","grammar:812:ex3:words:5:zh":"(as soon as…)","grammar:812:ex3:words:5:pos":"particle","grammar:812:ex3:words:6:zh":"can relax","grammar:812:ex3:words:6:pos":"verb","grammar:812:ex3:points:0":"自由な時間: free time (na-adjective + noun).","grammar:812:ex3:points:1":"❗〜と: whenever …, then … (if I have it, I can relax).","grammar:812:ex4:trans":"It's important to express your opinions freely.","grammar:812:ex4:structure":"〜ことが大切です","grammar:812:ex4:words:0:zh":"freedom","grammar:812:ex4:words:0:note":"じゆう","grammar:812:ex4:words:0:pos":"na-adjective","grammar:812:ex4:words:1:zh":"(made adverbial)","grammar:812:ex4:words:1:pos":"particle","grammar:812:ex4:words:2:zh":"opinion","grammar:812:ex4:words:2:note":"いけん","grammar:812:ex4:words:2:pos":"noun","grammar:812:ex4:words:3:zh":"(object marker)","grammar:812:ex4:words:3:pos":"particle","grammar:812:ex4:words:4:zh":"state","grammar:812:ex4:words:4:note":"のべる","grammar:812:ex4:words:4:pos":"verb","grammar:812:ex4:words:5:zh":"(nominalizer)","grammar:812:ex4:words:5:pos":"noun","grammar:812:ex4:words:6:zh":"(nominative)","grammar:812:ex4:words:6:pos":"particle","grammar:812:ex4:words:7:zh":"important","grammar:812:ex4:words:7:note":"たいせつ","grammar:812:ex4:words:7:pos":"na-adjective","grammar:812:ex4:words:8:zh":"(polite form)","grammar:812:ex4:words:8:pos":"copula","grammar:812:ex4:points:0":"意見を述べる: to state an opinion.","grammar:812:ex4:points:1":"〜ことが大切です: doing … is important.","grammar:812:ex5:trans":"This country respects freedom.","grammar:812:ex5:structure":"〜が尊重されています","grammar:812:ex5:words:0:zh":"this","grammar:812:ex5:words:0:pos":"pre-noun adjectival","grammar:812:ex5:words:1:zh":"country","grammar:812:ex5:words:1:note":"くに","grammar:812:ex5:words:1:pos":"noun","grammar:812:ex5:words:2:zh":"(scope)","grammar:812:ex5:words:2:pos":"particle","grammar:812:ex5:words:3:zh":"(contrast)","grammar:812:ex5:words:3:pos":"particle","grammar:812:ex5:words:4:zh":"freedom","grammar:812:ex5:words:4:note":"じゆう","grammar:812:ex5:words:4:pos":"noun","grammar:812:ex5:words:5:zh":"(nominative)","grammar:812:ex5:words:5:pos":"particle","grammar:812:ex5:words:6:zh":"is respected","grammar:812:ex5:words:6:note":"そんちょうされています (passive)","grammar:812:ex5:words:6:pos":"verb","grammar:812:ex5:points:0":"尊重される: to be respected (passive).","grammar:812:ex5:points:1":"この国では: in this country."},"813":{"example:813:exzh":"That samurai is an outstanding warrior.","example:813:exzh2":"I have the pride of a samurai.","example:813:exzh3":"You should keep your word as a samurai.","example:813:exzh4":"He fulfills his responsibilities as a samurai.","example:813:exzh5":"Samurai value honor."},"814":{"example:814:exzh":"He is my enemy.","example:814:exzh2":"Knowing your enemy is important.","example:814:exzh3":"She is surrounded by enemies.","example:814:exzh4":"We are fighting a common enemy.","example:814:exzh5":"We prepare in order to defeat the enemy."},"815":{"example:815:exzh":"The deadline for submitting the report is tomorrow.","example:815:exzh2":"He made the latest report.","example:815:exzh3":"I will report on this matter.","example:815:exzh4":"Don't forget to report to your boss.","example:815:exzh5":"Please check the report."},"816":{"example:816:exzh":"This problem is easy.","example:816:exzh2":"Please give me a simple explanation.","example:816:exzh3":"This can be solved easily.","example:816:exzh4":"Let's choose the easy path.","example:816:exzh5":"Let's start with simple practice.","grammar:816:ex:trans":"This problem is simple.","grammar:816:ex:structure":"〜は簡単です","grammar:816:ex:explain":"「簡単（かんたん）」 is a na-adjective meaning simple or easy. Here it is the predicate and takes 「です」 directly to become the polite form 「簡単です」. The pattern is 「〜は簡単です」: the topic 「この問題」 is presented with 「は」 and then commented on. Remember that a na-adjective as a predicate takes 「です」 directly and does not conjugate like a verb; before a noun, though, it needs 「な」, as in 「簡単な問題」.","grammar:816:ex:words:0:zh":"this","grammar:816:ex:words:0:pos":"pre-noun adjectival","grammar:816:ex:words:1:zh":"problem","grammar:816:ex:words:1:note":"もんだい","grammar:816:ex:words:1:pos":"noun","grammar:816:ex:words:2:zh":"(topic)","grammar:816:ex:words:2:pos":"particle","grammar:816:ex:words:3:zh":"easy","grammar:816:ex:words:3:note":"かんたん","grammar:816:ex:words:3:pos":"na-adjective","grammar:816:ex:words:4:zh":"(polite form)","grammar:816:ex:words:4:pos":"copula","grammar:816:ex:points:0":"簡単（かんたん）: simple (na-adjective).","grammar:816:ex:points:1":"この問題: this problem.","grammar:816:ex2:trans":"Please give me a simple explanation.","grammar:816:ex2:structure":"簡単な〜をお願いします","grammar:816:ex2:words:0:zh":"easy","grammar:816:ex2:words:0:note":"かんたん","grammar:816:ex2:words:0:pos":"na-adjective","grammar:816:ex2:words:1:zh":"(attributive form)","grammar:816:ex2:words:1:pos":"auxiliary verb","grammar:816:ex2:words:2:zh":"explanation","grammar:816:ex2:words:2:note":"せつめい","grammar:816:ex2:words:2:pos":"noun","grammar:816:ex2:words:3:zh":"(object marker)","grammar:816:ex2:words:3:pos":"particle","grammar:816:ex2:words:4:zh":"please","grammar:816:ex2:words:4:note":"おねがいします","grammar:816:ex2:words:4:pos":"set phrase","grammar:816:ex2:points:0":"簡単な説明: a simple explanation (na-adjective + noun).","grammar:816:ex2:points:1":"〜をお願いします: please give me ….","grammar:816:ex3:trans":"This can be solved easily.","grammar:816:ex3:structure":"〜は簡単に〜できます","grammar:816:ex3:words:0:zh":"this","grammar:816:ex3:words:0:pos":"pronoun","grammar:816:ex3:words:1:zh":"(topic)","grammar:816:ex3:words:1:pos":"particle","grammar:816:ex3:words:2:zh":"easily","grammar:816:ex3:words:2:note":"かんたんに","grammar:816:ex3:words:2:pos":"adverb","grammar:816:ex3:words:3:zh":"can solve","grammar:816:ex3:words:3:note":"かいけつできます","grammar:816:ex3:words:3:pos":"verb","grammar:816:ex3:points:0":"簡単に: easily (na-adjective + に makes an adverb).","grammar:816:ex3:points:1":"解決できる: can solve (potential form).","grammar:816:ex4:trans":"Let's choose the easy path.","grammar:816:ex4:structure":"簡単な〜を選びましょう","grammar:816:ex4:words:0:zh":"easy","grammar:816:ex4:words:0:note":"かんたん","grammar:816:ex4:words:0:pos":"na-adjective","grammar:816:ex4:words:1:zh":"(attributive form)","grammar:816:ex4:words:1:pos":"auxiliary verb","grammar:816:ex4:words:2:zh":"road","grammar:816:ex4:words:2:note":"みち","grammar:816:ex4:words:2:pos":"noun","grammar:816:ex4:words:3:zh":"(object marker)","grammar:816:ex4:words:3:pos":"particle","grammar:816:ex4:words:4:zh":"let's choose","grammar:816:ex4:words:4:note":"えらびましょう","grammar:816:ex4:words:4:pos":"verb","grammar:816:ex4:points:0":"簡単な道: the easy path.","grammar:816:ex4:points:1":"〜ましょう: a suggestion.","grammar:816:ex5:trans":"Let's start with easy practice.","grammar:816:ex5:structure":"〜から始めましょう","grammar:816:ex5:words:0:zh":"easy","grammar:816:ex5:words:0:note":"かんたん","grammar:816:ex5:words:0:pos":"na-adjective","grammar:816:ex5:words:1:zh":"(attributive form)","grammar:816:ex5:words:1:pos":"auxiliary verb","grammar:816:ex5:words:2:zh":"practice","grammar:816:ex5:words:2:note":"れんしゅう","grammar:816:ex5:words:2:pos":"noun","grammar:816:ex5:words:3:zh":"from","grammar:816:ex5:words:3:pos":"particle","grammar:816:ex5:words:4:zh":"let's start","grammar:816:ex5:words:4:note":"はじめましょう","grammar:816:ex5:words:4:pos":"verb","grammar:816:ex5:points:0":"❗〜から始める: to start from ….","grammar:816:ex5:points:1":"簡単な練習: easy practice."},"817":{"example:817:exzh":"Can you hear the sound?","example:817:exzh2":"The night is quiet, with no sound.","example:817:exzh3":"The sound of this music is pleasant.","example:817:exzh4":"The sound is echoing.","example:817:exzh5":"I want to listen to music with good sound quality.","grammar:817:ex:trans":"Can you hear the sound?","grammar:817:ex:structure":"〜が聞こえますか","grammar:817:ex:explain":"Two key points. First, 「音（おと）」 is a sound made by an object or the environment; don't confuse it with 「声（こえ）」, which is a voice coming from a person or animal. Second, the verb 「聞こえる」 is an intransitive verb meaning to hear something naturally, focusing on the sound reaching your ears, so the thing heard takes 「が」, not 「を」. The final 「か」 makes it a question, and the whole sentence asks whether the other person can hear the sound.","grammar:817:ex:words:0:zh":"voice","grammar:817:ex:words:0:note":"おと","grammar:817:ex:words:0:pos":"noun","grammar:817:ex:words:1:zh":"(nominative)","grammar:817:ex:words:1:pos":"particle","grammar:817:ex:words:2:zh":"can hear","grammar:817:ex:words:2:note":"きこえます","grammar:817:ex:words:2:pos":"verb","grammar:817:ex:words:3:zh":"(question)","grammar:817:ex:words:3:pos":"particle","grammar:817:ex:points:0":"❗音（おと）: a sound (made by an object).","grammar:817:ex:points:1":"聞こえる: to be audible, to be heard (intransitive verb; its subject takes が).","grammar:817:ex2:trans":"The night is quiet and there's no sound.","grammar:817:ex2:structure":"〜で〜がない","grammar:817:ex2:words:0:zh":"night","grammar:817:ex2:words:0:note":"よる","grammar:817:ex2:words:0:pos":"noun","grammar:817:ex2:words:1:zh":"(topic)","grammar:817:ex2:words:1:pos":"particle","grammar:817:ex2:words:2:zh":"quiet","grammar:817:ex2:words:2:note":"しずか","grammar:817:ex2:words:2:pos":"na-adjective","grammar:817:ex2:words:3:zh":"(te-form)","grammar:817:ex2:words:3:pos":"auxiliary verb","grammar:817:ex2:words:4:zh":"voice","grammar:817:ex2:words:4:note":"おと","grammar:817:ex2:words:4:pos":"noun","grammar:817:ex2:words:5:zh":"(nominative)","grammar:817:ex2:words:5:pos":"particle","grammar:817:ex2:words:6:zh":"don't have","grammar:817:ex2:words:6:pos":"adjective","grammar:817:ex2:points:0":"❗〜で: (links two clauses) …, and ….","grammar:817:ex2:points:1":"音がない: there is no sound.","grammar:817:ex3:trans":"This music has a pleasant sound.","grammar:817:ex3:structure":"〜は〜音です","grammar:817:ex3:words:0:zh":"this","grammar:817:ex3:words:0:pos":"pre-noun adjectival","grammar:817:ex3:words:1:zh":"music","grammar:817:ex3:words:1:note":"おんがく","grammar:817:ex3:words:1:pos":"noun","grammar:817:ex3:words:2:zh":"(topic)","grammar:817:ex3:words:2:pos":"particle","grammar:817:ex3:words:3:zh":"comfortable","grammar:817:ex3:words:3:note":"ここちよい","grammar:817:ex3:words:3:pos":"adjective","grammar:817:ex3:words:4:zh":"voice","grammar:817:ex3:words:4:note":"おと","grammar:817:ex3:words:4:pos":"noun","grammar:817:ex3:words:5:zh":"is","grammar:817:ex3:words:5:pos":"copula","grammar:817:ex3:points:0":"心地よい: pleasant, easy on the ears.","grammar:817:ex3:points:1":"心地よい音: a pleasant sound.","grammar:817:ex4:trans":"The sound is echoing.","grammar:817:ex4:structure":"〜が響いています","grammar:817:ex4:words:0:zh":"voice","grammar:817:ex4:words:0:note":"おと","grammar:817:ex4:words:0:pos":"noun","grammar:817:ex4:words:1:zh":"(nominative)","grammar:817:ex4:words:1:pos":"particle","grammar:817:ex4:words:2:zh":"is echoing","grammar:817:ex4:words:2:note":"ひびいています","grammar:817:ex4:words:2:pos":"verb","grammar:817:ex4:points:0":"響く: to echo, to resound (intransitive verb).","grammar:817:ex4:points:1":"〜ている: the state (of echoing).","grammar:817:ex5:trans":"I want to listen to music with good sound.","grammar:817:ex5:structure":"〜で音楽を聴きたいです","grammar:817:ex5:explain":"「良い」 directly modifies 「音」, and 「良い音で」 here means listening with good sound or sound quality. 「音楽を」 is what is being listened to. 「聴く」 changes to 「聴き」, then takes the desire suffix 「たい」, and 「です」 makes it polite.","grammar:817:ex5:words:0:zh":"good","grammar:817:ex5:words:0:note":"よい","grammar:817:ex5:words:0:pos":"i-adjective","grammar:817:ex5:words:1:zh":"sound, sound quality","grammar:817:ex5:words:1:note":"おと","grammar:817:ex5:words:1:pos":"noun","grammar:817:ex5:words:2:zh":"(manner, condition)","grammar:817:ex5:words:2:pos":"particle","grammar:817:ex5:words:3:zh":"music","grammar:817:ex5:words:3:note":"おんがく","grammar:817:ex5:words:3:pos":"noun","grammar:817:ex5:words:4:zh":"(object)","grammar:817:ex5:words:4:pos":"particle","grammar:817:ex5:words:5:zh":"listen","grammar:817:ex5:words:5:note":"きき","grammar:817:ex5:words:5:pos":"verb","grammar:817:ex5:words:6:zh":"to want to","grammar:817:ex5:words:6:pos":"auxiliary verb","grammar:817:ex5:words:7:zh":"(polite tone)","grammar:817:ex5:words:7:pos":"auxiliary verb","grammar:817:ex5:points:0":"Take a verb's masu-form, drop 「ます」, and add 「たい」 to say you want to do something.","grammar:817:ex5:points:1":"The 「で」 in 「良い音で」 marks the manner or the sound conditions for listening to music.","grammar:817:ex5:points:2":"「聴く」 is commonly used for actively enjoying music or listening closely to content."},"818":{"example:818:exzh":"I will obey his orders.","example:818:exzh2":"Please be sure to follow this order.","example:818:exzh3":"It's the boss who gives the orders.","example:818:exzh4":"She disobeyed the order.","example:818:exzh5":"It's important to understand the orders."},"819":{"example:819:exzh":"He is the person I'm dealing with.","example:819:exzh2":"I respect the other person's opinion.","example:819:exzh3":"The opponent in the match is strong.","example:819:exzh4":"She is a good partner.","example:819:exzh5":"I talk while looking into the other person's eyes."},"820":{"example:820:exzh":"Her voice is very beautiful.","example:820:exzh2":"The sound is too loud and my ears hurt.","example:820:exzh3":"Can you hear your friend's voice?","example:820:exzh4":"Please raise your voice when you speak.","example:820:exzh5":"I can tell who it is just from that voice.","grammar:820:ex:trans":"Her voice is very beautiful.","grammar:820:ex:structure":"〜はとても〜です","grammar:820:ex:explain":"The key point is that 「声（こえ）」 is a voice produced by a person or animal, unlike 「音（おと）」, which is the sound of an object; this sentence is about her singing voice, so 「声」 is used. The pattern is 「〜はとても〜です」: 「とても」 is an adverb that intensifies the degree, and it pairs with the i-adjective 「美しい」 plus 「です」 for the polite form. The topic 「彼女の声」 is presented with 「は」 and then evaluated.","grammar:820:ex:words:0:zh":"she","grammar:820:ex:words:0:note":"かのじょ","grammar:820:ex:words:0:pos":"pronoun","grammar:820:ex:words:1:zh":"'s","grammar:820:ex:words:1:pos":"particle","grammar:820:ex:words:2:zh":"voice","grammar:820:ex:words:2:note":"こえ","grammar:820:ex:words:2:pos":"noun","grammar:820:ex:words:3:zh":"(topic)","grammar:820:ex:words:3:pos":"particle","grammar:820:ex:words:4:zh":"extremely","grammar:820:ex:words:4:pos":"adverb","grammar:820:ex:words:5:zh":"beautiful","grammar:820:ex:words:5:note":"うつくしい","grammar:820:ex:words:5:pos":"adjective","grammar:820:ex:words:6:zh":"(polite form)","grammar:820:ex:words:6:pos":"copula","grammar:820:ex:points:1":"彼女の声: her voice.","grammar:820:ex2:trans":"The voice is too loud, and my ears hurt.","grammar:820:ex2:structure":"〜すぎて、〜が痛い","grammar:820:ex2:words:0:zh":"voice","grammar:820:ex2:words:0:note":"こえ","grammar:820:ex2:words:0:pos":"noun","grammar:820:ex2:words:1:zh":"(nominative)","grammar:820:ex2:words:1:pos":"particle","grammar:820:ex2:words:2:zh":"too loud","grammar:820:ex2:words:2:note":"おおきすぎて","grammar:820:ex2:words:2:pos":"adjective","grammar:820:ex2:words:3:zh":"ears","grammar:820:ex2:words:3:note":"みみ","grammar:820:ex2:words:3:pos":"noun","grammar:820:ex2:words:4:zh":"(nominative)","grammar:820:ex2:words:4:pos":"particle","grammar:820:ex2:words:5:zh":"hurt / painful","grammar:820:ex2:words:5:note":"いたい","grammar:820:ex2:words:5:pos":"adjective","grammar:820:ex2:points:0":"❗〜すぎる: too … (大きい→大きすぎる).","grammar:820:ex2:points:1":"〜て: cause and effect (too loud, so it hurts).","grammar:820:ex3:trans":"Can you hear your friend's voice?","grammar:820:ex3:structure":"〜が聞こえますか","grammar:820:ex3:words:0:zh":"friend","grammar:820:ex3:words:0:note":"ともだち","grammar:820:ex3:words:0:pos":"noun","grammar:820:ex3:words:1:zh":"'s","grammar:820:ex3:words:1:pos":"particle","grammar:820:ex3:words:2:zh":"voice","grammar:820:ex3:words:2:note":"こえ","grammar:820:ex3:words:2:pos":"noun","grammar:820:ex3:words:3:zh":"(nominative)","grammar:820:ex3:words:3:pos":"particle","grammar:820:ex3:words:4:zh":"can hear","grammar:820:ex3:words:4:note":"きこえます","grammar:820:ex3:words:4:pos":"verb","grammar:820:ex3:words:5:zh":"(question)","grammar:820:ex3:words:5:pos":"particle","grammar:820:ex3:points:0":"声が聞こえる: to hear a voice (an intransitive verb, so the thing heard takes が).","grammar:820:ex3:points:1":"友達の声: a friend's voice.","grammar:820:ex4:trans":"Please raise your voice when you speak.","grammar:820:ex4:structure":"〜を高めて話してください","grammar:820:ex4:words:0:zh":"voice","grammar:820:ex4:words:0:note":"こえ","grammar:820:ex4:words:0:pos":"noun","grammar:820:ex4:words:1:zh":"(object marker)","grammar:820:ex4:words:1:pos":"particle","grammar:820:ex4:words:2:zh":"raise","grammar:820:ex4:words:2:note":"たかめて","grammar:820:ex4:words:2:pos":"verb","grammar:820:ex4:words:3:zh":"tell","grammar:820:ex4:words:3:note":"はなして","grammar:820:ex4:words:3:pos":"verb","grammar:820:ex4:words:4:zh":"please","grammar:820:ex4:words:4:pos":"auxiliary verb","grammar:820:ex4:points:0":"❗声を高める: to raise your voice.","grammar:820:ex4:points:1":"〜て: te-form link (raise + speak).","grammar:820:ex5:trans":"Just from that voice, I can tell who it is.","grammar:820:ex5:structure":"その〜で〜だかわかる","grammar:820:ex5:words:0:zh":"that","grammar:820:ex5:words:0:pos":"pre-noun adjectival","grammar:820:ex5:words:1:zh":"voice","grammar:820:ex5:words:1:note":"こえ","grammar:820:ex5:words:1:pos":"noun","grammar:820:ex5:words:2:zh":"(means)","grammar:820:ex5:words:2:pos":"particle","grammar:820:ex5:words:3:zh":"who","grammar:820:ex5:words:3:note":"だれ","grammar:820:ex5:words:3:pos":"question word","grammar:820:ex5:words:4:zh":"is","grammar:820:ex5:words:4:pos":"copula","grammar:820:ex5:words:5:zh":"(uncertainty)","grammar:820:ex5:words:5:pos":"particle","grammar:820:ex5:words:6:zh":"know","grammar:820:ex5:words:6:pos":"verb","grammar:820:ex5:points:0":"❓で: by means of … (means); その声で = from that voice.","grammar:820:ex5:points:1":"〜だかわかる: to know who it is."},"821":{"example:821:exzh":"He is the king of the country.","example:821:exzh2":"The king has the responsibility to govern the country.","example:821:exzh3":"The king's words carry weight.","example:821:exzh4":"The king of long ago started a war.","example:821:exzh5":"Do you know about that legendary king?"},"823":{"example:823:exzh":"I'll give you my frank opinion.","example:823:exzh2":"She is cold toward me.","example:823:exzh3":"The answer to this problem is simple.","example:823:exzh4":"Education for children is important.","example:823:exzh5":"There are various opinions on that topic."},"824":{"example:824:exzh":"Many people are watching this movie.","example:824:exzh2":"This product is popular with many people.","example:824:exzh3":"Many students passed the exam.","example:824:exzh4":"It's important to gain a lot of experience.","example:824:exzh5":"There are many plants here.","grammar:824:ex:trans":"Many people are watching this movie.","grammar:824:ex:structure":"多くの〜が〜ています","grammar:824:ex:explain":"Two key points. First, 「多くの＋名詞」 is the written-style way to say many … (more formal than the casual 「たくさんの」). Second, 「〜ている」 is the progressive form: the te-form of the verb 「見る」, 「見て」, plus 「いる」, showing an action in progress or continuing; here it means they are watching, or are all watching. The subject 「多くの人」 is marked with 「が」, and the object 「映画」 with 「を」.","grammar:824:ex:words:0:zh":"a lot","grammar:824:ex:words:0:note":"おおく","grammar:824:ex:words:0:pos":"noun","grammar:824:ex:words:1:zh":"'s","grammar:824:ex:words:1:pos":"particle","grammar:824:ex:words:2:zh":"person","grammar:824:ex:words:2:note":"ひと","grammar:824:ex:words:2:pos":"noun","grammar:824:ex:words:3:zh":"(nominative)","grammar:824:ex:words:3:pos":"particle","grammar:824:ex:words:4:zh":"this","grammar:824:ex:words:4:pos":"pre-noun adjectival","grammar:824:ex:words:5:zh":"movie","grammar:824:ex:words:5:note":"えいが","grammar:824:ex:words:5:pos":"noun","grammar:824:ex:words:6:zh":"(object marker)","grammar:824:ex:words:6:pos":"particle","grammar:824:ex:words:7:zh":"watching","grammar:824:ex:words:7:note":"みています","grammar:824:ex:words:7:pos":"verb","grammar:824:ex:points:0":"❗多くの＋noun: many … (written usage).","grammar:824:ex:points:1":"〜ている: (is) continuing; in progress.","grammar:824:ex2:trans":"This product is popular with many people.","grammar:824:ex2:structure":"〜に人気です","grammar:824:ex2:words:0:zh":"this","grammar:824:ex2:words:0:pos":"pre-noun adjectival","grammar:824:ex2:words:1:zh":"product","grammar:824:ex2:words:1:note":"しょうひん","grammar:824:ex2:words:1:pos":"noun","grammar:824:ex2:words:2:zh":"(topic)","grammar:824:ex2:words:2:pos":"particle","grammar:824:ex2:words:3:zh":"a lot","grammar:824:ex2:words:3:note":"おおく","grammar:824:ex2:words:3:pos":"noun","grammar:824:ex2:words:4:zh":"'s","grammar:824:ex2:words:4:pos":"particle","grammar:824:ex2:words:5:zh":"person","grammar:824:ex2:words:5:note":"ひと","grammar:824:ex2:words:5:pos":"noun","grammar:824:ex2:words:6:zh":"(object)","grammar:824:ex2:words:6:pos":"particle","grammar:824:ex2:words:7:zh":"popularity","grammar:824:ex2:words:7:note":"にんき","grammar:824:ex2:words:7:pos":"noun","grammar:824:ex2:words:8:zh":"(polite form)","grammar:824:ex2:words:8:pos":"copula","grammar:824:ex2:points:0":"❗〜に人気: popular with … (the target takes に).","grammar:824:ex2:points:1":"多くの人に: with many people; among many people.","grammar:824:ex3:trans":"Many students passed the exam.","grammar:824:ex3:structure":"〜に合格しました","grammar:824:ex3:words:0:zh":"a lot","grammar:824:ex3:words:0:note":"おおく","grammar:824:ex3:words:0:pos":"noun","grammar:824:ex3:words:1:zh":"'s","grammar:824:ex3:words:1:pos":"particle","grammar:824:ex3:words:2:zh":"student","grammar:824:ex3:words:2:note":"がくせい","grammar:824:ex3:words:2:pos":"noun","grammar:824:ex3:words:3:zh":"(nominative)","grammar:824:ex3:words:3:pos":"particle","grammar:824:ex3:words:4:zh":"test","grammar:824:ex3:words:4:note":"しけん","grammar:824:ex3:words:4:pos":"noun","grammar:824:ex3:words:5:zh":"(object)","grammar:824:ex3:words:5:pos":"particle","grammar:824:ex3:words:6:zh":"passed","grammar:824:ex3:words:6:note":"ごうかくしました","grammar:824:ex3:words:6:pos":"verb","grammar:824:ex3:points:0":"❗〜に合格する: pass … (an exam) (the target takes に).","grammar:824:ex3:points:1":"多くの学生: many students.","grammar:824:ex4:trans":"It's important to build up a lot of experience.","grammar:824:ex4:structure":"〜ことが大切です","grammar:824:ex4:words:0:zh":"a lot","grammar:824:ex4:words:0:note":"おおく","grammar:824:ex4:words:0:pos":"noun","grammar:824:ex4:words:1:zh":"'s","grammar:824:ex4:words:1:pos":"particle","grammar:824:ex4:words:2:zh":"experience","grammar:824:ex4:words:2:note":"けいけん","grammar:824:ex4:words:2:pos":"noun","grammar:824:ex4:words:3:zh":"(object marker)","grammar:824:ex4:words:3:pos":"particle","grammar:824:ex4:words:4:zh":"build up","grammar:824:ex4:words:4:note":"つむ","grammar:824:ex4:words:4:pos":"verb","grammar:824:ex4:words:5:zh":"(nominalizer)","grammar:824:ex4:words:5:pos":"noun","grammar:824:ex4:words:6:zh":"(nominative)","grammar:824:ex4:words:6:pos":"particle","grammar:824:ex4:words:7:zh":"important","grammar:824:ex4:words:7:note":"たいせつ","grammar:824:ex4:words:7:pos":"na-adjective","grammar:824:ex4:words:8:zh":"(polite form)","grammar:824:ex4:words:8:pos":"copula","grammar:824:ex4:points:0":"❗経験を積む: build up experience (fixed expression; uses 積む).","grammar:824:ex4:points:1":"〜ことが大切です: doing … is important.","grammar:824:ex5:trans":"There are many plants here.","grammar:824:ex5:structure":"〜には〜があります (〜 has 〜)","grammar:824:ex5:words:0:zh":"here","grammar:824:ex5:words:0:pos":"pronoun","grammar:824:ex5:words:1:zh":"(location of existence)","grammar:824:ex5:words:1:pos":"particle","grammar:824:ex5:words:2:zh":"(contrast)","grammar:824:ex5:words:2:pos":"particle","grammar:824:ex5:words:3:zh":"a lot","grammar:824:ex5:words:3:note":"おおく","grammar:824:ex5:words:3:pos":"noun","grammar:824:ex5:words:4:zh":"'s","grammar:824:ex5:words:4:pos":"particle","grammar:824:ex5:words:5:zh":"plant","grammar:824:ex5:words:5:note":"しょくぶつ","grammar:824:ex5:words:5:pos":"noun","grammar:824:ex5:words:6:zh":"(nominative)","grammar:824:ex5:words:6:pos":"particle","grammar:824:ex5:words:7:zh":"there is / are","grammar:824:ex5:words:7:pos":"verb","grammar:824:ex5:points:0":"多くの植物: many plants.","grammar:824:ex5:points:1":"〜には〜がある: … has…, there is… in…"},"826":{"example:826:exzh":"I value my own experience.","example:826:exzh2":"She has confidence in herself.","example:826:exzh3":"Personal growth is important.","example:826:exzh4":"In reality, personal effort is what's needed.","example:826:exzh5":"Do you know your own worth?"},"827":{"example:827:exzh":"Friends, family, and others gathered together.","example:827:exzh2":"I bought fruit and vegetables and so on.","example:827:exzh3":"He, she, and others are my close friends.","example:827:exzh4":"I want to go to places like Japan and China.","example:827:exzh5":"I like movies and music and things like that.","grammar:827:ex:trans":"Friends, family, and others got together.","grammar:827:ex:structure":"〜や〜などが〜ました","grammar:827:ex:explain":"The key is the listing pattern 「〜や〜など」. 「や」 links items as examples, implying that others are not listed — unlike 「と」, which lists everything completely. It often pairs with 「など」 (etc.) at the end to reinforce that the list is not exhaustive. So 「友達や家族など」 means friends, family, and others besides. The past polite form of the verb 「集まる」, 「集まりました」, shows that they have already gathered.","grammar:827:ex:words:0:zh":"friend","grammar:827:ex:words:0:note":"ともだち","grammar:827:ex:words:0:pos":"noun","grammar:827:ex:words:1:zh":"and (listing)","grammar:827:ex:words:1:pos":"particle","grammar:827:ex:words:2:zh":"family","grammar:827:ex:words:2:note":"かぞく","grammar:827:ex:words:2:pos":"noun","grammar:827:ex:words:3:zh":"etc.","grammar:827:ex:words:3:pos":"particle","grammar:827:ex:words:4:zh":"(nominative)","grammar:827:ex:words:4:pos":"particle","grammar:827:ex:words:5:zh":"gathered","grammar:827:ex:words:5:note":"あつまりました","grammar:827:ex:words:5:pos":"verb","grammar:827:ex:points:0":"❗〜や〜など: … and … etc. (not a complete list; や pairs with など).","grammar:827:ex:points:1":"集まる→集まりました.","grammar:827:ex2:trans":"I bought fruit, vegetables, and so on.","grammar:827:ex2:structure":"〜や〜などを買いました","grammar:827:ex2:words:0:zh":"fruit","grammar:827:ex2:words:0:note":"loanword","grammar:827:ex2:words:0:pos":"noun","grammar:827:ex2:words:1:zh":"with","grammar:827:ex2:words:1:pos":"particle","grammar:827:ex2:words:2:zh":"vegetables","grammar:827:ex2:words:2:note":"やさい","grammar:827:ex2:words:2:pos":"noun","grammar:827:ex2:words:3:zh":"etc.","grammar:827:ex2:words:3:pos":"particle","grammar:827:ex2:words:4:zh":"(object marker)","grammar:827:ex2:words:4:pos":"particle","grammar:827:ex2:words:5:zh":"bought","grammar:827:ex2:words:5:note":"かいました","grammar:827:ex2:words:5:pos":"verb","grammar:827:ex2:points:0":"フルーツや野菜など: fruit, vegetables, etc.","grammar:827:ex2:points:1":"〜など: things like …; etc.","grammar:827:ex3:trans":"He, she, and others are my closest friends.","grammar:827:ex3:structure":"〜や〜などは〜です","grammar:827:ex3:words:0:zh":"he","grammar:827:ex3:words:0:note":"かれ","grammar:827:ex3:words:0:pos":"pronoun","grammar:827:ex3:words:1:zh":"with","grammar:827:ex3:words:1:pos":"particle","grammar:827:ex3:words:2:zh":"she","grammar:827:ex3:words:2:note":"かのじょ","grammar:827:ex3:words:2:pos":"pronoun","grammar:827:ex3:words:3:zh":"wait","grammar:827:ex3:words:3:pos":"particle","grammar:827:ex3:words:4:zh":"(topic)","grammar:827:ex3:words:4:pos":"particle","grammar:827:ex3:words:5:zh":"I","grammar:827:ex3:words:5:note":"わたし","grammar:827:ex3:words:5:pos":"pronoun","grammar:827:ex3:words:6:zh":"'s","grammar:827:ex3:words:6:pos":"particle","grammar:827:ex3:words:7:zh":"close friend","grammar:827:ex3:words:7:note":"しんゆう","grammar:827:ex3:words:7:pos":"noun","grammar:827:ex3:words:8:zh":"is","grammar:827:ex3:words:8:pos":"copula","grammar:827:ex3:points:0":"彼や彼女など: he, she, and others.","grammar:827:ex3:points:1":"親友: close friend; good friend.","grammar:827:ex4:trans":"I want to go to Japan, China, and other places.","grammar:827:ex4:structure":"〜や〜などに行きたいです","grammar:827:ex4:words:0:zh":"Japan","grammar:827:ex4:words:0:note":"にほん","grammar:827:ex4:words:0:pos":"noun","grammar:827:ex4:words:1:zh":"with","grammar:827:ex4:words:1:pos":"particle","grammar:827:ex4:words:2:zh":"China","grammar:827:ex4:words:2:note":"ちゅうごく","grammar:827:ex4:words:2:pos":"noun","grammar:827:ex4:words:3:zh":"wait","grammar:827:ex4:words:3:pos":"particle","grammar:827:ex4:words:4:zh":"(destination)","grammar:827:ex4:words:4:pos":"particle","grammar:827:ex4:words:5:zh":"want to go","grammar:827:ex4:words:5:note":"いきたい","grammar:827:ex4:words:5:pos":"verb","grammar:827:ex4:words:6:zh":"(polite form)","grammar:827:ex4:words:6:pos":"copula","grammar:827:ex4:points:0":"日本や中国など: Japan, China, etc.","grammar:827:ex4:points:1":"〜たい: to want to ….","grammar:827:ex5:trans":"I like movies, music, and so on.","grammar:827:ex5:structure":"〜や〜などが好きです","grammar:827:ex5:words:0:zh":"movie","grammar:827:ex5:words:0:note":"えいが","grammar:827:ex5:words:0:pos":"noun","grammar:827:ex5:words:1:zh":"with","grammar:827:ex5:words:1:pos":"particle","grammar:827:ex5:words:2:zh":"music","grammar:827:ex5:words:2:note":"おんがく","grammar:827:ex5:words:2:pos":"noun","grammar:827:ex5:words:3:zh":"wait","grammar:827:ex5:words:3:pos":"particle","grammar:827:ex5:words:4:zh":"(object)","grammar:827:ex5:words:4:pos":"particle","grammar:827:ex5:words:5:zh":"to like","grammar:827:ex5:words:5:note":"すき","grammar:827:ex5:words:5:pos":"na-adjective","grammar:827:ex5:words:6:zh":"(polite form)","grammar:827:ex5:words:6:pos":"copula","grammar:827:ex5:points:0":"映画や音楽など: movies, music, etc.","grammar:827:ex5:points:1":"〜が好き: to like …"},"829":{"example:829:exzh":"Today was a rough day.","example:829:exzh2":"Something troublesome happened.","example:829:exzh3":"I'm very sorry to have kept you waiting.","example:829:exzh4":"This is a troublesome problem.","example:829:exzh5":"Help is needed in a tough situation.","grammar:829:ex:trans":"Today was a rough day.","grammar:829:ex:structure":"〜は大変な〜でした","grammar:829:ex:explain":"「大変（たいへん）」 has two uses: as a na-adjective it means tough, awful, or terrible, and as an adverb it means very. Here it is the na-adjective use; before a noun it takes 「な」 to become 「大変な一日」, meaning a tough, terrible day. The ending 「でした」 is the past form of 「です」, because the sentence is about the overall feeling of a day that has already passed — like saying today was an exhausting day.","grammar:829:ex:words:0:zh":"today","grammar:829:ex:words:0:note":"きょう","grammar:829:ex:words:0:pos":"noun","grammar:829:ex:words:1:zh":"(topic)","grammar:829:ex:words:1:pos":"particle","grammar:829:ex:words:2:zh":"tough","grammar:829:ex:words:2:note":"たいへん","grammar:829:ex:words:2:pos":"na-adjective","grammar:829:ex:words:3:zh":"(attributive form)","grammar:829:ex:words:3:pos":"auxiliary verb","grammar:829:ex:words:4:zh":"one day","grammar:829:ex:words:4:note":"いちにち","grammar:829:ex:words:4:pos":"noun","grammar:829:ex:words:5:zh":"(past) was","grammar:829:ex:words:5:pos":"copula","grammar:829:ex:points:0":"❗大変（たいへん）: tough, awful (na-adjective); also an adverb meaning very.","grammar:829:ex:points:1":"大変な一日: a rough / tough day.","grammar:829:ex2:trans":"Something terrible happened.","grammar:829:ex2:structure":"大変なことが起こりました","grammar:829:ex2:words:0:zh":"trouble","grammar:829:ex2:words:0:note":"たいへん","grammar:829:ex2:words:0:pos":"na-adjective","grammar:829:ex2:words:1:zh":"(attributive form)","grammar:829:ex2:words:1:pos":"auxiliary verb","grammar:829:ex2:words:2:zh":"thing / matter","grammar:829:ex2:words:2:pos":"noun","grammar:829:ex2:words:3:zh":"(nominative)","grammar:829:ex2:words:3:pos":"particle","grammar:829:ex2:words:4:zh":"occurred","grammar:829:ex2:words:4:note":"おこりました","grammar:829:ex2:words:4:pos":"verb","grammar:829:ex2:points:0":"大変なこと: something terrible / serious.","grammar:829:ex2:points:1":"起こる: to happen (intransitive verb).","grammar:829:ex3:trans":"I'm sorry to keep you waiting.","grammar:829:ex3:structure":"大変〜しました","grammar:829:ex3:words:0:zh":"extremely","grammar:829:ex3:words:0:note":"たいへん","grammar:829:ex3:words:0:pos":"adverb","grammar:829:ex3:words:1:zh":"keep you waiting","grammar:829:ex3:words:1:note":"おまたせしました","grammar:829:ex3:words:1:pos":"set phrase","grammar:829:ex3:points:0":"❗大変 (adverb): very; extremely.","grammar:829:ex3:points:1":"お待たせしました: sorry to keep you waiting (humble, kenjōgo).","grammar:829:ex4:trans":"This is a serious problem.","grammar:829:ex4:structure":"これは大変な〜です","grammar:829:ex4:words:0:zh":"this","grammar:829:ex4:words:0:pos":"pronoun","grammar:829:ex4:words:1:zh":"(topic)","grammar:829:ex4:words:1:pos":"particle","grammar:829:ex4:words:2:zh":"trouble","grammar:829:ex4:words:2:note":"たいへん","grammar:829:ex4:words:2:pos":"na-adjective","grammar:829:ex4:words:3:zh":"(attributive form)","grammar:829:ex4:words:3:pos":"auxiliary verb","grammar:829:ex4:words:4:zh":"problem","grammar:829:ex4:words:4:note":"もんだい","grammar:829:ex4:words:4:pos":"noun","grammar:829:ex4:words:5:zh":"is","grammar:829:ex4:words:5:pos":"copula","grammar:829:ex4:points:0":"大変な問題: a troublesome problem.","grammar:829:ex4:points:1":"これは: this is.","grammar:829:ex5:trans":"Help is needed in a difficult situation.","grammar:829:ex5:structure":"大変な〜で〜が必要です","grammar:829:ex5:words:0:zh":"difficult","grammar:829:ex5:words:0:note":"たいへん","grammar:829:ex5:words:0:pos":"na-adjective","grammar:829:ex5:words:1:zh":"(attributive form)","grammar:829:ex5:words:1:pos":"auxiliary verb","grammar:829:ex5:words:2:zh":"case","grammar:829:ex5:words:2:note":"じょうきょう","grammar:829:ex5:words:2:pos":"noun","grammar:829:ex5:words:3:zh":"(a state)","grammar:829:ex5:words:3:pos":"particle","grammar:829:ex5:words:4:zh":"help","grammar:829:ex5:words:4:note":"たすけ","grammar:829:ex5:words:4:pos":"noun","grammar:829:ex5:words:5:zh":"(nominative)","grammar:829:ex5:words:5:pos":"particle","grammar:829:ex5:words:6:zh":"necessary","grammar:829:ex5:words:6:note":"ひつよう","grammar:829:ex5:words:6:pos":"na-adjective","grammar:829:ex5:words:7:zh":"(polite form)","grammar:829:ex5:words:7:pos":"copula","grammar:829:ex5:points:0":"大変な状況: a difficult situation.","grammar:829:ex5:points:1":"助けが必要: help is needed."},"830":{"example:830:exzh":"His mouth is big.","example:830:exzh2":"I eat food with my mouth.","example:830:exzh3":"Please close your mouth.","example:830:exzh4":"She has beautiful lips.","example:830:exzh5":"My mouth is dry.","grammar:830:ex:trans":"He has a big mouth.","grammar:830:ex:structure":"〜は〜が大きいです","grammar:830:ex:explain":"This sentence shows the typical Japanese pattern for describing a physical feature: the topic 「は」 introduces the person (彼は), 「が」 brings out the specific part (口が), and the adjective comes last (大きい). This double structure — big topic は + small subject が + adjective — is very common; 「彼は背が高い」 works the same way. 「口（くち）」 means mouth, so 「口が大きい」 literally means having a big mouth, and it can also suggest someone who likes to boast.","grammar:830:ex:words:0:zh":"he","grammar:830:ex:words:0:note":"かれ","grammar:830:ex:words:0:pos":"pronoun","grammar:830:ex:words:1:zh":"(topic)","grammar:830:ex:words:1:pos":"particle","grammar:830:ex:words:2:zh":"mouth","grammar:830:ex:words:2:note":"くち","grammar:830:ex:words:2:pos":"noun","grammar:830:ex:words:3:zh":"(nominative)","grammar:830:ex:words:3:pos":"particle","grammar:830:ex:words:4:zh":"big","grammar:830:ex:words:4:note":"おおきい","grammar:830:ex:words:4:pos":"adjective","grammar:830:ex:words:5:zh":"(polite form)","grammar:830:ex:words:5:pos":"copula","grammar:830:ex:points:0":"❗口（くち）: mouth.","grammar:830:ex:points:1":"❗For a body part being big, use 〜が大きい（口が大きい）.","grammar:830:ex2:trans":"Eat food with your mouth.","grammar:830:ex2:structure":"〜から〜を食べます","grammar:830:ex2:words:0:zh":"mouth","grammar:830:ex2:words:0:note":"くち","grammar:830:ex2:words:0:pos":"noun","grammar:830:ex2:words:1:zh":"from","grammar:830:ex2:words:1:pos":"particle","grammar:830:ex2:words:2:zh":"food","grammar:830:ex2:words:2:note":"たべもの","grammar:830:ex2:words:2:pos":"noun","grammar:830:ex2:words:3:zh":"(object marker)","grammar:830:ex2:words:3:pos":"particle","grammar:830:ex2:words:4:zh":"eat","grammar:830:ex2:words:4:pos":"verb","grammar:830:ex2:points:0":"口から: from the mouth (から marks the starting point).","grammar:830:ex2:points:1":"食べ物を食べる: eat food.","grammar:830:ex3:trans":"Please close your mouth.","grammar:830:ex3:structure":"〜を閉じてください","grammar:830:ex3:words:0:zh":"mouth","grammar:830:ex3:words:0:note":"くち","grammar:830:ex3:words:0:pos":"noun","grammar:830:ex3:words:1:zh":"(object marker)","grammar:830:ex3:words:1:pos":"particle","grammar:830:ex3:words:2:zh":"close","grammar:830:ex3:words:2:note":"とじて","grammar:830:ex3:words:2:pos":"verb","grammar:830:ex3:words:3:zh":"please","grammar:830:ex3:words:3:pos":"auxiliary verb","grammar:830:ex3:points:0":"❗口を閉じる: close one's mouth (閉じる is a transitive verb).","grammar:830:ex3:points:1":"閉じる → 閉じて ＋ ください.","grammar:830:ex4:trans":"She has a beautiful mouth.","grammar:830:ex4:structure":"〜を持っています (has 〜)","grammar:830:ex4:words:0:zh":"she","grammar:830:ex4:words:0:note":"かのじょ","grammar:830:ex4:words:0:pos":"pronoun","grammar:830:ex4:words:1:zh":"(topic)","grammar:830:ex4:words:1:pos":"particle","grammar:830:ex4:words:2:zh":"beautiful","grammar:830:ex4:words:2:note":"うつくしい","grammar:830:ex4:words:2:pos":"adjective","grammar:830:ex4:words:3:zh":"mouth","grammar:830:ex4:words:3:note":"くち","grammar:830:ex4:words:3:pos":"noun","grammar:830:ex4:words:4:zh":"(object marker)","grammar:830:ex4:words:4:pos":"particle","grammar:830:ex4:words:5:zh":"own, have","grammar:830:ex4:words:5:note":"もっています","grammar:830:ex4:words:5:pos":"verb","grammar:830:ex4:points:0":"美しい口: a beautiful mouth.","grammar:830:ex4:points:1":"〜を持っている: to have….","grammar:830:ex5:trans":"My mouth got dry.","grammar:830:ex5:structure":"〜が乾いた","grammar:830:ex5:words:0:zh":"mouth","grammar:830:ex5:words:0:note":"くち","grammar:830:ex5:words:0:pos":"noun","grammar:830:ex5:words:1:zh":"(nominative)","grammar:830:ex5:words:1:pos":"particle","grammar:830:ex5:words:2:zh":"dried","grammar:830:ex5:words:2:note":"かわいた","grammar:830:ex5:words:2:pos":"verb","grammar:830:ex5:points:0":"❗口が乾く: to be thirsty, to have a dry mouth (intransitive verb, takes が).","grammar:830:ex5:points:1":"乾く→乾いた。","exam:830:zh":"The dentist is going to look at your teeth, so please open your mouth wide.","exam:830:why":"For the dentist to check your teeth you need to open your 「口」 (mouth). 「目」 can also go with 「開ける」, but opening your eyes doesn't let the dentist see your teeth."},"831":{"example:831:exzh":"There is a desk at the back of that room.","example:831:exzh2":"I hid it in the back.","example:831:exzh3":"Deep in the mountains there is a beautiful lake.","example:831:exzh4":"I want to explore the inside.","example:831:exzh5":"What's inside the box?"},"832":{"example:832:exzh":"Let's go over there.","example:832:exzh2":"It's quiet over there.","example:832:exzh3":"There's a supermarket over there.","example:832:exzh4":"A friend is over there.","example:832:exzh5":"The scenery is beautiful over there.","grammar:832:ex:trans":"Let's go over there.","grammar:832:ex:structure":"あそこに行きましょう","grammar:832:ex:explain":"「あそこ」 is a demonstrative pronoun from the 「あ」 group of the 「こそあど」 system, meaning over there — far from both the speaker and the listener. In the pattern 「〜に行きましょう」, 「に」 marks the destination, and 「行きましょう」 is the polite volitional form of 「行く」, used to invite someone: let's go …. The whole sentence invites the other person to go to that place.","grammar:832:ex:words:0:zh":"there","grammar:832:ex:words:0:pos":"pronoun","grammar:832:ex:words:1:zh":"(destination)","grammar:832:ex:words:1:pos":"particle","grammar:832:ex:words:2:zh":"let's go","grammar:832:ex:words:2:note":"いきましょう","grammar:832:ex:words:2:pos":"verb","grammar:832:ex:points:0":"❗あそこ: over there (far from both speaker and listener; こそあど).","grammar:832:ex:points:1":"〜に行きましょう: let's go to ….","grammar:832:ex2:trans":"It's quiet over there.","grammar:832:ex2:structure":"あそこは〜です","grammar:832:ex2:words:0:zh":"there","grammar:832:ex2:words:0:pos":"pronoun","grammar:832:ex2:words:1:zh":"(topic)","grammar:832:ex2:words:1:pos":"particle","grammar:832:ex2:words:2:zh":"quiet","grammar:832:ex2:words:2:note":"しずか","grammar:832:ex2:words:2:pos":"na-adjective","grammar:832:ex2:words:3:zh":"(polite form)","grammar:832:ex2:words:3:pos":"copula","grammar:832:ex2:points:0":"あそこは: over there (topic).","grammar:832:ex2:points:1":"静か: quiet.","grammar:832:ex3:trans":"There's a supermarket over there.","grammar:832:ex3:structure":"あそこに〜があります","grammar:832:ex3:words:0:zh":"there","grammar:832:ex3:words:0:pos":"pronoun","grammar:832:ex3:words:1:zh":"(location of existence)","grammar:832:ex3:words:1:pos":"particle","grammar:832:ex3:words:2:zh":"supermarket","grammar:832:ex3:words:2:note":"loanword","grammar:832:ex3:words:2:pos":"noun","grammar:832:ex3:words:3:zh":"(nominative)","grammar:832:ex3:words:3:pos":"particle","grammar:832:ex3:words:4:zh":"there is / are","grammar:832:ex3:words:4:pos":"verb","grammar:832:ex3:points:0":"スーパー: supermarket.","grammar:832:ex3:points:1":"〜にあります: be at/in … (inanimate things).","grammar:832:ex4:trans":"A friend is over there.","grammar:832:ex4:structure":"あそこに〜がいます","grammar:832:ex4:words:0:zh":"there","grammar:832:ex4:words:0:pos":"pronoun","grammar:832:ex4:words:1:zh":"(location of existence)","grammar:832:ex4:words:1:pos":"particle","grammar:832:ex4:words:2:zh":"friend","grammar:832:ex4:words:2:note":"ともだち","grammar:832:ex4:words:2:pos":"noun","grammar:832:ex4:words:3:zh":"(nominative)","grammar:832:ex4:words:3:pos":"particle","grammar:832:ex4:words:4:zh":"there is / are","grammar:832:ex4:words:4:pos":"verb","grammar:832:ex4:points:0":"友達 (a person) → います.","grammar:832:ex4:points:1":"あそこに: over there.","grammar:832:ex5:trans":"The scenery there is beautiful.","grammar:832:ex5:structure":"あそこは〜がきれいです","grammar:832:ex5:words:0:zh":"there","grammar:832:ex5:words:0:pos":"pronoun","grammar:832:ex5:words:1:zh":"(topic)","grammar:832:ex5:words:1:pos":"particle","grammar:832:ex5:words:2:zh":"scenery","grammar:832:ex5:words:2:note":"けしき","grammar:832:ex5:words:2:pos":"noun","grammar:832:ex5:words:3:zh":"(nominative)","grammar:832:ex5:words:3:pos":"particle","grammar:832:ex5:words:4:zh":"beautiful","grammar:832:ex5:words:4:pos":"na-adjective","grammar:832:ex5:words:5:zh":"(polite form)","grammar:832:ex5:words:5:pos":"copula","grammar:832:ex5:points:0":"景色がきれい: beautiful scenery (the subject takes が).","grammar:832:ex5:points:1":"あそこは: over there (topic).","exam:832:zh":"It's far from both me and you, but you can see a red bridge over there.","exam:832:why":"「あそこ」 refers to a place far from both the speaker and the listener. 「そこ」 usually refers to a place near the listener, which doesn't fit the distance cue here."},"833":{"example:833:exzh":"It's hard to know the truth.","example:833:exzh2":"He told the truth.","example:833:exzh3":"The truth sometimes hurts.","example:833:exzh4":"I didn't notice that truth.","example:833:exzh5":"It's important to face the truth."},"834":{"example:834:exzh":"Please check that record.","example:834:exzh2":"Keeping records is important.","example:834:exzh3":"He set a new record.","example:834:exzh4":"This record is important.","example:834:exzh5":"It's important to keep a record."},"835":{"example:835:exzh":"War is a sad event.","example:835:exzh2":"History teaches us about war.","example:835:exzh3":"He likes war movies.","example:835:exzh4":"War changes people's lives.","example:835:exzh5":"Let's talk about war."},"836":{"example:836:exzh":"He intends to decide the outcome of the match.","example:836:exzh2":"Let's decide the important matters at the meeting.","example:836:exzh3":"She places importance on her mother's opinion when deciding.","example:836:exzh4":"We need to decide on the trip plan soon.","example:836:exzh5":"Deciding on a new job isn't easy.","grammar:836:ex:trans":"He intends to decide the outcome of the match.","grammar:836:ex:structure":"〜を決めるつもりだ","grammar:836:ex:explain":"Two key points. First, the transitive verb 「決める」 (to decide …) takes 「を」 for the thing acted on, and pairs with the intransitive 「決まる」 (to be decided, to be settled); use 「決める」 when someone actively decides. Second, 「〜つもりだ」 expresses the speaker's intention and follows the dictionary form of a verb. The whole sentence means: he intends to decide the match result himself.","grammar:836:ex:words:0:zh":"he","grammar:836:ex:words:0:note":"かれ","grammar:836:ex:words:0:pos":"pronoun","grammar:836:ex:words:1:zh":"(topic)","grammar:836:ex:words:1:pos":"particle","grammar:836:ex:words:2:zh":"competition","grammar:836:ex:words:2:note":"しあい","grammar:836:ex:words:2:pos":"noun","grammar:836:ex:words:3:zh":"'s","grammar:836:ex:words:3:pos":"particle","grammar:836:ex:words:4:zh":"result","grammar:836:ex:words:4:note":"けっか","grammar:836:ex:words:4:pos":"noun","grammar:836:ex:words:5:zh":"(object marker)","grammar:836:ex:words:5:pos":"particle","grammar:836:ex:words:6:zh":"decide","grammar:836:ex:words:6:note":"きめる","grammar:836:ex:words:6:pos":"verb","grammar:836:ex:words:7:zh":"intend to","grammar:836:ex:words:7:pos":"noun","grammar:836:ex:words:8:zh":"is","grammar:836:ex:words:8:pos":"copula","grammar:836:ex:points:0":"❗決める (transitive verb, to decide …) + を; vs 決まる (intransitive verb, to be decided).","grammar:836:ex:points:1":"〜つもりだ: intend to ….","grammar:836:ex2:trans":"Let's decide the important matters at the meeting.","grammar:836:ex2:structure":"〜で〜を決めましょう","grammar:836:ex2:words:0:zh":"meeting","grammar:836:ex2:words:0:note":"かいぎ","grammar:836:ex2:words:0:pos":"noun","grammar:836:ex2:words:1:zh":"(place)","grammar:836:ex2:words:1:pos":"particle","grammar:836:ex2:words:2:zh":"important","grammar:836:ex2:words:2:note":"じゅうよう","grammar:836:ex2:words:2:pos":"na-adjective","grammar:836:ex2:words:3:zh":"(attributive form)","grammar:836:ex2:words:3:pos":"auxiliary verb","grammar:836:ex2:words:4:zh":"thing / matter","grammar:836:ex2:words:4:pos":"noun","grammar:836:ex2:words:5:zh":"(object marker)","grammar:836:ex2:words:5:pos":"particle","grammar:836:ex2:words:6:zh":"let's decide","grammar:836:ex2:words:6:note":"きめましょう","grammar:836:ex2:words:6:pos":"verb","grammar:836:ex2:points:0":"❓会議で: at the meeting (で for place).","grammar:836:ex2:points:1":"〜ましょう: a suggestion.","grammar:836:ex3:trans":"She decides while placing great importance on her mother's opinion.","grammar:836:ex3:structure":"〜を重視して決める","grammar:836:ex3:words:0:zh":"she","grammar:836:ex3:words:0:note":"かのじょ","grammar:836:ex3:words:0:pos":"pronoun","grammar:836:ex3:words:1:zh":"(topic)","grammar:836:ex3:words:1:pos":"particle","grammar:836:ex3:words:2:zh":"mom","grammar:836:ex3:words:2:note":"はは","grammar:836:ex3:words:2:pos":"noun","grammar:836:ex3:words:3:zh":"'s","grammar:836:ex3:words:3:pos":"particle","grammar:836:ex3:words:4:zh":"opinion","grammar:836:ex3:words:4:note":"いけん","grammar:836:ex3:words:4:pos":"noun","grammar:836:ex3:words:5:zh":"(object marker)","grammar:836:ex3:words:5:pos":"particle","grammar:836:ex3:words:6:zh":"to value","grammar:836:ex3:words:6:note":"じゅうしして","grammar:836:ex3:words:6:pos":"verb","grammar:836:ex3:words:7:zh":"decide","grammar:836:ex3:words:7:note":"きめる","grammar:836:ex3:words:7:pos":"verb","grammar:836:ex3:points:0":"❗重視する: to value, to place importance on.","grammar:836:ex3:points:1":"〜して決める: decide (after considering).","grammar:836:ex4:trans":"It's about time we decided on the trip plan.","grammar:836:ex4:structure":"そろそろ〜ないといけない","grammar:836:ex4:words:0:zh":"travel / trip","grammar:836:ex4:words:0:note":"りょこう","grammar:836:ex4:words:0:pos":"noun","grammar:836:ex4:words:1:zh":"'s","grammar:836:ex4:words:1:pos":"particle","grammar:836:ex4:words:2:zh":"plan","grammar:836:ex4:words:2:note":"けいかく","grammar:836:ex4:words:2:pos":"noun","grammar:836:ex4:words:3:zh":"(object marker)","grammar:836:ex4:words:3:pos":"particle","grammar:836:ex4:words:4:zh":"it's about time","grammar:836:ex4:words:4:pos":"adverb","grammar:836:ex4:words:5:zh":"have to decide","grammar:836:ex4:words:5:note":"きめないといけない","grammar:836:ex4:words:5:pos":"verb","grammar:836:ex4:points:0":"❗そろそろ: it's about time to …; 〜ないといけない = must …","grammar:836:ex4:points:1":"計画を決める: decide on a plan.","grammar:836:ex5:trans":"Deciding on a new job isn't easy.","grammar:836:ex5:structure":"〜のは簡単ではない","grammar:836:ex5:words:0:zh":"new","grammar:836:ex5:words:0:note":"あたらしい","grammar:836:ex5:words:0:pos":"adjective","grammar:836:ex5:words:1:zh":"work","grammar:836:ex5:words:1:note":"しごと","grammar:836:ex5:words:1:pos":"noun","grammar:836:ex5:words:2:zh":"(object marker)","grammar:836:ex5:words:2:pos":"particle","grammar:836:ex5:words:3:zh":"decide","grammar:836:ex5:words:3:note":"きめる","grammar:836:ex5:words:3:pos":"verb","grammar:836:ex5:words:4:zh":"(nominalizer)","grammar:836:ex5:words:4:pos":"particle","grammar:836:ex5:words:5:zh":"(topic)","grammar:836:ex5:words:5:pos":"particle","grammar:836:ex5:words:6:zh":"easy","grammar:836:ex5:words:6:note":"かんたん","grammar:836:ex5:words:6:pos":"na-adjective","grammar:836:ex5:words:7:zh":"is not","grammar:836:ex5:words:7:pos":"copula","grammar:836:ex5:points:0":"仕事を決める: decide on a job.","grammar:836:ex5:points:1":"〜のは簡単ではない: doing … isn't easy."},"837":{"example:837:exzh":"He had a checkup at the hospital.","example:837:exzh2":"To get to the hospital, you take the bus from the station.","example:837:exzh3":"There's a café near the hospital.","example:837:exzh4":"A friend came to visit me at the hospital.","example:837:exzh5":"Hospitals can be crowded.","grammar:837:ex:trans":"He had a medical examination at the hospital.","grammar:837:ex:structure":"〜で〜を受けた","grammar:837:ex:explain":"Two key points. First, the fixed collocation 「診察を受ける」: to see a doctor or have a checkup you use the verb 「受ける」 (to receive) — this is the standard way to say it. Second, 「で」 in 「病院で」 marks where the action takes place, at the hospital. Unlike 「に」, which marks where something exists, 「で」 highlights that an action happens there. The past form 「受けた」 shows it is completed, so the whole sentence is he was examined at the hospital.","grammar:837:ex:words:0:zh":"he","grammar:837:ex:words:0:note":"かれ","grammar:837:ex:words:0:pos":"pronoun","grammar:837:ex:words:1:zh":"(topic)","grammar:837:ex:words:1:pos":"particle","grammar:837:ex:words:2:zh":"hospital","grammar:837:ex:words:2:note":"びょういん","grammar:837:ex:words:2:pos":"noun","grammar:837:ex:words:3:zh":"(place)","grammar:837:ex:words:3:pos":"particle","grammar:837:ex:words:4:zh":"medical examination","grammar:837:ex:words:4:note":"しんさつ","grammar:837:ex:words:4:pos":"noun","grammar:837:ex:words:5:zh":"(object marker)","grammar:837:ex:words:5:pos":"particle","grammar:837:ex:words:6:zh":"accepted","grammar:837:ex:words:6:note":"うけた","grammar:837:ex:words:6:pos":"verb","grammar:837:ex:points:0":"❗診察を受ける: be examined by a doctor (fixed expression; uses 受ける).","grammar:837:ex:points:1":"病院で: at the hospital.","grammar:837:ex2:trans":"To get to the hospital, you take a bus from the station.","grammar:837:ex2:structure":"〜には〜に乗ります","grammar:837:ex2:words:0:zh":"hospital","grammar:837:ex2:words:0:note":"びょういん","grammar:837:ex2:words:0:pos":"noun","grammar:837:ex2:words:1:zh":"(destination)","grammar:837:ex2:words:1:pos":"particle","grammar:837:ex2:words:2:zh":"go","grammar:837:ex2:words:2:note":"いく","grammar:837:ex2:words:2:pos":"verb","grammar:837:ex2:words:3:zh":"(in order to)","grammar:837:ex2:words:3:pos":"particle","grammar:837:ex2:words:4:zh":"station","grammar:837:ex2:words:4:note":"えき","grammar:837:ex2:words:4:pos":"noun","grammar:837:ex2:words:5:zh":"from","grammar:837:ex2:words:5:pos":"particle","grammar:837:ex2:words:6:zh":"bus","grammar:837:ex2:words:6:note":"loanword","grammar:837:ex2:words:6:pos":"noun","grammar:837:ex2:words:7:zh":"(ride)","grammar:837:ex2:words:7:pos":"particle","grammar:837:ex2:words:8:zh":"to ride, to board","grammar:837:ex2:words:8:note":"のります","grammar:837:ex2:words:8:pos":"verb","grammar:837:ex2:points:0":"❗〜には: in order to …; to …; 病院に行くには = to go to the hospital.","grammar:837:ex2:points:1":"バスに乗る: take a bus.","grammar:837:ex3:trans":"There's a café near the hospital.","grammar:837:ex3:structure":"〜の近くに〜があります","grammar:837:ex3:words:0:zh":"hospital","grammar:837:ex3:words:0:note":"びょういん","grammar:837:ex3:words:0:pos":"noun","grammar:837:ex3:words:1:zh":"'s","grammar:837:ex3:words:1:pos":"particle","grammar:837:ex3:words:2:zh":"nearby","grammar:837:ex3:words:2:note":"ちかく","grammar:837:ex3:words:2:pos":"noun","grammar:837:ex3:words:3:zh":"(location of existence)","grammar:837:ex3:words:3:pos":"particle","grammar:837:ex3:words:4:zh":"café","grammar:837:ex3:words:4:note":"loanword","grammar:837:ex3:words:4:pos":"noun","grammar:837:ex3:words:5:zh":"(nominative)","grammar:837:ex3:words:5:pos":"particle","grammar:837:ex3:words:6:zh":"there is / are","grammar:837:ex3:words:6:pos":"verb","grammar:837:ex3:points:0":"病院の近く: near the hospital.","grammar:837:ex3:points:1":"カフェ: café.","grammar:837:ex4:trans":"A friend came to visit me at the hospital.","grammar:837:ex4:structure":"〜が〜をしてくれた","grammar:837:ex4:words:0:zh":"friend","grammar:837:ex4:words:0:note":"ともだち","grammar:837:ex4:words:0:pos":"noun","grammar:837:ex4:words:1:zh":"(nominative)","grammar:837:ex4:words:1:pos":"particle","grammar:837:ex4:words:2:zh":"hospital","grammar:837:ex4:words:2:note":"びょういん","grammar:837:ex4:words:2:pos":"noun","grammar:837:ex4:words:3:zh":"(place)","grammar:837:ex4:words:3:pos":"particle","grammar:837:ex4:words:4:zh":"visit (someone who is sick)","grammar:837:ex4:words:4:note":"おみまい","grammar:837:ex4:words:4:pos":"noun","grammar:837:ex4:words:5:zh":"(object marker)","grammar:837:ex4:words:5:pos":"particle","grammar:837:ex4:words:6:zh":"did (for me)","grammar:837:ex4:words:6:pos":"verb","grammar:837:ex4:points:0":"❗お見舞いをする: visit someone who is sick.","grammar:837:ex4:points:1":"〜てくれた: did … for me (giving and receiving).","grammar:837:ex5:trans":"Hospitals are sometimes crowded.","grammar:837:ex5:structure":"〜ことがある","grammar:837:ex5:words:0:zh":"hospital","grammar:837:ex5:words:0:note":"びょういん","grammar:837:ex5:words:0:pos":"noun","grammar:837:ex5:words:1:zh":"(topic)","grammar:837:ex5:words:1:pos":"particle","grammar:837:ex5:words:2:zh":"person","grammar:837:ex5:words:2:note":"ひと","grammar:837:ex5:words:2:pos":"noun","grammar:837:ex5:words:3:zh":"(nominative)","grammar:837:ex5:words:3:pos":"particle","grammar:837:ex5:words:4:zh":"many","grammar:837:ex5:words:4:note":"おおい","grammar:837:ex5:words:4:pos":"adjective","grammar:837:ex5:words:5:zh":"(cases)","grammar:837:ex5:words:5:pos":"noun","grammar:837:ex5:words:6:zh":"(nominative)","grammar:837:ex5:words:6:pos":"particle","grammar:837:ex5:words:7:zh":"there is / are","grammar:837:ex5:words:7:pos":"verb","grammar:837:ex5:points:0":"❗〜ことがある: sometimes ….","grammar:837:ex5:points:1":"人が多い: crowded; many people.","exam:837:zh":"I have a high fever, so I'm going to the hospital to have a doctor look at me.","exam:837:why":"When you're sick and need a doctor to examine you, you go to a 「病院」. A 「学校」 is a school, not the medical place needed here."},"838":{"example:838:exzh":"I use a cell phone.","example:838:exzh2":"A cell phone is a handy tool.","example:838:exzh3":"Do you have a trendy cell phone?","example:838:exzh4":"Don't forget to bring your cell phone.","example:838:exzh5":"My phone battery is about to die."},"839":{"example:839:exzh":"This shop is cheap.","example:839:exzh2":"A new shop has opened.","example:839:exzh3":"That shop is stylish.","example:839:exzh4":"I went to the shop to buy food.","example:839:exzh5":"There's a long line in front of the shop.","grammar:839:ex:trans":"This shop is cheap.","grammar:839:ex:structure":"〜は安いです","grammar:839:ex:explain":"「店（みせ）」 means a shop or store. The pattern is 「〜は安いです」: the i-adjective 「安い」 (cheap) works as the predicate and attaches straight to 「です」 to become polite form. The topic 「この店」 is marked with 「は」 and then commented on. Note that an i-adjective already ends in 「い」, so nothing changes when it attaches to 「です」 — 「安いです」 works as it is. This is the basic polite form of an i-adjective.","grammar:839:ex:words:0:zh":"this","grammar:839:ex:words:0:pos":"pre-noun adjectival","grammar:839:ex:words:1:zh":"store","grammar:839:ex:words:1:note":"みせ","grammar:839:ex:words:1:pos":"noun","grammar:839:ex:words:2:zh":"(topic)","grammar:839:ex:words:2:pos":"particle","grammar:839:ex:words:3:zh":"cheap","grammar:839:ex:words:3:note":"やすい","grammar:839:ex:words:3:pos":"adjective","grammar:839:ex:words:4:zh":"(polite form)","grammar:839:ex:words:4:pos":"copula","grammar:839:ex:points:0":"店（みせ）: shop, store.","grammar:839:ex:points:1":"安い: cheap.","grammar:839:ex2:trans":"The new shop has already opened.","grammar:839:ex2:structure":"〜がオープンしました","grammar:839:ex2:words:0:zh":"new","grammar:839:ex2:words:0:note":"あたらしい","grammar:839:ex2:words:0:pos":"adjective","grammar:839:ex2:words:1:zh":"store","grammar:839:ex2:words:1:note":"みせ","grammar:839:ex2:words:1:pos":"noun","grammar:839:ex2:words:2:zh":"(nominative)","grammar:839:ex2:words:2:pos":"particle","grammar:839:ex2:words:3:zh":"opened","grammar:839:ex2:words:3:pos":"verb","grammar:839:ex2:points:0":"オープンする: to open, to launch (loanword + する).","grammar:839:ex2:points:1":"新しい店: a new shop.","grammar:839:ex3:trans":"That shop is stylish.","grammar:839:ex3:structure":"〜はおしゃれです","grammar:839:ex3:words:0:zh":"that","grammar:839:ex3:words:0:pos":"pre-noun adjectival","grammar:839:ex3:words:1:zh":"store","grammar:839:ex3:words:1:note":"みせ","grammar:839:ex3:words:1:pos":"noun","grammar:839:ex3:words:2:zh":"(topic)","grammar:839:ex3:words:2:pos":"particle","grammar:839:ex3:words:3:zh":"stylish","grammar:839:ex3:words:3:pos":"na-adjective","grammar:839:ex3:words:4:zh":"(polite form)","grammar:839:ex3:words:4:pos":"copula","grammar:839:ex3:points:0":"おしゃれ: stylish, chic.","grammar:839:ex3:points:1":"あの店: that shop.","grammar:839:ex4:trans":"I went to the shop to buy food.","grammar:839:ex4:structure":"〜ために店に行きました","grammar:839:ex4:words:0:zh":"food","grammar:839:ex4:words:0:note":"たべもの","grammar:839:ex4:words:0:pos":"noun","grammar:839:ex4:words:1:zh":"(object marker)","grammar:839:ex4:words:1:pos":"particle","grammar:839:ex4:words:2:zh":"buy","grammar:839:ex4:words:2:note":"かう","grammar:839:ex4:words:2:pos":"verb","grammar:839:ex4:words:3:zh":"for the sake of","grammar:839:ex4:words:3:pos":"particle","grammar:839:ex4:words:4:zh":"store","grammar:839:ex4:words:4:note":"みせ","grammar:839:ex4:words:4:pos":"noun","grammar:839:ex4:words:5:zh":"(destination)","grammar:839:ex4:words:5:pos":"particle","grammar:839:ex4:words:6:zh":"went","grammar:839:ex4:words:6:note":"いきました","grammar:839:ex4:words:6:pos":"verb","grammar:839:ex4:points:0":"❗〜ために: in order to…","grammar:839:ex4:points:1":"店に行く: to go to the shop.","grammar:839:ex5:trans":"There's a long line in front of the shop.","grammar:839:ex5:structure":"〜に〜ができている","grammar:839:ex5:words:0:zh":"store","grammar:839:ex5:words:0:note":"みせ","grammar:839:ex5:words:0:pos":"noun","grammar:839:ex5:words:1:zh":"'s","grammar:839:ex5:words:1:pos":"particle","grammar:839:ex5:words:2:zh":"front","grammar:839:ex5:words:2:note":"まえ","grammar:839:ex5:words:2:pos":"noun","grammar:839:ex5:words:3:zh":"(location of existence)","grammar:839:ex5:words:3:pos":"particle","grammar:839:ex5:words:4:zh":"long","grammar:839:ex5:words:4:note":"ながい","grammar:839:ex5:words:4:pos":"adjective","grammar:839:ex5:words:5:zh":"team","grammar:839:ex5:words:5:note":"れつ","grammar:839:ex5:words:5:pos":"noun","grammar:839:ex5:words:6:zh":"(nominative)","grammar:839:ex5:words:6:pos":"particle","grammar:839:ex5:words:7:zh":"is forming","grammar:839:ex5:words:7:pos":"verb","grammar:839:ex5:points:0":"❗列ができる: a line forms (できる = to form).","grammar:839:ex5:points:1":"店の前: in front of the shop.","exam:839:zh":"I bought two breads at the shop that sells bread.","exam:839:why":"「店」 is a place where goods are sold, which fits the situation of selling and buying bread. 「図書館」 is a place for borrowing books, not a place that sells bread."},"840":{"example:840:exzh":"She forgave me.","example:840:exzh2":"It's important to forgive mistakes.","example:840:exzh3":"He can't forgive his friend.","example:840:exzh4":"That's behavior that shouldn't be forgiven.","example:840:exzh5":"Everyone makes mistakes, so let's forgive them."},"841":{"example:841:exzh":"This river is deep.","example:841:exzh2":"His voice is deep.","example:841:exzh3":"He went deep into the mountains.","example:841:exzh4":"I think this issue is profound.","example:841:exzh5":"I fell into a deep sleep.","grammar:841:ex:trans":"This river is deep.","grammar:841:ex:structure":"〜は深いです","grammar:841:ex:explain":"「深い（ふかい）」 is an i-adjective meaning deep, and its opposite is 「浅い（あさい）」 (shallow); learn them together. The pattern is 「〜は深いです」: the topic 「この川」 is marked with 「は」, followed by the i-adjective predicate 「深い」 plus 「です」 for the polite form. The whole sentence means: this river is deep. It's a basic adjective sentence describing a quality.","grammar:841:ex:words:0:zh":"this","grammar:841:ex:words:0:pos":"pre-noun adjectival","grammar:841:ex:words:1:zh":"river","grammar:841:ex:words:1:note":"かわ","grammar:841:ex:words:1:pos":"noun","grammar:841:ex:words:2:zh":"(topic)","grammar:841:ex:words:2:pos":"particle","grammar:841:ex:words:3:zh":"deep","grammar:841:ex:words:3:note":"ふかい","grammar:841:ex:words:3:pos":"adjective","grammar:841:ex:words:4:zh":"(polite form)","grammar:841:ex:words:4:pos":"copula","grammar:841:ex:points:0":"❗深い（ふかい）: deep; vs 浅い（あさい, shallow).","grammar:841:ex:points:1":"この川: this river.","grammar:841:ex2:trans":"His voice is deep.","grammar:841:ex2:structure":"〜は深い","grammar:841:ex2:words:0:zh":"he","grammar:841:ex2:words:0:note":"かれ","grammar:841:ex2:words:0:pos":"pronoun","grammar:841:ex2:words:1:zh":"'s","grammar:841:ex2:words:1:pos":"particle","grammar:841:ex2:words:2:zh":"voice","grammar:841:ex2:words:2:note":"こえ","grammar:841:ex2:words:2:pos":"noun","grammar:841:ex2:words:3:zh":"(topic)","grammar:841:ex2:words:3:pos":"particle","grammar:841:ex2:words:4:zh":"deep (of a voice)","grammar:841:ex2:words:4:note":"ふかい","grammar:841:ex2:words:4:pos":"adjective","grammar:841:ex2:points:0":"❗深い声: a deep voice.","grammar:841:ex2:points:1":"彼の声: his voice.","grammar:841:ex3:trans":"He walked deep into the mountains.","grammar:841:ex3:structure":"〜に入って行った","grammar:841:ex3:words:0:zh":"deep","grammar:841:ex3:words:0:note":"ふかい","grammar:841:ex3:words:0:pos":"adjective","grammar:841:ex3:words:1:zh":"mountain","grammar:841:ex3:words:1:note":"やま","grammar:841:ex3:words:1:pos":"noun","grammar:841:ex3:words:2:zh":"'s","grammar:841:ex3:words:2:pos":"particle","grammar:841:ex3:words:3:zh":"inside","grammar:841:ex3:words:3:note":"なか","grammar:841:ex3:words:3:pos":"noun","grammar:841:ex3:words:4:zh":"(the destination point)","grammar:841:ex3:words:4:pos":"particle","grammar:841:ex3:words:5:zh":"went in","grammar:841:ex3:words:5:note":"はいっていった","grammar:841:ex3:words:5:pos":"verb","grammar:841:ex3:points:0":"❗深い山: deep mountains; 〜に入って行く = go into …","grammar:841:ex3:points:1":"山の中: inside the mountains.","grammar:841:ex4:trans":"I think this question is profound.","grammar:841:ex4:structure":"〜は深いと思います","grammar:841:ex4:words:0:zh":"this","grammar:841:ex4:words:0:pos":"pre-noun adjectival","grammar:841:ex4:words:1:zh":"problem","grammar:841:ex4:words:1:note":"もんだい","grammar:841:ex4:words:1:pos":"noun","grammar:841:ex4:words:2:zh":"(topic)","grammar:841:ex4:words:2:pos":"particle","grammar:841:ex4:words:3:zh":"profound","grammar:841:ex4:words:3:note":"ふかい","grammar:841:ex4:words:3:pos":"adjective","grammar:841:ex4:words:4:zh":"(quotation)","grammar:841:ex4:words:4:pos":"particle","grammar:841:ex4:words:5:zh":"think","grammar:841:ex4:words:5:note":"おもいます","grammar:841:ex4:words:5:pos":"verb","grammar:841:ex4:points:0":"❗深い問題: a profound question (深い describing something abstract).","grammar:841:ex4:points:1":"〜と思います: I think …","grammar:841:ex5:trans":"I fell into a deep sleep.","grammar:841:ex5:structure":"深い〜に落ちてしまった","grammar:841:ex5:words:0:zh":"deep","grammar:841:ex5:words:0:note":"ふかい","grammar:841:ex5:words:0:pos":"adjective","grammar:841:ex5:words:1:zh":"sleep","grammar:841:ex5:words:1:note":"ねむり","grammar:841:ex5:words:1:pos":"noun","grammar:841:ex5:words:2:zh":"(the destination point)","grammar:841:ex5:words:2:pos":"particle","grammar:841:ex5:words:3:zh":"fall into","grammar:841:ex5:words:3:note":"おちて","grammar:841:ex5:words:3:pos":"verb","grammar:841:ex5:words:4:zh":"(without realizing it)","grammar:841:ex5:words:4:pos":"auxiliary verb","grammar:841:ex5:points:0":"❗深い眠りに落ちる: to fall into a deep sleep (idiomatic).","grammar:841:ex5:points:1":"〜てしまった: (unintentionally) ended up …"},"842":{"example:842:exzh":"The moon is beautiful tonight.","example:842:exzh2":"July is a summer month.","example:842:exzh3":"The moon is shining brightly.","example:842:exzh4":"A new month has begun.","example:842:exzh5":"I saw the waxing and waning of the moon.","grammar:842:ex:trans":"The moon is beautiful tonight.","grammar:842:ex:structure":"〜は〜がきれいです","grammar:842:ex:explain":"Two points. First, 「月（つき）」 means the moon, but the same kanji read 「がつ」 or 「げつ」 means a month (as in 「7月」), so context decides. Second, the pattern 「〜は〜がきれいです」: the overall topic 「今夜」 takes 「は」, the thing being described 「月」 takes 「が」, and then comes the na-adjective 「きれい」. By the way, 「月がきれい」 is sometimes taken as an indirect confession of love in Japanese — a famous literary allusion.","grammar:842:ex:words:0:zh":"Tonight","grammar:842:ex:words:0:note":"こんや","grammar:842:ex:words:0:pos":"noun","grammar:842:ex:words:1:zh":"(topic)","grammar:842:ex:words:1:pos":"particle","grammar:842:ex:words:2:zh":"the moon","grammar:842:ex:words:2:note":"つき","grammar:842:ex:words:2:pos":"noun","grammar:842:ex:words:3:zh":"(nominative)","grammar:842:ex:words:3:pos":"particle","grammar:842:ex:words:4:zh":"beautiful","grammar:842:ex:words:4:pos":"na-adjective","grammar:842:ex:words:5:zh":"(polite form)","grammar:842:ex:words:5:pos":"copula","grammar:842:ex:points:0":"❗月（つき）: the moon; also read がつ to mean a month (as in 7月).","grammar:842:ex:points:1":"月がきれい: the moon is beautiful (the subject takes が).","grammar:842:ex2:trans":"July is a summer month.","grammar:842:ex2:structure":"〜は〜の月です","grammar:842:ex2:words:0:zh":"July","grammar:842:ex2:words:0:note":"しちがつ","grammar:842:ex2:words:0:pos":"noun","grammar:842:ex2:words:1:zh":"(topic)","grammar:842:ex2:words:1:pos":"particle","grammar:842:ex2:words:2:zh":"summer","grammar:842:ex2:words:2:note":"なつ","grammar:842:ex2:words:2:pos":"noun","grammar:842:ex2:words:3:zh":"'s","grammar:842:ex2:words:3:pos":"particle","grammar:842:ex2:words:4:zh":"month (of the year)","grammar:842:ex2:words:4:note":"つき","grammar:842:ex2:words:4:pos":"noun","grammar:842:ex2:words:5:zh":"is","grammar:842:ex2:words:5:pos":"copula","grammar:842:ex2:points:0":"❗7月（しちがつ）: July (the month is read がつ).","grammar:842:ex2:points:1":"夏の月: a summer month.","grammar:842:ex3:trans":"The moon is shining brightly.","grammar:842:ex3:structure":"〜が〜照らしている","grammar:842:ex3:words:0:zh":"the moon","grammar:842:ex3:words:0:note":"つき","grammar:842:ex3:words:0:pos":"noun","grammar:842:ex3:words:1:zh":"(nominative)","grammar:842:ex3:words:1:pos":"particle","grammar:842:ex3:words:2:zh":"brightly","grammar:842:ex3:words:2:note":"あかるく","grammar:842:ex3:words:2:pos":"adverb","grammar:842:ex3:words:3:zh":"according to","grammar:842:ex3:words:3:note":"てらしている","grammar:842:ex3:words:3:pos":"verb","grammar:842:ex3:points:0":"明るく: brightly (明るい→明るく).","grammar:842:ex3:points:1":"照らす: to shine on, to illuminate.","grammar:842:ex4:trans":"A new month has begun.","grammar:842:ex4:structure":"〜が始まりました","grammar:842:ex4:words:0:zh":"new","grammar:842:ex4:words:0:note":"あたらしい","grammar:842:ex4:words:0:pos":"adjective","grammar:842:ex4:words:1:zh":"month (of the year)","grammar:842:ex4:words:1:note":"つき","grammar:842:ex4:words:1:pos":"noun","grammar:842:ex4:words:2:zh":"(nominative)","grammar:842:ex4:words:2:pos":"particle","grammar:842:ex4:words:3:zh":"started","grammar:842:ex4:words:3:note":"はじまりました","grammar:842:ex4:words:3:pos":"verb","grammar:842:ex4:points:0":"新しい月: a new month.","grammar:842:ex4:points:1":"始まる→始まりました。","grammar:842:ex5:trans":"I saw the waxing and waning of the moon.","grammar:842:ex5:structure":"〜を見ました","grammar:842:ex5:words:0:zh":"the moon","grammar:842:ex5:words:0:note":"つき","grammar:842:ex5:words:0:pos":"noun","grammar:842:ex5:words:1:zh":"'s","grammar:842:ex5:words:1:pos":"particle","grammar:842:ex5:words:2:zh":"waxing and waning","grammar:842:ex5:words:2:note":"みちかけ","grammar:842:ex5:words:2:pos":"noun","grammar:842:ex5:words:3:zh":"(object marker)","grammar:842:ex5:words:3:pos":"particle","grammar:842:ex5:words:4:zh":"watched","grammar:842:ex5:words:4:note":"みました","grammar:842:ex5:words:4:pos":"verb","grammar:842:ex5:points:0":"満ち欠け: the waxing and waning (of the moon).","grammar:842:ex5:points:1":"月の満ち欠け: the phases of the moon.","exam:842:zh":"On a clear night I looked up at the sky and saw one big, round moon.","exam:842:why":"In the night sky you can clearly see a big, round 「月」 (moon). A 「星」 usually looks like a tiny point of light, so it doesn't fit the description of big and round."},"843":{"example:843:exzh":"There's a surveillance camera there.","example:843:exzh2":"The police are strengthening surveillance.","example:843:exzh3":"I act under surveillance.","example:843:exzh4":"I'm thinking about a surveillance society.","example:843:exzh5":"The purpose of surveillance is safety."},"844":{"example:844:exzh":"Actually, that story has a continuation.","example:844:exzh2":"In reality, it isn't like that.","example:844:exzh3":"To be honest, I'm still hesitating.","example:844:exzh4":"This shows the truth.","example:844:exzh5":"Let's check the actual situation."},"845":{"example:845:exzh":"I study Japanese.","example:845:exzh2":"He likes learning new knowledge.","example:845:exzh3":"We should learn many things.","example:845:exzh4":"I learned a lot at university.","example:845:exzh5":"She says she wants to study history."},"846":{"example:846:exzh":"I exercise every day and train my body.","example:846:exzh2":"To maintain a healthy body, a balanced diet is important.","example:846:exzh3":"I went to the hospital recently because I wasn't feeling well.","example:846:exzh4":"Resting your body is also important.","example:846:exzh5":"This exercise is easy on the body.","grammar:846:ex:trans":"I exercise every day and train my body.","grammar:846:ex:structure":"〜て、〜を鍛えています","grammar:846:ex:explain":"Two points. First, te-form linking: the te-form 「して」 of the verb 「する」 joins the two actions 「運動をする」 and 「体を鍛える」, showing sequence or parallel action. Second, the continuous 「〜ている」: 「鍛えて＋いる」 expresses the habitual state of continually training. 「体（からだ）を鍛える」 means to train your body.","grammar:846:ex:words:0:zh":"every day","grammar:846:ex:words:0:note":"まいにち","grammar:846:ex:words:0:pos":"adverb","grammar:846:ex:words:1:zh":"exercise","grammar:846:ex:words:1:note":"うんどう","grammar:846:ex:words:1:pos":"noun","grammar:846:ex:words:2:zh":"(object marker)","grammar:846:ex:words:2:pos":"particle","grammar:846:ex:words:3:zh":"do","grammar:846:ex:words:3:pos":"verb","grammar:846:ex:words:4:zh":"body","grammar:846:ex:words:4:note":"からだ","grammar:846:ex:words:4:pos":"noun","grammar:846:ex:words:5:zh":"(object marker)","grammar:846:ex:words:5:pos":"particle","grammar:846:ex:words:6:zh":"am training","grammar:846:ex:words:6:note":"きたえています","grammar:846:ex:words:6:pos":"verb","grammar:846:ex:points:0":"❗体（からだ）: body.","grammar:846:ex:points:1":"体を鍛える: to train your body; 〜て: te-form linking.","grammar:846:ex2:trans":"To keep your body healthy, a balanced diet is important.","grammar:846:ex2:structure":"〜ために、〜が大切です","grammar:846:ex2:words:0:zh":"health","grammar:846:ex2:words:0:note":"けんこう","grammar:846:ex2:words:0:pos":"na-adjective","grammar:846:ex2:words:1:zh":"(attributive form)","grammar:846:ex2:words:1:pos":"auxiliary verb","grammar:846:ex2:words:2:zh":"body","grammar:846:ex2:words:2:note":"からだ","grammar:846:ex2:words:2:pos":"noun","grammar:846:ex2:words:3:zh":"(object marker)","grammar:846:ex2:words:3:pos":"particle","grammar:846:ex2:words:4:zh":"maintain","grammar:846:ex2:words:4:note":"いじする","grammar:846:ex2:words:4:pos":"verb","grammar:846:ex2:words:5:zh":"for the sake of","grammar:846:ex2:words:5:pos":"particle","grammar:846:ex2:words:6:zh":"balance","grammar:846:ex2:words:6:note":"loanword","grammar:846:ex2:words:6:pos":"noun","grammar:846:ex2:words:7:zh":"'s","grammar:846:ex2:words:7:pos":"particle","grammar:846:ex2:words:8:zh":"balanced (as in バランスの取れた)","grammar:846:ex2:words:8:note":"とれた","grammar:846:ex2:words:8:pos":"verb","grammar:846:ex2:words:9:zh":"diet","grammar:846:ex2:words:9:note":"しょくじ","grammar:846:ex2:words:9:pos":"noun","grammar:846:ex2:words:10:zh":"(nominative)","grammar:846:ex2:words:10:pos":"particle","grammar:846:ex2:words:11:zh":"important","grammar:846:ex2:words:11:note":"たいせつ","grammar:846:ex2:words:11:pos":"na-adjective","grammar:846:ex2:words:12:zh":"(polite form)","grammar:846:ex2:words:12:pos":"copula","grammar:846:ex2:points:0":"体を維持する: to maintain the body (its condition).","grammar:846:ex2:points:1":"バランスの取れた食事: a balanced diet.","grammar:846:ex3:trans":"I went to the hospital recently because I felt unwell.","grammar:846:ex3:structure":"〜ので〜に行きました","grammar:846:ex3:words:0:zh":"lately","grammar:846:ex3:words:0:note":"さいきん","grammar:846:ex3:words:0:pos":"adverb","grammar:846:ex3:words:1:zh":"physical condition","grammar:846:ex3:words:1:note":"たいちょう","grammar:846:ex3:words:1:pos":"noun","grammar:846:ex3:words:2:zh":"(nominative)","grammar:846:ex3:words:2:pos":"particle","grammar:846:ex3:words:3:zh":"bad","grammar:846:ex3:words:3:note":"わるい","grammar:846:ex3:words:3:pos":"adjective","grammar:846:ex3:words:4:zh":"because","grammar:846:ex3:words:4:pos":"particle","grammar:846:ex3:words:5:zh":"hospital","grammar:846:ex3:words:5:note":"びょういん","grammar:846:ex3:words:5:pos":"noun","grammar:846:ex3:words:6:zh":"(destination)","grammar:846:ex3:words:6:pos":"particle","grammar:846:ex3:words:7:zh":"went","grammar:846:ex3:words:7:note":"いきました","grammar:846:ex3:words:7:pos":"verb","grammar:846:ex3:points:0":"❗体調が悪い: to feel unwell (体調 = physical condition).","grammar:846:ex3:points:1":"〜ので: because…","grammar:846:ex4:trans":"Resting your body is also important.","grammar:846:ex4:structure":"〜ことも大事です","grammar:846:ex4:words:0:zh":"body","grammar:846:ex4:words:0:note":"からだ","grammar:846:ex4:words:0:pos":"noun","grammar:846:ex4:words:1:zh":"(object marker)","grammar:846:ex4:words:1:pos":"particle","grammar:846:ex4:words:2:zh":"to rest (something)","grammar:846:ex4:words:2:note":"やすめる","grammar:846:ex4:words:2:pos":"verb","grammar:846:ex4:words:3:zh":"(nominalizer)","grammar:846:ex4:words:3:pos":"noun","grammar:846:ex4:words:4:zh":"also, too","grammar:846:ex4:words:4:pos":"particle","grammar:846:ex4:words:5:zh":"important","grammar:846:ex4:words:5:note":"だいじ","grammar:846:ex4:words:5:pos":"na-adjective","grammar:846:ex4:words:6:zh":"(polite form)","grammar:846:ex4:words:6:pos":"copula","grammar:846:ex4:points:0":"❗体を休める: to rest your body (休める is a transitive verb).","grammar:846:ex4:points:1":"〜ことも大事: doing … is also important.","grammar:846:ex5:trans":"This exercise is gentle on the body.","grammar:846:ex5:structure":"〜は〜に優しいです","grammar:846:ex5:words:0:zh":"this","grammar:846:ex5:words:0:pos":"pre-noun adjectival","grammar:846:ex5:words:1:zh":"exercise","grammar:846:ex5:words:1:note":"うんどう","grammar:846:ex5:words:1:pos":"noun","grammar:846:ex5:words:2:zh":"(topic)","grammar:846:ex5:words:2:pos":"particle","grammar:846:ex5:words:3:zh":"body","grammar:846:ex5:words:3:note":"からだ","grammar:846:ex5:words:3:pos":"noun","grammar:846:ex5:words:4:zh":"(object)","grammar:846:ex5:words:4:pos":"particle","grammar:846:ex5:words:5:zh":"gentle","grammar:846:ex5:words:5:note":"やさしい","grammar:846:ex5:words:5:pos":"adjective","grammar:846:ex5:words:6:zh":"(polite form)","grammar:846:ex5:words:6:pos":"copula","grammar:846:ex5:points:0":"❗〜に優しい: gentle on / friendly to…","grammar:846:ex5:points:1":"体に優しい: gentle on the body, easy on the body.","exam:846:zh":"Every morning I wash my body from head to toe.","exam:846:why":"「体」 means body and covers everything from head to toe. 「顔」 means only the face and can't include the feet mentioned in the sentence."},"847":{"example:847:exzh":"The first time I went to Japan, I was very nervous.","example:847:exzh2":"He cooked for the first time.","example:847:exzh3":"The first volunteer experience was wonderful.","example:847:exzh4":"I saw this movie for the first time.","example:847:exzh5":"A first date will become a special memory.","grammar:847:ex:trans":"I was very nervous the first time I went to Japan.","grammar:847:ex:structure":"初めて〜た時、〜ました","grammar:847:ex:explain":"Two points. First, 「初めて」 means for the first time and modifies the action that follows. Second, the 「〜た時」 pattern: the verb goes in the past form 「行った」 and then takes 「時」, meaning when… — especially at or after the moment the action was completed. Here 「日本に初めて行った時」 means the time I first went to Japan. The second half, 「とても緊張しました」, describes how nervous I was then.","grammar:847:ex:words:0:zh":"Japan","grammar:847:ex:words:0:note":"にほん","grammar:847:ex:words:0:pos":"noun","grammar:847:ex:words:1:zh":"(destination)","grammar:847:ex:words:1:pos":"particle","grammar:847:ex:words:2:zh":"the first time","grammar:847:ex:words:2:note":"はじめて","grammar:847:ex:words:2:pos":"adverb","grammar:847:ex:words:3:zh":"went","grammar:847:ex:words:3:note":"いった","grammar:847:ex:words:3:pos":"verb","grammar:847:ex:words:4:zh":"time","grammar:847:ex:words:4:note":"とき","grammar:847:ex:words:4:pos":"noun","grammar:847:ex:words:5:zh":"extremely","grammar:847:ex:words:5:pos":"adverb","grammar:847:ex:words:6:zh":"was nervous","grammar:847:ex:words:6:note":"きんちょうしました","grammar:847:ex:words:6:pos":"verb","grammar:847:ex:points:0":"❗初めて: for the first time, first.","grammar:847:ex:points:1":"〜た時: when …","grammar:847:ex2:trans":"He cooked for the first time.","grammar:847:ex2:structure":"初めて〜を作りました","grammar:847:ex2:words:0:zh":"he","grammar:847:ex2:words:0:note":"かれ","grammar:847:ex2:words:0:pos":"pronoun","grammar:847:ex2:words:1:zh":"(topic)","grammar:847:ex2:words:1:pos":"particle","grammar:847:ex2:words:2:zh":"the first time","grammar:847:ex2:words:2:note":"はじめて","grammar:847:ex2:words:2:pos":"adverb","grammar:847:ex2:words:3:zh":"dish / cuisine","grammar:847:ex2:words:3:note":"りょうり","grammar:847:ex2:words:3:pos":"noun","grammar:847:ex2:words:4:zh":"(object marker)","grammar:847:ex2:words:4:pos":"particle","grammar:847:ex2:words:5:zh":"did","grammar:847:ex2:words:5:note":"つくりました","grammar:847:ex2:words:5:pos":"verb","grammar:847:ex2:points:0":"初めて料理を作る: to cook for the first time.","grammar:847:ex2:points:1":"作る→作りました。","grammar:847:ex3:trans":"The first volunteer experience was wonderful.","grammar:847:ex3:structure":"初めての〜は〜かったです","grammar:847:ex3:words:0:zh":"the first time","grammar:847:ex3:words:0:note":"はじめて","grammar:847:ex3:words:0:pos":"noun","grammar:847:ex3:words:1:zh":"'s","grammar:847:ex3:words:1:pos":"particle","grammar:847:ex3:words:2:zh":"volunteer","grammar:847:ex3:words:2:note":"loanword","grammar:847:ex3:words:2:pos":"noun","grammar:847:ex3:words:3:zh":"experience","grammar:847:ex3:words:3:note":"たいけん","grammar:847:ex3:words:3:pos":"noun","grammar:847:ex3:words:4:zh":"(topic)","grammar:847:ex3:words:4:pos":"particle","grammar:847:ex3:words:5:zh":"was great (past)","grammar:847:ex3:words:5:note":"すばらしかった","grammar:847:ex3:words:5:pos":"adjective","grammar:847:ex3:words:6:zh":"(polite form)","grammar:847:ex3:words:6:pos":"copula","grammar:847:ex3:points:0":"❗初めての＋noun: the first… (初めて + の).","grammar:847:ex3:points:1":"素晴らしかった: was wonderful (past).","grammar:847:ex4:trans":"I saw this movie for the first time.","grammar:847:ex4:structure":"〜は初めて〜ました","grammar:847:ex4:words:0:zh":"this","grammar:847:ex4:words:0:pos":"pre-noun adjectival","grammar:847:ex4:words:1:zh":"movie","grammar:847:ex4:words:1:note":"えいが","grammar:847:ex4:words:1:pos":"noun","grammar:847:ex4:words:2:zh":"(topic)","grammar:847:ex4:words:2:pos":"particle","grammar:847:ex4:words:3:zh":"the first time","grammar:847:ex4:words:3:note":"はじめて","grammar:847:ex4:words:3:pos":"adverb","grammar:847:ex4:words:4:zh":"watched","grammar:847:ex4:words:4:note":"みました","grammar:847:ex4:words:4:pos":"verb","grammar:847:ex4:points:0":"初めて見る: to see for the first time.","grammar:847:ex4:points:1":"この映画: this movie.","grammar:847:ex5:trans":"A first date becomes a special memory.","grammar:847:ex5:structure":"初めての〜は〜になります","grammar:847:ex5:words:0:zh":"the first time","grammar:847:ex5:words:0:note":"はじめて","grammar:847:ex5:words:0:pos":"noun","grammar:847:ex5:words:1:zh":"'s","grammar:847:ex5:words:1:pos":"particle","grammar:847:ex5:words:2:zh":"date","grammar:847:ex5:words:2:note":"loanword","grammar:847:ex5:words:2:pos":"noun","grammar:847:ex5:words:3:zh":"(topic)","grammar:847:ex5:words:3:pos":"particle","grammar:847:ex5:words:4:zh":"special","grammar:847:ex5:words:4:note":"とくべつ","grammar:847:ex5:words:4:pos":"na-adjective","grammar:847:ex5:words:5:zh":"(attributive form)","grammar:847:ex5:words:5:pos":"auxiliary verb","grammar:847:ex5:words:6:zh":"memories","grammar:847:ex5:words:6:note":"おもいで","grammar:847:ex5:words:6:pos":"noun","grammar:847:ex5:words:7:zh":"(result)","grammar:847:ex5:words:7:pos":"particle","grammar:847:ex5:words:8:zh":"become","grammar:847:ex5:words:8:pos":"verb","grammar:847:ex5:points:0":"初めてのデート: a first date.","grammar:847:ex5:points:1":"〜になる: to become…"},"848":{"example:848:exzh":"Childhood memories make me feel nostalgic.","example:848:exzh2":"This photo is my precious memory.","example:848:exzh3":"Let's talk together about memories from the trip.","example:848:exzh4":"I want to make good memories.","example:848:exzh5":"This song brings back my memories."},"849":{"example:849:exzh":"He's lucky, so he always succeeds.","example:849:exzh2":"I believe in luck and keep taking on challenges.","example:849:exzh3":"There are bad-luck days too, but don't worry about it.","example:849:exzh4":"It's important to feel that you're lucky.","example:849:exzh5":"Let's think positively to attract good luck.","grammar:849:ex:trans":"He has good luck, so he always succeeds.","grammar:849:ex:structure":"〜が良いので、〜します","grammar:849:ex:explain":"Two points. First, 「運が良い」 means to have good luck; 「運（うん）」 is luck, marked as the subject with 「が」. Second, 「〜ので」 expresses a cause or reason. It sounds more objective and softer than 「から」, and it attaches after an adjective or verb to explain cause and effect. So 「運が良いので」 means \"because he has good luck\". The second half, 「いつも成功します」, is the result. The whole sentence means \"he has good luck, so he always succeeds\".","grammar:849:ex:words:0:zh":"he","grammar:849:ex:words:0:note":"かれ","grammar:849:ex:words:0:pos":"pronoun","grammar:849:ex:words:1:zh":"(topic)","grammar:849:ex:words:1:pos":"particle","grammar:849:ex:words:2:zh":"luck","grammar:849:ex:words:2:note":"うん","grammar:849:ex:words:2:pos":"noun","grammar:849:ex:words:3:zh":"(nominative)","grammar:849:ex:words:3:pos":"particle","grammar:849:ex:words:4:zh":"good","grammar:849:ex:words:4:note":"いい","grammar:849:ex:words:4:pos":"adjective","grammar:849:ex:words:5:zh":"because","grammar:849:ex:words:5:pos":"particle","grammar:849:ex:words:6:zh":"always","grammar:849:ex:words:6:pos":"adverb","grammar:849:ex:words:7:zh":"success","grammar:849:ex:words:7:note":"せいこうします","grammar:849:ex:words:7:pos":"verb","grammar:849:ex:points:0":"❗運が良い: to have good luck (運 = luck, marked as subject with が).","grammar:849:ex:points:1":"〜ので: because…","grammar:849:ex2:trans":"I believe in luck and take on the challenge.","grammar:849:ex2:structure":"〜を信じて、〜します","grammar:849:ex2:words:0:zh":"luck","grammar:849:ex2:words:0:note":"うん","grammar:849:ex2:words:0:pos":"noun","grammar:849:ex2:words:1:zh":"(object marker)","grammar:849:ex2:words:1:pos":"particle","grammar:849:ex2:words:2:zh":"believe","grammar:849:ex2:words:2:note":"しんじて","grammar:849:ex2:words:2:pos":"verb","grammar:849:ex2:words:3:zh":"challenge; try","grammar:849:ex2:words:3:pos":"verb","grammar:849:ex2:points:0":"運を信じる: to believe in luck.","grammar:849:ex2:points:1":"チャレンジする: to take on a challenge.","grammar:849:ex3:trans":"There are bad-luck days too, but don't worry about it.","grammar:849:ex3:structure":"〜日もありますが、気にしないで","grammar:849:ex3:words:0:zh":"luck","grammar:849:ex3:words:0:note":"うん","grammar:849:ex3:words:0:pos":"noun","grammar:849:ex3:words:1:zh":"(nominative)","grammar:849:ex3:words:1:pos":"particle","grammar:849:ex3:words:2:zh":"bad","grammar:849:ex3:words:2:note":"わるい","grammar:849:ex3:words:2:pos":"adjective","grammar:849:ex3:words:3:zh":"day","grammar:849:ex3:words:3:note":"ひ","grammar:849:ex3:words:3:pos":"noun","grammar:849:ex3:words:4:zh":"also, too","grammar:849:ex3:words:4:pos":"particle","grammar:849:ex3:words:5:zh":"there is / are","grammar:849:ex3:words:5:pos":"verb","grammar:849:ex3:words:6:zh":"but","grammar:849:ex3:words:6:pos":"particle","grammar:849:ex3:words:7:zh":"don't worry about it","grammar:849:ex3:words:7:note":"きにしないで","grammar:849:ex3:words:7:pos":"set phrase","grammar:849:ex3:points:0":"❗気にしないで: don't worry about it (気にする = to mind, to care about).","grammar:849:ex3:points:1":"〜日もある: there are also days when…","grammar:849:ex4:trans":"It's important to feel that you're lucky.","grammar:849:ex4:structure":"〜と感じることが大切です","grammar:849:ex4:words:0:zh":"luck","grammar:849:ex4:words:0:note":"うん","grammar:849:ex4:words:0:pos":"noun","grammar:849:ex4:words:1:zh":"(nominative)","grammar:849:ex4:words:1:pos":"particle","grammar:849:ex4:words:2:zh":"good","grammar:849:ex4:words:2:note":"いい","grammar:849:ex4:words:2:pos":"adjective","grammar:849:ex4:words:3:zh":"(quotation)","grammar:849:ex4:words:3:pos":"particle","grammar:849:ex4:words:4:zh":"sense","grammar:849:ex4:words:4:note":"かんじる","grammar:849:ex4:words:4:pos":"verb","grammar:849:ex4:words:5:zh":"(nominalizer)","grammar:849:ex4:words:5:pos":"noun","grammar:849:ex4:words:6:zh":"(nominative)","grammar:849:ex4:words:6:pos":"particle","grammar:849:ex4:words:7:zh":"important","grammar:849:ex4:words:7:note":"たいせつ","grammar:849:ex4:words:7:pos":"na-adjective","grammar:849:ex4:words:8:zh":"(polite form)","grammar:849:ex4:words:8:pos":"copula","grammar:849:ex4:points:0":"〜と感じる: to feel that… (quotation).","grammar:849:ex4:points:1":"〜ことが大切です: doing … is important.","grammar:849:ex5:trans":"To attract luck, stay positive.","grammar:849:ex5:structure":"〜ために〜ましょう","grammar:849:ex5:words:0:zh":"luck","grammar:849:ex5:words:0:note":"うん","grammar:849:ex5:words:0:pos":"noun","grammar:849:ex5:words:1:zh":"(object marker)","grammar:849:ex5:words:1:pos":"particle","grammar:849:ex5:words:2:zh":"attract","grammar:849:ex5:words:2:note":"ひきよせる","grammar:849:ex5:words:2:pos":"verb","grammar:849:ex5:words:3:zh":"for the sake of","grammar:849:ex5:words:3:pos":"particle","grammar:849:ex5:words:4:zh":"positively","grammar:849:ex5:words:4:pos":"adverb","grammar:849:ex5:words:5:zh":"let's think","grammar:849:ex5:words:5:note":"かんがえましょう","grammar:849:ex5:words:5:pos":"verb","grammar:849:ex5:points:0":"運を引き寄せる: to draw good luck to yourself.","grammar:849:ex5:points:1":"ポジティブに: positively."},"850":{"example:850:exzh":"That mountain is very tall.","example:850:exzh2":"This hotel is expensive, but the service is good.","example:850:exzh3":"He is very tall.","example:850:exzh4":"Do you like high places?","example:850:exzh5":"This book is a little expensive, but it's worth buying.","grammar:850:ex:trans":"That mountain is very high.","grammar:850:ex:structure":"あの＋noun＋は＋とても＋i-adjective＋です。","grammar:850:ex:explain":"「あの」 is a demonstrative pre-noun adjectival referring to something far from both speaker and listener, and it attaches directly to the noun 「山」. The pattern is 「〜はとても〜です」: the adverb 「とても」 intensifies and modifies the i-adjective 「高い」. The topic 「あの山」 is marked with 「は」, and the predicate 「高い」 takes 「です」 to become polite. The whole sentence simply describes that the mountain over there is very high — the most basic kind of adjective statement.","grammar:850:ex:words:0:zh":"that","grammar:850:ex:words:0:pos":"pre-noun adjectival","grammar:850:ex:words:1:zh":"mountain","grammar:850:ex:words:1:note":"やま","grammar:850:ex:words:1:pos":"noun","grammar:850:ex:words:2:zh":"(topic marker)","grammar:850:ex:words:2:pos":"particle","grammar:850:ex:words:3:zh":"extremely","grammar:850:ex:words:3:pos":"adverb","grammar:850:ex:words:4:zh":"high","grammar:850:ex:words:4:note":"たかい","grammar:850:ex:words:4:pos":"adjective","grammar:850:ex:words:5:zh":"(polite form)","grammar:850:ex:words:5:pos":"copula","grammar:850:ex:points:0":"あの: that (over there)","grammar:850:ex:points:1":"とても高い: very high","grammar:850:ex2:trans":"This hotel is expensive, but the service is good.","grammar:850:ex2:structure":"i-adjective＋けれど、〜。 「けれど」 is a contrastive conjunction meaning although…, …","grammar:850:ex2:words:0:zh":"this","grammar:850:ex2:words:0:pos":"pre-noun adjectival","grammar:850:ex2:words:1:zh":"hotel","grammar:850:ex2:words:1:note":"loanword","grammar:850:ex2:words:1:pos":"noun","grammar:850:ex2:words:2:zh":"(topic marker)","grammar:850:ex2:words:2:pos":"particle","grammar:850:ex2:words:3:zh":"expensive","grammar:850:ex2:words:3:note":"たかい","grammar:850:ex2:words:3:pos":"adjective","grammar:850:ex2:words:4:zh":"although…, but","grammar:850:ex2:words:4:note":"contrast","grammar:850:ex2:words:4:pos":"particle","grammar:850:ex2:words:5:zh":"service","grammar:850:ex2:words:5:note":"loanword","grammar:850:ex2:words:5:pos":"noun","grammar:850:ex2:words:6:zh":"(nominative)","grammar:850:ex2:words:6:pos":"particle","grammar:850:ex2:words:7:zh":"good","grammar:850:ex2:words:7:note":"よい","grammar:850:ex2:words:7:pos":"adjective","grammar:850:ex2:words:8:zh":"(polite form)","grammar:850:ex2:words:8:pos":"copula","grammar:850:ex2:points:0":"けれど: although…, … (contrast)","grammar:850:ex2:points:1":"高い: expensive (also means tall / high)","grammar:850:ex3:trans":"He is very tall.","grammar:850:ex3:structure":"〔nounのnoun〕＋は＋とても＋i-adjective＋です。","grammar:850:ex3:words:0:zh":"he","grammar:850:ex3:words:0:note":"かれ","grammar:850:ex3:words:0:pos":"pronoun","grammar:850:ex3:words:1:zh":"'s","grammar:850:ex3:words:1:pos":"particle","grammar:850:ex3:words:2:zh":"height","grammar:850:ex3:words:2:note":"しんちょう","grammar:850:ex3:words:2:pos":"noun","grammar:850:ex3:words:3:zh":"(topic marker)","grammar:850:ex3:words:3:pos":"particle","grammar:850:ex3:words:4:zh":"extremely","grammar:850:ex3:words:4:pos":"adverb","grammar:850:ex3:words:5:zh":"high","grammar:850:ex3:words:5:note":"たかい","grammar:850:ex3:words:5:pos":"adjective","grammar:850:ex3:words:6:zh":"(polite form)","grammar:850:ex3:words:6:pos":"copula","grammar:850:ex3:points:0":"身長が高い: to be tall","grammar:850:ex3:points:1":"彼の身長: his height","grammar:850:ex4:trans":"Do you like high places?","grammar:850:ex4:structure":"i-adjective＋noun＋が＋好きですか。","grammar:850:ex4:words:0:zh":"high","grammar:850:ex4:words:0:note":"たかい","grammar:850:ex4:words:0:pos":"adjective","grammar:850:ex4:words:1:zh":"place","grammar:850:ex4:words:1:pos":"noun","grammar:850:ex4:words:2:zh":"(object marker)","grammar:850:ex4:words:2:pos":"particle","grammar:850:ex4:words:3:zh":"to like","grammar:850:ex4:words:3:note":"すき","grammar:850:ex4:words:3:pos":"na-adjective","grammar:850:ex4:words:4:zh":"is","grammar:850:ex4:words:4:pos":"copula","grammar:850:ex4:words:5:zh":"(question)","grammar:850:ex4:words:5:pos":"particle","grammar:850:ex4:points:0":"高いところ: a high place","grammar:850:ex4:points:1":"〜が好きですか: do you like…?","grammar:850:ex5:trans":"This book is a little expensive, but it is worth buying.","grammar:850:ex5:structure":"〜ですが、〔verb dictionary form〕＋価値があります。 「が」 is contrastive, and 「〜価値がある」 means to be worth…","grammar:850:ex5:words:0:zh":"this","grammar:850:ex5:words:0:pos":"pre-noun adjectival","grammar:850:ex5:words:1:zh":"book","grammar:850:ex5:words:1:note":"ほん","grammar:850:ex5:words:1:pos":"noun","grammar:850:ex5:words:2:zh":"(topic marker)","grammar:850:ex5:words:2:pos":"particle","grammar:850:ex5:words:3:zh":"a little","grammar:850:ex5:words:3:note":"すこし","grammar:850:ex5:words:3:pos":"adverb","grammar:850:ex5:words:4:zh":"expensive","grammar:850:ex5:words:4:note":"たかい","grammar:850:ex5:words:4:pos":"adjective","grammar:850:ex5:words:5:zh":"(polite form)","grammar:850:ex5:words:5:pos":"copula","grammar:850:ex5:words:6:zh":"but","grammar:850:ex5:words:6:note":"contrast","grammar:850:ex5:words:6:pos":"particle","grammar:850:ex5:words:7:zh":"buy","grammar:850:ex5:words:7:note":"かう","grammar:850:ex5:words:7:pos":"verb","grammar:850:ex5:words:8:zh":"value","grammar:850:ex5:words:8:note":"かち","grammar:850:ex5:words:8:pos":"noun","grammar:850:ex5:words:9:zh":"(nominative)","grammar:850:ex5:words:9:pos":"particle","grammar:850:ex5:words:10:zh":"there is / are","grammar:850:ex5:words:10:note":"〜価値がある ＝ to be worth…","grammar:850:ex5:words:10:pos":"verb","grammar:850:ex5:points:0":"〜が: but (contrast)","grammar:850:ex5:points:1":"〜価値がある: to be worth… (買う価値がある ＝ worth buying)","exam:850:zh":"This watch costs as much as a hundred thousand yen, so it's expensive for me.","exam:850:why":"「高い」 can mean expensive, which matches 「十万円もする」. 「低い」 usually means low in height or degree, so it can't describe this watch as expensive."},"851":{"example:851:exzh":"His country restricts weapons exports.","example:851:exzh2":"This weapon is extremely high-performance.","example:851:exzh3":"Using weapons is not easy.","example:851:exzh4":"He is a weapons expert.","example:851:exzh5":"Efforts to reduce weapons are needed around the world."},"852":{"example:852:exzh":"I often make mistakes.","example:852:exzh2":"Sometimes you make mistakes, but learning is what matters most.","example:852:exzh3":"Don't be afraid of making mistakes either.","example:852:exzh4":"I made a mistake in my calculation.","example:852:exzh5":"It's important to correct the parts you got wrong.","grammar:852:ex:trans":"I often make mistakes.","grammar:852:ex:structure":"よく間違えます","grammar:852:ex:explain":"The key point is the transitive verb 「間違える（まちがえる）」, meaning to get wrong or to mistake, which can take an object (to get something wrong). It's often confused with the intransitive 「間違う」 (to be wrong, to err), but strictly 「間違える」 stresses a person actively making a mistake. The adverb 「よく」 here means often, and the polite 「間違えます」 expresses a habit. The whole sentence means: I often make mistakes.","grammar:852:ex:words:0:zh":"I","grammar:852:ex:words:0:note":"わたし","grammar:852:ex:words:0:pos":"pronoun","grammar:852:ex:words:1:zh":"(topic)","grammar:852:ex:words:1:pos":"particle","grammar:852:ex:words:2:zh":"often","grammar:852:ex:words:2:pos":"adverb","grammar:852:ex:words:3:zh":"got it wrong","grammar:852:ex:words:3:note":"まちがえます","grammar:852:ex:words:3:pos":"verb","grammar:852:ex:points:0":"❗間違える（まちがえる）: to get wrong, to make a mistake (transitive verb); vs 間違う (intransitive verb, to be wrong).","grammar:852:ex:points:1":"よく間違える: often make mistakes.","grammar:852:ex2:trans":"You sometimes get it wrong, but learning is what matters most.","grammar:852:ex2:structure":"〜ときもあるけれど、〜","grammar:852:ex2:words:0:zh":"got it wrong","grammar:852:ex2:words:0:note":"まちがえる","grammar:852:ex2:words:0:pos":"verb","grammar:852:ex2:words:1:zh":"time","grammar:852:ex2:words:1:pos":"noun","grammar:852:ex2:words:2:zh":"also, too","grammar:852:ex2:words:2:pos":"particle","grammar:852:ex2:words:3:zh":"there is / are","grammar:852:ex2:words:3:pos":"verb","grammar:852:ex2:words:4:zh":"but","grammar:852:ex2:words:4:pos":"particle","grammar:852:ex2:words:5:zh":"study","grammar:852:ex2:words:5:note":"まなぶ","grammar:852:ex2:words:5:pos":"verb","grammar:852:ex2:words:6:zh":"(nominalizer)","grammar:852:ex2:words:6:pos":"noun","grammar:852:ex2:words:7:zh":"(nominative)","grammar:852:ex2:words:7:pos":"particle","grammar:852:ex2:words:8:zh":"important","grammar:852:ex2:words:8:note":"たいせつ","grammar:852:ex2:words:8:pos":"na-adjective","grammar:852:ex2:words:9:zh":"(polite form)","grammar:852:ex2:words:9:pos":"copula","grammar:852:ex2:points:0":"❗〜けれど: but, although (contrast).","grammar:852:ex2:points:1":"〜ときもある: there are also times when …","grammar:852:ex3:trans":"Don't be afraid of making mistakes either.","grammar:852:ex3:structure":"〜ことを恐れないでください","grammar:852:ex3:explain":"「あなたも」 means you too. 「間違えること」 turns the act of making a mistake into a thing, and 「を」 marks it as the object of fear. 「恐れないでください」 is the negative request form of 「恐れる」, meaning please don't be afraid; the whole sentence has an encouraging tone, urging the other person to try boldly.","grammar:852:ex3:words:0:zh":"you","grammar:852:ex3:words:0:pos":"pronoun","grammar:852:ex3:words:1:zh":"also, too","grammar:852:ex3:words:1:pos":"particle","grammar:852:ex3:words:2:zh":"making a mistake","grammar:852:ex3:words:2:note":"まちがえる","grammar:852:ex3:words:2:pos":"verb","grammar:852:ex3:words:3:zh":"(nominalizes the action)","grammar:852:ex3:words:3:pos":"noun","grammar:852:ex3:words:4:zh":"(object of fear)","grammar:852:ex3:words:4:pos":"particle","grammar:852:ex3:words:5:zh":"fear","grammar:852:ex3:words:5:note":"おそれ","grammar:852:ex3:words:5:pos":"verb","grammar:852:ex3:words:6:zh":"No","grammar:852:ex3:words:6:pos":"auxiliary verb","grammar:852:ex3:words:7:zh":"(links to a negative request)","grammar:852:ex3:words:7:pos":"particle","grammar:852:ex3:words:8:zh":"please","grammar:852:ex3:words:8:pos":"verb","grammar:852:ex3:points:0":"「dictionary form verb + こと」 nominalizes the action, so 「間違えること」 means the act of making a mistake.","grammar:852:ex3:points:1":"「nai-form verb + でください」 means please don't do something.","grammar:852:ex3:points:2":"With 「恐れる」, the thing feared is marked with 「を」.","grammar:852:ex4:trans":"I miscalculated.","grammar:852:ex4:structure":"〜を間違えました","grammar:852:ex4:words:0:zh":"calculation","grammar:852:ex4:words:0:note":"けいさん","grammar:852:ex4:words:0:pos":"noun","grammar:852:ex4:words:1:zh":"(object marker)","grammar:852:ex4:words:1:pos":"particle","grammar:852:ex4:words:2:zh":"got it wrong","grammar:852:ex4:words:2:note":"まちがえました","grammar:852:ex4:words:2:pos":"verb","grammar:852:ex4:points:0":"❗計算を間違える: to miscalculate.","grammar:852:ex4:points:1":"間違える → 間違えました.","grammar:852:ex5:trans":"It's important to fix the parts you got wrong.","grammar:852:ex5:structure":"〜たところを正すことは大事です","grammar:852:ex5:explain":"「間違えた」 modifies 「ところ」, and here 「ところ」 means the part that is wrong, not necessarily a physical place. 「間違えたところを正す」 means to correct the part you got wrong. The following 「こと」 nominalizes the whole action, 「は」 sets it as the topic, and 「大事です」 says this is important.","grammar:852:ex5:words:0:zh":"got it wrong","grammar:852:ex5:words:0:note":"まちがえ","grammar:852:ex5:words:0:pos":"verb","grammar:852:ex5:words:1:zh":"(past, completed)","grammar:852:ex5:words:1:pos":"auxiliary verb","grammar:852:ex5:words:2:zh":"place, part","grammar:852:ex5:words:2:pos":"noun","grammar:852:ex5:words:3:zh":"(object)","grammar:852:ex5:words:3:pos":"particle","grammar:852:ex5:words:4:zh":"correct","grammar:852:ex5:words:4:note":"ただす","grammar:852:ex5:words:4:pos":"verb","grammar:852:ex5:words:5:zh":"(nominalizes the action)","grammar:852:ex5:words:5:pos":"noun","grammar:852:ex5:words:6:zh":"(topic)","grammar:852:ex5:words:6:pos":"particle","grammar:852:ex5:words:7:zh":"important","grammar:852:ex5:words:7:note":"だいじ","grammar:852:ex5:words:7:pos":"na-adjective","grammar:852:ex5:words:8:zh":"(polite tone)","grammar:852:ex5:words:8:pos":"auxiliary verb","grammar:852:ex5:points:0":"「ta-form verb + ところ」 can mean the part where an action was done, as in 「間違えたところ」.","grammar:852:ex5:points:1":"「dictionary form verb + ことは」 makes the whole action the topic.","grammar:852:ex5:points:2":"「大事」 is a na-adjective, and as a sentence-final predicate it can take 「です」 directly."},"853":{"example:853:exzh":"When I was a student, I often played with friends.","example:853:exzh2":"Around spring, the cherry blossoms bloom.","example:853:exzh3":"By the time he came, it was already dark.","example:853:exzh4":"Lately I haven't been able to get in touch with a friend.","example:853:exzh5":"Childhood was the happiest time.","grammar:853:ex:trans":"When I was a student, I often played with friends.","grammar:853:ex:structure":"〜の頃、〜ました","grammar:853:ex:explain":"The key point is 「〜の頃（ころ）」, which means around a certain period or time; 「学生の頃」 is your school days. The 「と」 in 「友達と」 marks the person you do the action with, and 「よく」 here means often. The past polite form of the verb 「遊ぶ」 is 「遊びました」 (ぶ→び + ました). The whole sentence looks back on playing with friends often during your school days.","grammar:853:ex:words:0:zh":"student","grammar:853:ex:words:0:note":"がくせい","grammar:853:ex:words:0:pos":"noun","grammar:853:ex:words:1:zh":"'s","grammar:853:ex:words:1:pos":"particle","grammar:853:ex:words:2:zh":"time","grammar:853:ex:words:2:note":"ころ","grammar:853:ex:words:2:pos":"noun","grammar:853:ex:words:3:zh":"friend","grammar:853:ex:words:3:note":"ともだち","grammar:853:ex:words:3:pos":"noun","grammar:853:ex:words:4:zh":"with","grammar:853:ex:words:4:pos":"particle","grammar:853:ex:words:5:zh":"often","grammar:853:ex:words:5:pos":"adverb","grammar:853:ex:words:6:zh":"hung out / played","grammar:853:ex:words:6:note":"あそびました","grammar:853:ex:words:6:pos":"verb","grammar:853:ex:points:0":"❗〜の頃: the time or period of… (学生の頃 = your school days).","grammar:853:ex:points:1":"よく: often.","grammar:853:ex2:trans":"When spring comes around, the cherry blossoms bloom.","grammar:853:ex2:structure":"〔time period〕頃になると、〜","grammar:853:ex2:words:0:zh":"around spring","grammar:853:ex2:words:0:note":"はるごろ","grammar:853:ex2:words:0:pos":"noun","grammar:853:ex2:words:1:zh":"(result of the change)","grammar:853:ex2:words:1:pos":"particle","grammar:853:ex2:words:2:zh":"becomes, turns into","grammar:853:ex2:words:2:pos":"verb","grammar:853:ex2:words:3:zh":"(as soon as…)","grammar:853:ex2:words:3:pos":"particle","grammar:853:ex2:words:4:zh":"cherry blossoms","grammar:853:ex2:words:4:note":"さくら","grammar:853:ex2:words:4:pos":"noun","grammar:853:ex2:words:5:zh":"(subject)","grammar:853:ex2:words:5:pos":"particle","grammar:853:ex2:words:6:zh":"bloom","grammar:853:ex2:words:6:note":"さきます; masu-form","grammar:853:ex2:words:6:pos":"verb","grammar:853:ex2:points:0":"「春頃」: 頃 attaches after a time noun to mean \"around…\", and in that case it voices to ごろ; used on its own, it is read ころ.","grammar:853:ex2:points:1":"「〜になると」 means that once a certain time comes, what follows happens naturally.","grammar:853:ex2:points:2":"「咲きます」 is the masu-form of 咲く and describes something that happens every year.","grammar:853:ex3:trans":"By the time he came, it was already dark.","grammar:853:ex3:structure":"〜頃には、〜ていました","grammar:853:ex3:words:0:zh":"he","grammar:853:ex3:words:0:note":"かれ","grammar:853:ex3:words:0:pos":"pronoun","grammar:853:ex3:words:1:zh":"(nominative)","grammar:853:ex3:words:1:pos":"particle","grammar:853:ex3:words:2:zh":"come","grammar:853:ex3:words:2:note":"くる","grammar:853:ex3:words:2:pos":"verb","grammar:853:ex3:words:3:zh":"time","grammar:853:ex3:words:3:note":"ころ","grammar:853:ex3:words:3:pos":"noun","grammar:853:ex3:words:4:zh":"(time emphasis)","grammar:853:ex3:words:4:pos":"particle","grammar:853:ex3:words:5:zh":"already","grammar:853:ex3:words:5:pos":"adverb","grammar:853:ex3:words:6:zh":"had gotten dark","grammar:853:ex3:words:6:note":"くらくなっていました","grammar:853:ex3:words:6:pos":"verb","grammar:853:ex3:points:0":"〜頃には: by the time…","grammar:853:ex3:points:1":"暗くなる: to get dark (i-adjective く + なる).","grammar:853:ex4:trans":"Lately I haven't been able to get in touch with my friend.","grammar:853:ex4:structure":"この頃、〜が取れていません","grammar:853:ex4:words:0:zh":"lately","grammar:853:ex4:words:0:note":"このごろ","grammar:853:ex4:words:0:pos":"set phrase","grammar:853:ex4:words:1:zh":"friend","grammar:853:ex4:words:1:note":"ゆうじん","grammar:853:ex4:words:1:pos":"noun","grammar:853:ex4:words:2:zh":"with","grammar:853:ex4:words:2:pos":"particle","grammar:853:ex4:words:3:zh":"contact","grammar:853:ex4:words:3:note":"れんらく","grammar:853:ex4:words:3:pos":"noun","grammar:853:ex4:words:4:zh":"(nominative)","grammar:853:ex4:words:4:pos":"particle","grammar:853:ex4:words:5:zh":"haven't been able to get","grammar:853:ex4:words:5:note":"とれていません","grammar:853:ex4:words:5:pos":"verb","grammar:853:ex4:points:0":"❗このごろ: lately, these days.","grammar:853:ex4:points:1":"連絡が取れる: to be able to get in touch.","grammar:853:ex5:trans":"Childhood was the happiest time.","grammar:853:ex5:structure":"〜の頃が一番〜かったです","grammar:853:ex5:words:0:zh":"child","grammar:853:ex5:words:0:note":"こども","grammar:853:ex5:words:0:pos":"noun","grammar:853:ex5:words:1:zh":"'s","grammar:853:ex5:words:1:pos":"particle","grammar:853:ex5:words:2:zh":"time","grammar:853:ex5:words:2:note":"ころ","grammar:853:ex5:words:2:pos":"noun","grammar:853:ex5:words:3:zh":"(nominative)","grammar:853:ex5:words:3:pos":"particle","grammar:853:ex5:words:4:zh":"the most","grammar:853:ex5:words:4:note":"いちばん","grammar:853:ex5:words:4:pos":"adverb","grammar:853:ex5:words:5:zh":"(past) happy","grammar:853:ex5:words:5:note":"たのしかった","grammar:853:ex5:words:5:pos":"adjective","grammar:853:ex5:words:6:zh":"(polite form)","grammar:853:ex5:words:6:pos":"copula","grammar:853:ex5:points:0":"子供の頃: childhood.","grammar:853:ex5:points:1":"一番楽しかった: was the happiest."},"854":{"example:854:exzh":"This dish is served on a large plate.","example:854:exzh2":"I live in a big house.","example:854:exzh3":"She has a big dream.","example:854:exzh4":"I heard a loud sound.","example:854:exzh5":"The mountain looks big.","grammar:854:ex:trans":"This dish is served on a large plate.","grammar:854:ex:structure":"大きな〜に盛り付けられています","grammar:854:ex:explain":"Two key points. First, 「大きな」 is a pre-noun adjectival that can only attach to nouns (大きな皿), unlike the i-adjective 「大きい」. Second, passive: 「盛り付ける」 (to plate, to serve up) becomes 「盛り付けられる」 meaning to be plated, and with 「〜ている」 for state, 「盛り付けられています」 means it is in a plated state. 「に」 marks where it is plated.","grammar:854:ex:words:0:zh":"this","grammar:854:ex:words:0:pos":"pre-noun adjectival","grammar:854:ex:words:1:zh":"dish / cuisine","grammar:854:ex:words:1:note":"りょうり","grammar:854:ex:words:1:pos":"noun","grammar:854:ex:words:2:zh":"(topic)","grammar:854:ex:words:2:pos":"particle","grammar:854:ex:words:3:zh":"big","grammar:854:ex:words:3:note":"おおきな","grammar:854:ex:words:3:pos":"pre-noun adjectival","grammar:854:ex:words:4:zh":"dish","grammar:854:ex:words:4:note":"さら","grammar:854:ex:words:4:pos":"noun","grammar:854:ex:words:5:zh":"(the surface it is attached to)","grammar:854:ex:words:5:pos":"particle","grammar:854:ex:words:6:zh":"is plated","grammar:854:ex:words:6:note":"もりつけられています","grammar:854:ex:words:6:pos":"verb","grammar:854:ex:points:0":"❗大きな + noun: big … (pre-noun adjectival); 盛り付けられる = to be plated (passive form).","grammar:854:ex:points:1":"大きな皿: a large plate.","grammar:854:ex2:trans":"I live in a big house.","grammar:854:ex2:structure":"大きな〜に住んでいます","grammar:854:ex2:words:0:zh":"big","grammar:854:ex2:words:0:note":"おおきな","grammar:854:ex2:words:0:pos":"pre-noun adjectival","grammar:854:ex2:words:1:zh":"house","grammar:854:ex2:words:1:note":"いえ","grammar:854:ex2:words:1:pos":"noun","grammar:854:ex2:words:2:zh":"(place of residence)","grammar:854:ex2:words:2:pos":"particle","grammar:854:ex2:words:3:zh":"live (there)","grammar:854:ex2:words:3:note":"すんでいます","grammar:854:ex2:words:3:pos":"verb","grammar:854:ex2:points:0":"大きな家: a big house.","grammar:854:ex2:points:1":"〜に住む: to live in/at …","grammar:854:ex3:trans":"She has a big dream.","grammar:854:ex3:structure":"大きな〜を持っています","grammar:854:ex3:words:0:zh":"she","grammar:854:ex3:words:0:note":"かのじょ","grammar:854:ex3:words:0:pos":"pronoun","grammar:854:ex3:words:1:zh":"(topic)","grammar:854:ex3:words:1:pos":"particle","grammar:854:ex3:words:2:zh":"big","grammar:854:ex3:words:2:note":"おおきな","grammar:854:ex3:words:2:pos":"pre-noun adjectival","grammar:854:ex3:words:3:zh":"dream","grammar:854:ex3:words:3:note":"ゆめ","grammar:854:ex3:words:3:pos":"noun","grammar:854:ex3:words:4:zh":"(object marker)","grammar:854:ex3:words:4:pos":"particle","grammar:854:ex3:words:5:zh":"own, have","grammar:854:ex3:words:5:note":"もっています","grammar:854:ex3:words:5:pos":"verb","grammar:854:ex3:points:0":"❗大きな夢: a big dream.","grammar:854:ex3:points:1":"夢を持つ: to have a dream.","grammar:854:ex4:trans":"I heard a loud noise.","grammar:854:ex4:structure":"大きな〜が聞こえました","grammar:854:ex4:words:0:zh":"big","grammar:854:ex4:words:0:note":"おおきな","grammar:854:ex4:words:0:pos":"pre-noun adjectival","grammar:854:ex4:words:1:zh":"voice","grammar:854:ex4:words:1:note":"おと","grammar:854:ex4:words:1:pos":"noun","grammar:854:ex4:words:2:zh":"(nominative)","grammar:854:ex4:words:2:pos":"particle","grammar:854:ex4:words:3:zh":"heard","grammar:854:ex4:words:3:note":"きこえました","grammar:854:ex4:words:3:pos":"verb","grammar:854:ex4:points:0":"大きな音: a loud noise.","grammar:854:ex4:points:1":"音が聞こえる: to hear a sound.","grammar:854:ex5:trans":"The mountain looks big.","grammar:854:ex5:structure":"〜が大きく見えます","grammar:854:ex5:words:0:zh":"mountain","grammar:854:ex5:words:0:note":"やま","grammar:854:ex5:words:0:pos":"noun","grammar:854:ex5:words:1:zh":"(nominative)","grammar:854:ex5:words:1:pos":"particle","grammar:854:ex5:words:2:zh":"the ground","grammar:854:ex5:words:2:note":"おおきく","grammar:854:ex5:words:2:pos":"adverb","grammar:854:ex5:words:3:zh":"looks (like)","grammar:854:ex5:words:3:note":"みえます","grammar:854:ex5:words:3:pos":"verb","grammar:854:ex5:points:0":"❗大きく見える: to look big (大きい → 大きく).","grammar:854:ex5:points:1":"山が見える: to be able to see the mountain.","exam:854:zh":"All the books won't fit in this box, so please give me a bigger box.","exam:854:why":"Since not all the books fit, you need a 「大きい」 box. 「軽い」 only means light in weight and doesn't solve the lack of space."},"855":{"example:855:exzh":"He committed a crime.","example:855:exzh2":"We should protect innocent children.","example:855:exzh3":"Think about crime and punishment.","example:855:exzh4":"She works to atone for her crime.","example:855:exzh5":"It's important to recognize the sins of society."},"856":{"example:856:exzh":"My legs were tired, so I rested a little.","example:856:exzh2":"He plays soccer with his feet.","example:856:exzh3":"Please check whether the shoes fit.","example:856:exzh4":"I twisted my ankle.","example:856:exzh5":"Those shoes fit well.","grammar:856:ex:trans":"My legs were tired, so I rested a little.","grammar:856:ex:structure":"〜が疲れたので、〜ました","grammar:856:ex:explain":"Two key points. First, 「足（あし）が疲れる」 means your legs are tired, and the subject of a feeling or state takes 「が」. Second, 「〜ので」 expresses a cause or reason and sounds objective and gentle; 「疲れたので」 means because I was tired. The second half, 「少し休みました」, is the result, with 「少し」 meaning a little. The whole sentence uses a cause + ので + result structure to say that the speaker rested a bit because their legs were tired.","grammar:856:ex:words:0:zh":"legs","grammar:856:ex:words:0:note":"あし","grammar:856:ex:words:0:pos":"noun","grammar:856:ex:words:1:zh":"(nominative)","grammar:856:ex:words:1:pos":"particle","grammar:856:ex:words:2:zh":"tired","grammar:856:ex:words:2:note":"つかれた","grammar:856:ex:words:2:pos":"verb","grammar:856:ex:words:3:zh":"because","grammar:856:ex:words:3:pos":"particle","grammar:856:ex:words:4:zh":"a little","grammar:856:ex:words:4:note":"すこし","grammar:856:ex:words:4:pos":"adverb","grammar:856:ex:words:5:zh":"rested","grammar:856:ex:words:5:note":"やすみました","grammar:856:ex:words:5:pos":"verb","grammar:856:ex:points:0":"❗足（あし）: leg, foot.","grammar:856:ex:points:1":"足が疲れる: one's legs get tired (the subject takes が).","grammar:856:ex2:trans":"He plays soccer with his feet.","grammar:856:ex2:structure":"〜でサッカーをします","grammar:856:ex2:words:0:zh":"he","grammar:856:ex2:words:0:note":"かれ","grammar:856:ex2:words:0:pos":"pronoun","grammar:856:ex2:words:1:zh":"(topic)","grammar:856:ex2:words:1:pos":"particle","grammar:856:ex2:words:2:zh":"legs","grammar:856:ex2:words:2:note":"あし","grammar:856:ex2:words:2:pos":"noun","grammar:856:ex2:words:3:zh":"(means)","grammar:856:ex2:words:3:pos":"particle","grammar:856:ex2:words:4:zh":"soccer","grammar:856:ex2:words:4:note":"loanword","grammar:856:ex2:words:4:pos":"noun","grammar:856:ex2:words:5:zh":"(object marker)","grammar:856:ex2:words:5:pos":"particle","grammar:856:ex2:words:6:zh":"do","grammar:856:ex2:words:6:pos":"verb","grammar:856:ex2:points:0":"❓足で: with the feet (で = means).","grammar:856:ex2:points:1":"サッカーをする: to play soccer.","grammar:856:ex3:trans":"Please check whether the shoes fit.","grammar:856:ex3:structure":"［靴が足に合っているか］確認してください","grammar:856:ex3:explain":"「靴が足に合っている」 describes the shoes matching the size or shape of your feet, and 「合っている」 shows a state of fitting. Adding 「か」 turns the whole clause into the content being checked — whether the shoes fit. The te-form of 「確認する」 is 「確認して」, and with 「ください」 it forms a request. The 「を」 after the question clause is omitted in this sentence.","grammar:856:ex3:words:0:zh":"shoes","grammar:856:ex3:words:0:note":"くつ","grammar:856:ex3:words:0:pos":"noun","grammar:856:ex3:words:1:zh":"(nominative)","grammar:856:ex3:words:1:pos":"particle","grammar:856:ex3:words:2:zh":"legs","grammar:856:ex3:words:2:note":"あし","grammar:856:ex3:words:2:pos":"noun","grammar:856:ex3:words:3:zh":"(the thing something fits or suits)","grammar:856:ex3:words:3:pos":"particle","grammar:856:ex3:words:4:zh":"to fit, to match","grammar:856:ex3:words:4:note":"あっ","grammar:856:ex3:words:4:pos":"verb","grammar:856:ex3:words:5:zh":"(links to the verb that follows)","grammar:856:ex3:words:5:pos":"particle","grammar:856:ex3:words:6:zh":"(ongoing state)","grammar:856:ex3:words:6:pos":"verb","grammar:856:ex3:words:7:zh":"(whether)","grammar:856:ex3:words:7:pos":"particle","grammar:856:ex3:words:8:zh":"confirm","grammar:856:ex3:words:8:note":"かくにん","grammar:856:ex3:words:8:pos":"noun","grammar:856:ex3:words:9:zh":"do","grammar:856:ex3:words:9:pos":"verb","grammar:856:ex3:words:10:zh":"(links to the request expression)","grammar:856:ex3:words:10:pos":"particle","grammar:856:ex3:words:11:zh":"please","grammar:856:ex3:words:11:pos":"verb","grammar:856:ex3:points:0":"「足に合う」 means to fit your feet, and 「に」 marks the thing being fit.","grammar:856:ex3:points:1":"「普通形＋か」 embeds a yes-or-no question inside the sentence.","grammar:856:ex3:points:2":"「〜てください」 is used to politely ask someone to do something.","grammar:856:ex4:trans":"I twisted my ankle.","grammar:856:ex4:structure":"〜をひねった","grammar:856:ex4:words:0:zh":"ankle","grammar:856:ex4:words:0:note":"あしくび","grammar:856:ex4:words:0:pos":"noun","grammar:856:ex4:words:1:zh":"(object marker)","grammar:856:ex4:words:1:pos":"particle","grammar:856:ex4:words:2:zh":"twisted","grammar:856:ex4:words:2:pos":"verb","grammar:856:ex4:points:0":"足首: ankle (足 + 首).","grammar:856:ex4:points:1":"ひねる: to twist, to wrench.","grammar:856:ex5:trans":"Those shoes fit.","grammar:856:ex5:structure":"〜は足に合っている","grammar:856:ex5:words:0:zh":"that","grammar:856:ex5:words:0:pos":"pre-noun adjectival","grammar:856:ex5:words:1:zh":"shoes","grammar:856:ex5:words:1:note":"くつ","grammar:856:ex5:words:1:pos":"noun","grammar:856:ex5:words:2:zh":"(topic)","grammar:856:ex5:words:2:pos":"particle","grammar:856:ex5:words:3:zh":"legs","grammar:856:ex5:words:3:note":"あし","grammar:856:ex5:words:3:pos":"noun","grammar:856:ex5:words:4:zh":"(object)","grammar:856:ex5:words:4:pos":"particle","grammar:856:ex5:words:5:zh":"to suit","grammar:856:ex5:words:5:note":"あっている","grammar:856:ex5:words:5:pos":"verb","grammar:856:ex5:points:0":"❗〜に合う: to fit… (for shoes, the thing being fit takes に).","grammar:856:ex5:points:1":"靴が足に合う: the shoes fit your feet.","exam:856:zh":"Socks go on your feet, not on your hands.","exam:856:why":"「足」 means feet, and socks go on your feet. You can also put things on your 「頭」, but socks aren't something you wear on your head."},"858":{"example:858:exzh":"He is doing scientific research.","example:858:exzh2":"The research is progressing.","example:858:exzh3":"Research on new drugs is needed.","example:858:exzh4":"Her research is very important.","example:858:exzh5":"I will present the research results.","grammar:858:ex:trans":"He is doing scientific research.","grammar:858:ex:structure":"〜の研究をしています","grammar:858:ex:explain":"The key point is 「研究をする」, which equals 「研究する」; it uses the 「noun + を + する」 form, and many suru-verbs can be split this way. 「科学の研究」 uses 「の」 to modify, meaning research in the field of science. At the end, 「しています」 from 「〜ている」 shows an action in progress or a continuing state; here it means he is engaged in research.","grammar:858:ex:words:0:zh":"he","grammar:858:ex:words:0:note":"かれ","grammar:858:ex:words:0:pos":"pronoun","grammar:858:ex:words:1:zh":"(topic)","grammar:858:ex:words:1:pos":"particle","grammar:858:ex:words:2:zh":"science","grammar:858:ex:words:2:note":"かがく","grammar:858:ex:words:2:pos":"noun","grammar:858:ex:words:3:zh":"'s","grammar:858:ex:words:3:pos":"particle","grammar:858:ex:words:4:zh":"research","grammar:858:ex:words:4:note":"けんきゅう","grammar:858:ex:words:4:pos":"noun","grammar:858:ex:words:5:zh":"(object marker)","grammar:858:ex:words:5:pos":"particle","grammar:858:ex:words:6:zh":"is doing","grammar:858:ex:words:6:pos":"verb","grammar:858:ex:points:0":"研究をする: to do research (= 研究する).","grammar:858:ex:points:1":"科学の研究: scientific research.","grammar:858:ex2:trans":"The research is progressing.","grammar:858:ex2:structure":"〜が進んでいます","grammar:858:ex2:words:0:zh":"research","grammar:858:ex2:words:0:note":"けんきゅう","grammar:858:ex2:words:0:pos":"noun","grammar:858:ex2:words:1:zh":"(nominative)","grammar:858:ex2:words:1:pos":"particle","grammar:858:ex2:words:2:zh":"is progressing","grammar:858:ex2:words:2:note":"すすんでいます","grammar:858:ex2:words:2:pos":"verb","grammar:858:ex2:points:0":"進む: to progress (intransitive verb; the subject takes が).","grammar:858:ex2:points:1":"〜ている: in progress.","grammar:858:ex3:trans":"Research on new drugs is needed.","grammar:858:ex3:structure":"〜が必要です","grammar:858:ex3:words:0:zh":"new","grammar:858:ex3:words:0:note":"あたらしい","grammar:858:ex3:words:0:pos":"adjective","grammar:858:ex3:words:1:zh":"medicine","grammar:858:ex3:words:1:note":"くすり","grammar:858:ex3:words:1:pos":"noun","grammar:858:ex3:words:2:zh":"'s","grammar:858:ex3:words:2:pos":"particle","grammar:858:ex3:words:3:zh":"research","grammar:858:ex3:words:3:note":"けんきゅう","grammar:858:ex3:words:3:pos":"noun","grammar:858:ex3:words:4:zh":"(nominative)","grammar:858:ex3:words:4:pos":"particle","grammar:858:ex3:words:5:zh":"necessary","grammar:858:ex3:words:5:note":"ひつよう","grammar:858:ex3:words:5:pos":"na-adjective","grammar:858:ex3:words:6:zh":"(polite form)","grammar:858:ex3:words:6:pos":"copula","grammar:858:ex3:points:0":"新しい薬の研究: research on new drugs.","grammar:858:ex3:points:1":"「〜が必要です」: need …","grammar:858:ex4:trans":"Her research is very important.","grammar:858:ex4:structure":"〜はとても重要です","grammar:858:ex4:words:0:zh":"she","grammar:858:ex4:words:0:note":"かのじょ","grammar:858:ex4:words:0:pos":"pronoun","grammar:858:ex4:words:1:zh":"'s","grammar:858:ex4:words:1:pos":"particle","grammar:858:ex4:words:2:zh":"research","grammar:858:ex4:words:2:note":"けんきゅう","grammar:858:ex4:words:2:pos":"noun","grammar:858:ex4:words:3:zh":"(topic)","grammar:858:ex4:words:3:pos":"particle","grammar:858:ex4:words:4:zh":"extremely","grammar:858:ex4:words:4:pos":"adverb","grammar:858:ex4:words:5:zh":"important","grammar:858:ex4:words:5:note":"じゅうよう","grammar:858:ex4:words:5:pos":"na-adjective","grammar:858:ex4:words:6:zh":"(polite form)","grammar:858:ex4:words:6:pos":"copula","grammar:858:ex4:points:0":"彼女の研究: her research.","grammar:858:ex4:points:1":"とても重要：very important.","grammar:858:ex5:trans":"I will present the research results.","grammar:858:ex5:structure":"〜を発表します","grammar:858:ex5:words:0:zh":"research results","grammar:858:ex5:words:0:note":"けんきゅうけっか","grammar:858:ex5:words:0:pos":"noun","grammar:858:ex5:words:1:zh":"(object marker)","grammar:858:ex5:words:1:pos":"particle","grammar:858:ex5:words:2:zh":"present (announce)","grammar:858:ex5:words:2:note":"はっぴょうします","grammar:858:ex5:words:2:pos":"verb","grammar:858:ex5:points:0":"研究結果: research results.","grammar:858:ex5:points:1":"発表する: to present, to announce."},"859":{"example:859:exzh":"I'm walking in the park.","example:859:exzh2":"I walk to school every day.","example:859:exzh3":"If you walk along this road, you'll arrive soon.","example:859:exzh4":"Let's walk quickly so we're not late.","example:859:exzh5":"He walks fast.","grammar:859:ex:trans":"I'm taking a walk in the park.","grammar:859:ex:structure":"〜を歩いています","grammar:859:ex:explain":"The point is the special use of the particle 「を」: it marks the path or place of movement. With verbs of motion like 「歩く」, 「走る」, and 「散歩する」, the space you pass through takes 「を」, not 「で」, so 「公園を歩く」 means walking around in the park. At the end, 「歩いています」 from 「〜ている」 shows an action in progress, so the whole sentence means I'm taking a walk in the park.","grammar:859:ex:words:0:zh":"park","grammar:859:ex:words:0:note":"こうえん","grammar:859:ex:words:0:pos":"noun","grammar:859:ex:words:1:zh":"(path)","grammar:859:ex:words:1:pos":"particle","grammar:859:ex:words:2:zh":"walking","grammar:859:ex:words:2:note":"あるいています","grammar:859:ex:words:2:pos":"verb","grammar:859:ex:points:0":"❓公園を歩く: to walk in the park (the path of movement takes を).","grammar:859:ex:points:1":"〜ている: ongoing action.","grammar:859:ex2:trans":"I walk to school every day.","grammar:859:ex2:structure":"〜まで歩きます","grammar:859:ex2:words:0:zh":"every day","grammar:859:ex2:words:0:note":"まいにち","grammar:859:ex2:words:0:pos":"adverb","grammar:859:ex2:words:1:zh":"school","grammar:859:ex2:words:1:note":"がっこう","grammar:859:ex2:words:1:pos":"noun","grammar:859:ex2:words:2:zh":"until","grammar:859:ex2:words:2:pos":"particle","grammar:859:ex2:words:3:zh":"walk","grammar:859:ex2:words:3:note":"あるきます","grammar:859:ex2:words:3:pos":"verb","grammar:859:ex2:points:0":"〜まで歩く: to walk to…","grammar:859:ex2:points:1":"毎日: every day.","grammar:859:ex3:trans":"If you take this road, you'll arrive right away.","grammar:859:ex3:structure":"〜ば、〜着きます","grammar:859:ex3:words:0:zh":"this","grammar:859:ex3:words:0:pos":"pre-noun adjectival","grammar:859:ex3:words:1:zh":"road","grammar:859:ex3:words:1:note":"みち","grammar:859:ex3:words:1:pos":"noun","grammar:859:ex3:words:2:zh":"(path)","grammar:859:ex3:words:2:pos":"particle","grammar:859:ex3:words:3:zh":"if you walk","grammar:859:ex3:words:3:note":"あるけば","grammar:859:ex3:words:3:pos":"verb","grammar:859:ex3:words:4:zh":"soon","grammar:859:ex3:words:4:pos":"adverb","grammar:859:ex3:words:5:zh":"arrive","grammar:859:ex3:words:5:note":"つきます","grammar:859:ex3:words:5:pos":"verb","grammar:859:ex3:points:0":"❗〜ば: if… (歩く → 歩けば).","grammar:859:ex3:points:1":"着く: to arrive.","grammar:859:ex4:trans":"Let's walk faster so we're not late.","grammar:859:ex4:structure":"〜ないように歩きましょう","grammar:859:ex4:words:0:zh":"so as not to be late","grammar:859:ex4:words:0:note":"おくれない","grammar:859:ex4:words:0:pos":"verb","grammar:859:ex4:words:1:zh":"so as not to","grammar:859:ex4:words:1:pos":"particle","grammar:859:ex4:words:2:zh":"let's go","grammar:859:ex4:words:2:note":"あるきましょう","grammar:859:ex4:words:2:pos":"verb","grammar:859:ex4:points:0":"❗〜ないように: so as not to …; to avoid ….","grammar:859:ex4:points:1":"遅れる: to be late.","grammar:859:ex5:trans":"He walks fast.","grammar:859:ex5:structure":"〜は速く歩きます","grammar:859:ex5:words:0:zh":"he","grammar:859:ex5:words:0:note":"かれ","grammar:859:ex5:words:0:pos":"pronoun","grammar:859:ex5:words:1:zh":"(topic)","grammar:859:ex5:words:1:pos":"particle","grammar:859:ex5:words:2:zh":"quickly","grammar:859:ex5:words:2:note":"はやく","grammar:859:ex5:words:2:pos":"adverb","grammar:859:ex5:words:3:zh":"walk","grammar:859:ex5:words:3:note":"あるきます","grammar:859:ex5:words:3:pos":"verb","grammar:859:ex5:points:0":"速く歩く: to walk fast (速い → 速く).","grammar:859:ex5:points:1":"彼は: he (topic).","exam:859:zh":"I decided not to take the bus and to go to the station on foot.","exam:859:why":"「歩く」 means to walk on foot, which fits not taking the bus and walking to the station. 「登る」 means to climb upward, and there's no such route in this sentence."},"860":{"example:860:exzh":"He showed his opinion through his actions.","example:860:exzh2":"It's important to take action.","example:860:exzh3":"We need to act as a team.","example:860:exzh4":"You should think before you act.","example:860:exzh5":"He acted with courage."},"861":{"example:861:exzh":"Actually, he didn't think so.","example:861:exzh2":"The truth is, we don't have time.","example:861:exzh3":"We need to check the actual figures.","example:861:exzh4":"In reality, it was much harder.","example:861:exzh5":"She is actually an experienced person."},"862":{"example:862:exzh":"Few people know that this problem exists.","example:862:exzh2":"His presence cheers me up.","example:862:exzh3":"It's important to exist.","example:862:exzh4":"That idea exists.","example:862:exzh5":"Her presence is special to me."},"863":{"example:863:exzh":"He discovered a new star.","example:863:exzh2":"This discovery will have a big impact on medicine.","example:863:exzh3":"The discovered ruins are very interesting.","example:863:exzh4":"Discovery always brings new knowledge.","example:863:exzh5":"Her discovery won an award."},"864":{"example:864:exzh":"Let's think about how to solve the problem.","example:864:exzh2":"He can solve that problem.","example:864:exzh3":"We must find a solution.","example:864:exzh4":"Solving this problem is urgent.","example:864:exzh5":"It takes time to solve it."},"865":{"example:865:exzh":"Prison is a harsh environment.","example:865:exzh2":"Laws concerning prisons are needed.","example:865:exzh3":"His prison life was harsh.","example:865:exzh4":"Prison reform is being carried out.","example:865:exzh5":"She talked about her experience in prison."},"866":{"example:866:exzh":"He ran after the cat.","example:866:exzh2":"It's important to chase your dreams.","example:866:exzh3":"The dog is chasing the ball.","example:866:exzh4":"The statute of limitations is running out, so we have to pursue it.","example:866:exzh5":"She chased after the bus."},"867":{"example:867:exzh":"Please tell me my number.","example:867:exzh2":"I need to check the postal code.","example:867:exzh3":"That number seems to be wrong.","example:867:exzh4":"Please tell me your phone number.","example:867:exzh5":"If you need a number, please let me know.","grammar:867:ex:trans":"Please tell me my number.","grammar:867:ex:structure":"〜を教えてください","grammar:867:ex:explain":"「番号（ばんごう）」 means number. The pattern is the request 「〜てください」: the te-form of the verb 「教える」, 「教えて」, plus 「ください」 politely asks someone to tell you something. In 「私の番号」, 「の」 shows possession and 「を」 marks the object. Note that 「教える」 here means to tell, not to teach; the Japanese 「教える」 carries both meanings, so judge from the context.","grammar:867:ex:words:0:zh":"I","grammar:867:ex:words:0:note":"わたし","grammar:867:ex:words:0:pos":"pronoun","grammar:867:ex:words:1:zh":"'s","grammar:867:ex:words:1:pos":"particle","grammar:867:ex:words:2:zh":"number","grammar:867:ex:words:2:note":"ばんごう","grammar:867:ex:words:2:pos":"noun","grammar:867:ex:words:3:zh":"(object marker)","grammar:867:ex:words:3:pos":"particle","grammar:867:ex:words:4:zh":"tell","grammar:867:ex:words:4:note":"おしえて","grammar:867:ex:words:4:pos":"verb","grammar:867:ex:words:5:zh":"please","grammar:867:ex:words:5:pos":"auxiliary verb","grammar:867:ex:points:0":"番号（ばんごう）: number.","grammar:867:ex:points:1":"教える→教えて＋ください。","grammar:867:ex2:trans":"We need to check the postal code.","grammar:867:ex2:structure":"〜必要がある","grammar:867:ex2:words:0:zh":"postal code","grammar:867:ex2:words:0:note":"ゆうびんばんごう","grammar:867:ex2:words:0:pos":"noun","grammar:867:ex2:words:1:zh":"(object marker)","grammar:867:ex2:words:1:pos":"particle","grammar:867:ex2:words:2:zh":"confirm","grammar:867:ex2:words:2:note":"かくにんする","grammar:867:ex2:words:2:pos":"verb","grammar:867:ex2:words:3:zh":"necessary","grammar:867:ex2:words:3:note":"ひつよう","grammar:867:ex2:words:3:pos":"noun","grammar:867:ex2:words:4:zh":"(nominative)","grammar:867:ex2:words:4:pos":"particle","grammar:867:ex2:words:5:zh":"there is / are","grammar:867:ex2:words:5:pos":"verb","grammar:867:ex2:points:0":"郵便番号: postal code (郵便 + 番号).","grammar:867:ex2:points:1":"〜必要がある: it is necessary to ….","grammar:867:ex3:trans":"That number seems to be wrong.","grammar:867:ex3:structure":"〜のようです","grammar:867:ex3:words:0:zh":"that","grammar:867:ex3:words:0:pos":"pre-noun adjectival","grammar:867:ex3:words:1:zh":"number","grammar:867:ex3:words:1:note":"ばんごう","grammar:867:ex3:words:1:pos":"noun","grammar:867:ex3:words:2:zh":"(topic)","grammar:867:ex3:words:2:pos":"particle","grammar:867:ex3:words:3:zh":"Mistake","grammar:867:ex3:words:3:note":"おまちがい","grammar:867:ex3:words:3:pos":"noun","grammar:867:ex3:words:4:zh":"(assertion)","grammar:867:ex3:words:4:pos":"particle","grammar:867:ex3:words:5:zh":"seems","grammar:867:ex3:words:5:pos":"auxiliary verb","grammar:867:ex3:points:0":"❗〜のようです: seems… (guess).","grammar:867:ex3:points:1":"お間違い: (polite) a mistake.","grammar:867:ex4:trans":"Please tell me your phone number.","grammar:867:ex4:structure":"〜を教えてください","grammar:867:ex4:words:0:zh":"phone number","grammar:867:ex4:words:0:note":"でんわばんごう","grammar:867:ex4:words:0:pos":"noun","grammar:867:ex4:words:1:zh":"(object marker)","grammar:867:ex4:words:1:pos":"particle","grammar:867:ex4:words:2:zh":"tell","grammar:867:ex4:words:2:note":"おしえて","grammar:867:ex4:words:2:pos":"verb","grammar:867:ex4:words:3:zh":"please","grammar:867:ex4:words:3:pos":"auxiliary verb","grammar:867:ex4:points:0":"電話番号: phone number.","grammar:867:ex4:points:1":"教える→教えて＋ください。","grammar:867:ex5:trans":"If you need the number, please tell me.","grammar:867:ex5:structure":"〜場合は、〜てください","grammar:867:ex5:words:0:zh":"number","grammar:867:ex5:words:0:note":"ばんごう","grammar:867:ex5:words:0:pos":"noun","grammar:867:ex5:words:1:zh":"(nominative)","grammar:867:ex5:words:1:pos":"particle","grammar:867:ex5:words:2:zh":"necessary","grammar:867:ex5:words:2:note":"ひつよう","grammar:867:ex5:words:2:pos":"na-adjective","grammar:867:ex5:words:3:zh":"(attributive form)","grammar:867:ex5:words:3:pos":"auxiliary verb","grammar:867:ex5:words:4:zh":"case","grammar:867:ex5:words:4:note":"ばあい","grammar:867:ex5:words:4:pos":"noun","grammar:867:ex5:words:5:zh":"(contrast)","grammar:867:ex5:words:5:pos":"particle","grammar:867:ex5:words:6:zh":"tell","grammar:867:ex5:words:6:note":"おしえて","grammar:867:ex5:words:6:pos":"verb","grammar:867:ex5:words:7:zh":"please","grammar:867:ex5:words:7:pos":"auxiliary verb","grammar:867:ex5:points:0":"❗〜場合は: in the case where…","grammar:867:ex5:points:1":"番号が必要: a number is needed.","exam:867:zh":"I want to make a phone call, so please tell me Tanaka's phone number.","exam:867:why":"「電話番号」 is a phone number, which you need to make a call. 「住所」 is an address, so it can't combine with 「電話」 to make the word needed here."},"868":{"example:868:exzh":"I threw away old clothes.","example:868:exzh2":"I'm looking for a place to throw away trash.","example:868:exzh3":"Let's think about what to throw away and what to keep.","example:868:exzh4":"It's better to throw away things you don't need.","example:868:exzh5":"He threw away that old book.","grammar:868:ex:trans":"I threw away old clothes.","grammar:868:ex:structure":"〜を捨てました","grammar:868:ex:explain":"「捨てる（すてる）」 is a transitive verb meaning to throw away, to discard, and its object takes 「を」. The i-adjective 「古い」 attaches directly to the noun 「服」, so 「古い服」 is old clothes. The past polite 「捨てました」 shows the action is done. The whole sentence means: I threw away old clothes. It's a very everyday action; the point is to remember the verb 「捨てる」 and its pairing with the object marker 「を」.","grammar:868:ex:words:0:zh":"old","grammar:868:ex:words:0:note":"ふるい","grammar:868:ex:words:0:pos":"adjective","grammar:868:ex:words:1:zh":"clothes","grammar:868:ex:words:1:note":"ふく","grammar:868:ex:words:1:pos":"noun","grammar:868:ex:words:2:zh":"(object marker)","grammar:868:ex:words:2:pos":"particle","grammar:868:ex:words:3:zh":"threw away","grammar:868:ex:words:3:note":"すてました","grammar:868:ex:words:3:pos":"verb","grammar:868:ex:points:0":"❗捨てる（すてる）: to throw away, to discard (transitive verb).","grammar:868:ex:points:1":"古い服を捨てる: throw away old clothes.","grammar:868:ex2:trans":"I'm looking for a place to throw away trash.","grammar:868:ex2:structure":"〜を捨てる場所を探している","grammar:868:ex2:words:0:zh":"trash","grammar:868:ex2:words:0:pos":"noun","grammar:868:ex2:words:1:zh":"(object marker)","grammar:868:ex2:words:1:pos":"particle","grammar:868:ex2:words:2:zh":"throw away","grammar:868:ex2:words:2:note":"すてる","grammar:868:ex2:words:2:pos":"verb","grammar:868:ex2:words:3:zh":"place","grammar:868:ex2:words:3:note":"ばしょ","grammar:868:ex2:words:3:pos":"noun","grammar:868:ex2:words:4:zh":"(object marker)","grammar:868:ex2:words:4:pos":"particle","grammar:868:ex2:words:5:zh":"are looking for","grammar:868:ex2:words:5:note":"さがしている","grammar:868:ex2:words:5:pos":"verb","grammar:868:ex2:points:0":"❗ゴミを捨てる: to throw away trash.","grammar:868:ex2:points:1":"捨てる場所: a place to throw things away (attributive use).","grammar:868:ex3:trans":"Let's think about what we should throw away and what we should keep.","grammar:868:ex3:structure":"〜べきものと〜べきものを考えよう","grammar:868:ex3:words:0:zh":"throw away","grammar:868:ex3:words:0:note":"すてる","grammar:868:ex3:words:0:pos":"verb","grammar:868:ex3:words:1:zh":"should","grammar:868:ex3:words:1:pos":"auxiliary verb","grammar:868:ex3:words:2:zh":"things","grammar:868:ex3:words:2:pos":"noun","grammar:868:ex3:words:3:zh":"with","grammar:868:ex3:words:3:pos":"particle","grammar:868:ex3:words:4:zh":"remain","grammar:868:ex3:words:4:note":"のこす","grammar:868:ex3:words:4:pos":"verb","grammar:868:ex3:words:5:zh":"should","grammar:868:ex3:words:5:pos":"auxiliary verb","grammar:868:ex3:words:6:zh":"things","grammar:868:ex3:words:6:pos":"noun","grammar:868:ex3:words:7:zh":"(object marker)","grammar:868:ex3:words:7:pos":"particle","grammar:868:ex3:words:8:zh":"let's think","grammar:868:ex3:words:8:note":"かんがえよう","grammar:868:ex3:words:8:pos":"verb","grammar:868:ex3:points:0":"❗〜べきもの: the things one should …; 捨てる vs 残す (throw away / keep).","grammar:868:ex3:points:1":"考えよう: let's think (volitional form).","grammar:868:ex4:trans":"It's better to throw away useless things.","grammar:868:ex4:structure":"〜は捨てた方がいい","grammar:868:ex4:words:0:zh":"unnecessary","grammar:868:ex4:words:0:note":"むだ","grammar:868:ex4:words:0:pos":"na-adjective","grammar:868:ex4:words:1:zh":"(attributive form)","grammar:868:ex4:words:1:pos":"auxiliary verb","grammar:868:ex4:words:2:zh":"things","grammar:868:ex4:words:2:pos":"noun","grammar:868:ex4:words:3:zh":"(topic)","grammar:868:ex4:words:3:pos":"particle","grammar:868:ex4:words:4:zh":"throw away","grammar:868:ex4:words:4:note":"すてた","grammar:868:ex4:words:4:pos":"verb","grammar:868:ex4:words:5:zh":"it's better to","grammar:868:ex4:words:5:note":"ほうがいい","grammar:868:ex4:words:5:pos":"set phrase","grammar:868:ex4:points:0":"❗〜た方がいい: it's better to … (advice); 無駄なもの = useless things.","grammar:868:ex4:points:1":"捨てる: to throw away.","grammar:868:ex5:trans":"He threw away that old book.","grammar:868:ex5:structure":"〜を捨てた","grammar:868:ex5:words:0:zh":"he","grammar:868:ex5:words:0:note":"かれ","grammar:868:ex5:words:0:pos":"pronoun","grammar:868:ex5:words:1:zh":"(topic)","grammar:868:ex5:words:1:pos":"particle","grammar:868:ex5:words:2:zh":"that","grammar:868:ex5:words:2:pos":"pre-noun adjectival","grammar:868:ex5:words:3:zh":"old","grammar:868:ex5:words:3:note":"ふるい","grammar:868:ex5:words:3:pos":"adjective","grammar:868:ex5:words:4:zh":"book","grammar:868:ex5:words:4:note":"ほん","grammar:868:ex5:words:4:pos":"noun","grammar:868:ex5:words:5:zh":"(object marker)","grammar:868:ex5:words:5:pos":"particle","grammar:868:ex5:words:6:zh":"threw away","grammar:868:ex5:words:6:note":"すてた","grammar:868:ex5:words:6:pos":"verb","grammar:868:ex5:points:0":"古い本: an old book.","grammar:868:ex5:points:1":"捨てる → 捨てた."},"869":{"example:869:exzh":"I have two older brothers.","example:869:exzh2":"He is a kind older brother.","example:869:exzh3":"My older brother likes traveling.","example:869:exzh4":"His older brother is a university student.","example:869:exzh5":"I play with my older brother.","grammar:869:ex:trans":"I have two older brothers.","grammar:869:ex:structure":"〜には〜がいる","grammar:869:ex:explain":"Two key points. First, 「兄（あに）」 is the humble word for one's own older brother; to refer to someone else's older brother you use 「お兄さん」. Second, the existential pattern 「〜には〜がいる」: 「私に」 means 'at/for me', and adding 「は」 gives a contrastive, topic-marking nuance; 「兄がいる」 means 'there is an older brother', and 「いる」 is used for people. 「二人（ふたり）」 is the quantity. The whole sentence means 'I have two older brothers'.","grammar:869:ex:words:0:zh":"I","grammar:869:ex:words:0:note":"わたし","grammar:869:ex:words:0:pos":"pronoun","grammar:869:ex:words:1:zh":"(object)","grammar:869:ex:words:1:pos":"particle","grammar:869:ex:words:2:zh":"(contrast)","grammar:869:ex:words:2:pos":"particle","grammar:869:ex:words:3:zh":"older brother","grammar:869:ex:words:3:note":"あに","grammar:869:ex:words:3:pos":"noun","grammar:869:ex:words:4:zh":"(nominative)","grammar:869:ex:words:4:pos":"particle","grammar:869:ex:words:5:zh":"two people","grammar:869:ex:words:5:note":"ふたり","grammar:869:ex:words:5:pos":"noun","grammar:869:ex:words:6:zh":"there is / are","grammar:869:ex:words:6:pos":"verb","grammar:869:ex:points:0":"❗兄（あに）: (humble) one's own older brother; for someone else's older brother use お兄さん.","grammar:869:ex:points:1":"〜には〜がいる: (someone) has … (a person).","grammar:869:ex2:trans":"He is a gentle older brother.","grammar:869:ex2:structure":"〜として〜人だ","grammar:869:ex2:words:0:zh":"he","grammar:869:ex2:words:0:note":"かれ","grammar:869:ex2:words:0:pos":"pronoun","grammar:869:ex2:words:1:zh":"(topic)","grammar:869:ex2:words:1:pos":"particle","grammar:869:ex2:words:2:zh":"older brother","grammar:869:ex2:words:2:note":"あに","grammar:869:ex2:words:2:pos":"noun","grammar:869:ex2:words:3:zh":"as","grammar:869:ex2:words:3:pos":"set phrase","grammar:869:ex2:words:4:zh":"kind","grammar:869:ex2:words:4:note":"やさしい","grammar:869:ex2:words:4:pos":"adjective","grammar:869:ex2:words:5:zh":"person","grammar:869:ex2:words:5:note":"ひと","grammar:869:ex2:words:5:pos":"noun","grammar:869:ex2:words:6:zh":"is","grammar:869:ex2:words:6:pos":"copula","grammar:869:ex2:points:0":"❗〜として: as… (in the role of).","grammar:869:ex2:points:1":"優しい人: a gentle person.","grammar:869:ex3:trans":"My older brother likes traveling.","grammar:869:ex3:structure":"〜は〜が好きだ","grammar:869:ex3:words:0:zh":"older brother","grammar:869:ex3:words:0:note":"あに","grammar:869:ex3:words:0:pos":"noun","grammar:869:ex3:words:1:zh":"(topic)","grammar:869:ex3:words:1:pos":"particle","grammar:869:ex3:words:2:zh":"travel / trip","grammar:869:ex3:words:2:note":"りょこう","grammar:869:ex3:words:2:pos":"noun","grammar:869:ex3:words:3:zh":"(object)","grammar:869:ex3:words:3:pos":"particle","grammar:869:ex3:words:4:zh":"to like","grammar:869:ex3:words:4:note":"すき","grammar:869:ex3:words:4:pos":"na-adjective","grammar:869:ex3:words:5:zh":"is","grammar:869:ex3:words:5:pos":"copula","grammar:869:ex3:points:0":"旅行が好き: to like traveling.","grammar:869:ex3:points:1":"兄は: older brother (topic).","grammar:869:ex4:trans":"His older brother is a university student.","grammar:869:ex4:structure":"〜は〜です","grammar:869:ex4:words:0:zh":"he","grammar:869:ex4:words:0:note":"かれ","grammar:869:ex4:words:0:pos":"pronoun","grammar:869:ex4:words:1:zh":"'s","grammar:869:ex4:words:1:pos":"particle","grammar:869:ex4:words:2:zh":"older brother","grammar:869:ex4:words:2:note":"あに","grammar:869:ex4:words:2:pos":"noun","grammar:869:ex4:words:3:zh":"(topic)","grammar:869:ex4:words:3:pos":"particle","grammar:869:ex4:words:4:zh":"university student","grammar:869:ex4:words:4:note":"だいがくせい","grammar:869:ex4:words:4:pos":"noun","grammar:869:ex4:words:5:zh":"is","grammar:869:ex4:words:5:pos":"copula","grammar:869:ex4:points:0":"❗彼の兄: his older brother (you can use 兄, or say お兄さん).","grammar:869:ex4:points:1":"大学生: university student.","grammar:869:ex5:trans":"I play together with my older brother.","grammar:869:ex5:structure":"〜と一緒に遊びます","grammar:869:ex5:words:0:zh":"older brother","grammar:869:ex5:words:0:note":"あに","grammar:869:ex5:words:0:pos":"noun","grammar:869:ex5:words:1:zh":"with","grammar:869:ex5:words:1:pos":"particle","grammar:869:ex5:words:2:zh":"together","grammar:869:ex5:words:2:note":"いっしょに","grammar:869:ex5:words:2:pos":"adverb","grammar:869:ex5:words:3:zh":"hang out","grammar:869:ex5:words:3:note":"あそびます","grammar:869:ex5:words:3:pos":"verb","grammar:869:ex5:points:0":"兄と一緒に: together with older brother.","grammar:869:ex5:points:1":"遊ぶ→遊びます。","exam:869:zh":"I'm eighteen, and I have a twenty-year-old male sibling, who is my older brother.","exam:869:why":"A male sibling older than you is 「兄」. 「弟」 is also a male sibling, but younger than you."},"870":{"example:870:exzh":"You can get around by bus.","example:870:exzh2":"He moved to a new town.","example:870:exzh3":"Let's get going so we won't be late.","example:870:exzh4":"She gets around on foot every day.","example:870:exzh5":"This way is the fastest way to get around."},"871":{"example:871:exzh":"I deposited money in the bank.","example:871:exzh2":"A new bank opened nearby.","example:871:exzh3":"I'm planning to open an account at the bank.","example:871:exzh4":"The bank's ATM is convenient.","example:871:exzh5":"You have to go to the bank to withdraw money.","grammar:871:ex:trans":"I deposited the money in the bank.","grammar:871:ex:structure":"〜に〜を預けました","grammar:871:ex:explain":"The core is 「〜にお金を預ける」, which means to deposit money into…; the place where it is kept takes 「に」. The verb 「預ける（あずける）」 means to leave something in someone's care, to entrust, to deposit, and its object (お金) takes 「を」. The past polite form 「預けました」 shows the action is completed. The 「お」 in 「お金」 is a beautifying prefix. The whole sentence means 'I deposited the money in the bank'.","grammar:871:ex:words:0:zh":"bank","grammar:871:ex:words:0:note":"ぎんこう","grammar:871:ex:words:0:pos":"noun","grammar:871:ex:words:1:zh":"(the destination point)","grammar:871:ex:words:1:pos":"particle","grammar:871:ex:words:2:zh":"money","grammar:871:ex:words:2:note":"おかね","grammar:871:ex:words:2:pos":"noun","grammar:871:ex:words:3:zh":"(object marker)","grammar:871:ex:words:3:pos":"particle","grammar:871:ex:words:4:zh":"deposited","grammar:871:ex:words:4:note":"あずけました","grammar:871:ex:words:4:pos":"verb","grammar:871:ex:points:0":"❗〜にお金を預ける: to deposit money into… (「に」 marks where it is kept).","grammar:871:ex:points:1":"預ける: to leave in someone's care; to deposit.","grammar:871:ex2:trans":"A new bank opened nearby.","grammar:871:ex2:structure":"〜ができました","grammar:871:ex2:words:0:zh":"nearby","grammar:871:ex2:words:0:note":"ちかく","grammar:871:ex2:words:0:pos":"noun","grammar:871:ex2:words:1:zh":"(location of existence)","grammar:871:ex2:words:1:pos":"particle","grammar:871:ex2:words:2:zh":"new","grammar:871:ex2:words:2:note":"あたらしい","grammar:871:ex2:words:2:pos":"adjective","grammar:871:ex2:words:3:zh":"bank","grammar:871:ex2:words:3:note":"ぎんこう","grammar:871:ex2:words:3:pos":"noun","grammar:871:ex2:words:4:zh":"(nominative)","grammar:871:ex2:words:4:pos":"particle","grammar:871:ex2:words:5:zh":"Was built","grammar:871:ex2:words:5:pos":"verb","grammar:871:ex2:points:0":"❗〜ができる: (for a shop, etc.) to open; to be built.","grammar:871:ex2:points:1":"近くに: nearby; in the area.","grammar:871:ex3:trans":"I plan to open an account at the bank.","grammar:871:ex3:structure":"〜で〜を開くつもりです","grammar:871:ex3:words:0:zh":"bank","grammar:871:ex3:words:0:note":"ぎんこう","grammar:871:ex3:words:0:pos":"noun","grammar:871:ex3:words:1:zh":"(place)","grammar:871:ex3:words:1:pos":"particle","grammar:871:ex3:words:2:zh":"account","grammar:871:ex3:words:2:note":"こうざ","grammar:871:ex3:words:2:pos":"noun","grammar:871:ex3:words:3:zh":"(object marker)","grammar:871:ex3:words:3:pos":"particle","grammar:871:ex3:words:4:zh":"open","grammar:871:ex3:words:4:note":"ひらく","grammar:871:ex3:words:4:pos":"verb","grammar:871:ex3:words:5:zh":"intend to","grammar:871:ex3:words:5:pos":"noun","grammar:871:ex3:words:6:zh":"(polite form)","grammar:871:ex3:words:6:pos":"copula","grammar:871:ex3:points:0":"❗口座を開く: to open an account (fixed expression; use 開く).","grammar:871:ex3:points:1":"〜つもりです: intend to ….","grammar:871:ex4:trans":"The bank's ATM is convenient.","grammar:871:ex4:structure":"〜は便利です","grammar:871:ex4:words:0:zh":"bank","grammar:871:ex4:words:0:note":"ぎんこう","grammar:871:ex4:words:0:pos":"noun","grammar:871:ex4:words:1:zh":"'s","grammar:871:ex4:words:1:pos":"particle","grammar:871:ex4:words:2:zh":"ATM","grammar:871:ex4:words:2:pos":"noun","grammar:871:ex4:words:3:zh":"(topic)","grammar:871:ex4:words:3:pos":"particle","grammar:871:ex4:words:4:zh":"convenient","grammar:871:ex4:words:4:note":"べんり","grammar:871:ex4:words:4:pos":"na-adjective","grammar:871:ex4:words:5:zh":"(polite form)","grammar:871:ex4:words:5:pos":"copula","grammar:871:ex4:points:0":"ATM: automated teller machine.","grammar:871:ex4:points:1":"便利: convenient.","grammar:871:ex5:trans":"To withdraw money, you have to go to the bank.","grammar:871:ex5:structure":"〜には〜なければなりません","grammar:871:ex5:words:0:zh":"money","grammar:871:ex5:words:0:note":"おかね","grammar:871:ex5:words:0:pos":"noun","grammar:871:ex5:words:1:zh":"(object marker)","grammar:871:ex5:words:1:pos":"particle","grammar:871:ex5:words:2:zh":"withdraw","grammar:871:ex5:words:2:note":"ひきだす","grammar:871:ex5:words:2:pos":"verb","grammar:871:ex5:words:3:zh":"(in order to)","grammar:871:ex5:words:3:pos":"particle","grammar:871:ex5:words:4:zh":"bank","grammar:871:ex5:words:4:note":"ぎんこう","grammar:871:ex5:words:4:pos":"noun","grammar:871:ex5:words:5:zh":"(destination)","grammar:871:ex5:words:5:pos":"particle","grammar:871:ex5:words:6:zh":"have to go","grammar:871:ex5:words:6:note":"いかなければなりません","grammar:871:ex5:words:6:pos":"verb","grammar:871:ex5:points:0":"お金を引き出す: to withdraw money.","grammar:871:ex5:points:1":"〜には〜なければなりません: to…, you must…","exam:871:zh":"I want to borrow money, so I'll go to the bank and talk it over.","exam:871:why":"「銀行」 provides financial services such as loans, which fits the purpose here. You can borrow books at a 「図書館」, but it isn't a place to arrange a loan."},"872":{"example:872:exzh":"He injured his hand.","example:872:exzh2":"It takes time for a wound to heal.","example:872:exzh3":"This injury hurts.","example:872:exzh4":"Please disinfect this wound.","example:872:exzh5":"I got hurt when I fell down."},"873":{"example:873:exzh":"This room is very quiet.","example:873:exzh2":"Her voice is quiet.","example:873:exzh3":"I want to study in a quiet place.","example:873:exzh4":"The park was quiet.","example:873:exzh5":"I like quiet nights.","grammar:873:ex:trans":"This room is very quiet.","grammar:873:ex:structure":"〜はとても静かです","grammar:873:ex:explain":"「静か（しずか）」 is a na-adjective meaning quiet. The pattern is 「〜はとても静かです」: the adverb 「とても」 intensifies and modifies 「静か」, and when a na-adjective is the predicate it attaches directly to 「です」 to become polite. The topic 「この部屋」 is marked with 「は」. Remember that a na-adjective as predicate does not take 「な」 — 「静かです」 is enough; 「な」 is only needed before a noun, as in 「静かな部屋」.","grammar:873:ex:words:0:zh":"this","grammar:873:ex:words:0:pos":"pre-noun adjectival","grammar:873:ex:words:1:zh":"room","grammar:873:ex:words:1:note":"へや","grammar:873:ex:words:1:pos":"noun","grammar:873:ex:words:2:zh":"(topic)","grammar:873:ex:words:2:pos":"particle","grammar:873:ex:words:3:zh":"extremely","grammar:873:ex:words:3:pos":"adverb","grammar:873:ex:words:4:zh":"quiet","grammar:873:ex:words:4:note":"しずか","grammar:873:ex:words:4:pos":"na-adjective","grammar:873:ex:words:5:zh":"(polite form)","grammar:873:ex:words:5:pos":"copula","grammar:873:ex:points:0":"静か（しずか）: quiet (na-adjective).","grammar:873:ex:points:1":"この部屋: this room.","grammar:873:ex2:trans":"Her voice is quiet.","grammar:873:ex2:structure":"〜は静かです","grammar:873:ex2:words:0:zh":"she","grammar:873:ex2:words:0:note":"かのじょ","grammar:873:ex2:words:0:pos":"pronoun","grammar:873:ex2:words:1:zh":"'s","grammar:873:ex2:words:1:pos":"particle","grammar:873:ex2:words:2:zh":"voice","grammar:873:ex2:words:2:note":"こえ","grammar:873:ex2:words:2:pos":"noun","grammar:873:ex2:words:3:zh":"(topic)","grammar:873:ex2:words:3:pos":"particle","grammar:873:ex2:words:4:zh":"gentle","grammar:873:ex2:words:4:note":"しずか","grammar:873:ex2:words:4:pos":"na-adjective","grammar:873:ex2:words:5:zh":"(polite form)","grammar:873:ex2:words:5:pos":"copula","grammar:873:ex2:points:0":"静かな声: a gentle voice.","grammar:873:ex2:points:1":"彼女の声: her voice.","grammar:873:ex3:trans":"I want to study in a quiet place.","grammar:873:ex3:structure":"静かな〜で〜たいです","grammar:873:ex3:words:0:zh":"quiet","grammar:873:ex3:words:0:note":"しずか","grammar:873:ex3:words:0:pos":"na-adjective","grammar:873:ex3:words:1:zh":"(attributive form)","grammar:873:ex3:words:1:pos":"auxiliary verb","grammar:873:ex3:words:2:zh":"place","grammar:873:ex3:words:2:note":"ばしょ","grammar:873:ex3:words:2:pos":"noun","grammar:873:ex3:words:3:zh":"(place)","grammar:873:ex3:words:3:pos":"particle","grammar:873:ex3:words:4:zh":"want to study","grammar:873:ex3:words:4:note":"べんきょうしたい","grammar:873:ex3:words:4:pos":"verb","grammar:873:ex3:words:5:zh":"(polite form)","grammar:873:ex3:words:5:pos":"copula","grammar:873:ex3:points:0":"静かな場所: a quiet place (な + noun).","grammar:873:ex3:points:1":"〜たい: to want to ….","grammar:873:ex4:trans":"The park was quiet.","grammar:873:ex4:structure":"〜は静かでした","grammar:873:ex4:words:0:zh":"park","grammar:873:ex4:words:0:note":"こうえん","grammar:873:ex4:words:0:pos":"noun","grammar:873:ex4:words:1:zh":"(topic)","grammar:873:ex4:words:1:pos":"particle","grammar:873:ex4:words:2:zh":"quiet","grammar:873:ex4:words:2:note":"しずか","grammar:873:ex4:words:2:pos":"na-adjective","grammar:873:ex4:words:3:zh":"(past) was","grammar:873:ex4:words:3:pos":"copula","grammar:873:ex4:points:0":"静かでした: was quiet (past).","grammar:873:ex4:points:1":"公園: park.","grammar:873:ex5:trans":"I like quiet nights.","grammar:873:ex5:structure":"静かな〜が好きです","grammar:873:ex5:words:0:zh":"quiet","grammar:873:ex5:words:0:note":"しずか","grammar:873:ex5:words:0:pos":"na-adjective","grammar:873:ex5:words:1:zh":"(attributive form)","grammar:873:ex5:words:1:pos":"auxiliary verb","grammar:873:ex5:words:2:zh":"night","grammar:873:ex5:words:2:note":"よる","grammar:873:ex5:words:2:pos":"noun","grammar:873:ex5:words:3:zh":"(object)","grammar:873:ex5:words:3:pos":"particle","grammar:873:ex5:words:4:zh":"to like","grammar:873:ex5:words:4:note":"すき","grammar:873:ex5:words:4:pos":"na-adjective","grammar:873:ex5:words:5:zh":"(polite form)","grammar:873:ex5:words:5:pos":"copula","grammar:873:ex5:points:0":"静かな夜: a quiet night.","grammar:873:ex5:points:1":"〜が好き: to like …","exam:873:zh":"You can't hear sounds from outside or people's voices in this room, so it's very quiet.","exam:873:why":"「静か」 means quiet, which matches not hearing any sounds. 「にぎやか」 means lively, the opposite of the situation here."},"874":{"example:874:exzh":"He is suspected of being involved in that case.","example:874:exzh2":"If the suspicion is cleared, she is innocent.","example:874:exzh3":"The police are looking for a suspect.","example:874:exzh4":"There is little basis for that suspicion.","example:874:exzh5":"The moment the suspicion was cleared, he was released."},"875":{"example:875:exzh":"This house is old.","example:875:exzh2":"He likes old books.","example:875:exzh3":"You can see an old castle.","example:875:exzh4":"This road has been here since long ago.","example:875:exzh5":"An old legend is being passed down.","grammar:875:ex:trans":"This house is old.","grammar:875:ex:structure":"この＋noun＋は＋i-adjective＋です。","grammar:875:ex:explain":"「古い（ふるい）」 is an i-adjective meaning old. The pattern is 「この＋noun＋は＋i-adjective＋です」: the topic 「この家」 is marked with 「は」, and the predicate 「古い」 takes 「です」 directly to become the polite 「古いです」. This is the most basic polite form of an i-adjective; note that the i-adjective already ends in 「い」, so nothing changes when 「です」 is added.","grammar:875:ex:words:0:zh":"this","grammar:875:ex:words:0:pos":"pre-noun adjectival","grammar:875:ex:words:1:zh":"house","grammar:875:ex:words:1:note":"いえ","grammar:875:ex:words:1:pos":"noun","grammar:875:ex:words:2:zh":"(topic marker)","grammar:875:ex:words:2:pos":"particle","grammar:875:ex:words:3:zh":"old","grammar:875:ex:words:3:note":"ふるい","grammar:875:ex:words:3:pos":"adjective","grammar:875:ex:words:4:zh":"(polite form)","grammar:875:ex:words:4:pos":"copula","grammar:875:ex:points:0":"古い: old","grammar:875:ex:points:1":"i-adjective polite form: 古いです","grammar:875:ex2:trans":"He likes old books.","grammar:875:ex2:structure":"i-adjective＋noun＋が＋好きです。","grammar:875:ex2:words:0:zh":"he","grammar:875:ex2:words:0:note":"かれ","grammar:875:ex2:words:0:pos":"pronoun","grammar:875:ex2:words:1:zh":"(topic marker)","grammar:875:ex2:words:1:pos":"particle","grammar:875:ex2:words:2:zh":"old","grammar:875:ex2:words:2:note":"ふるい","grammar:875:ex2:words:2:pos":"adjective","grammar:875:ex2:words:3:zh":"book","grammar:875:ex2:words:3:note":"ほん","grammar:875:ex2:words:3:pos":"noun","grammar:875:ex2:words:4:zh":"(object marker)","grammar:875:ex2:words:4:pos":"particle","grammar:875:ex2:words:5:zh":"to like","grammar:875:ex2:words:5:note":"すき","grammar:875:ex2:words:5:pos":"na-adjective","grammar:875:ex2:words:6:zh":"(polite form)","grammar:875:ex2:words:6:pos":"copula","grammar:875:ex2:points:0":"古い本: old books","grammar:875:ex2:points:1":"〜が好き: to like…","grammar:875:ex3:trans":"You can see an old castle.","grammar:875:ex3:structure":"i-adjective＋noun＋が＋見えます。 The object of 「見える」 takes が.","grammar:875:ex3:words:0:zh":"old","grammar:875:ex3:words:0:note":"ふるい","grammar:875:ex3:words:0:pos":"adjective","grammar:875:ex3:words:1:zh":"castle","grammar:875:ex3:words:1:note":"しろ","grammar:875:ex3:words:1:pos":"noun","grammar:875:ex3:words:2:zh":"(nominative)","grammar:875:ex3:words:2:pos":"particle","grammar:875:ex3:words:3:zh":"can see (is visible)","grammar:875:ex3:words:3:note":"みえます","grammar:875:ex3:words:3:pos":"verb","grammar:875:ex3:points:0":"見える: to be visible (to come naturally into view)","grammar:875:ex3:points:1":"古い城: an old castle","grammar:875:ex4:trans":"This road has existed since long ago.","grammar:875:ex4:structure":"〜は＋〔古くから〕＋ある。 「古くから」 means since long ago (i-adjective continuative form＋から).","grammar:875:ex4:words:0:zh":"this","grammar:875:ex4:words:0:pos":"pre-noun adjectival","grammar:875:ex4:words:1:zh":"road","grammar:875:ex4:words:1:note":"みち","grammar:875:ex4:words:1:pos":"noun","grammar:875:ex4:words:2:zh":"(topic marker)","grammar:875:ex4:words:2:pos":"particle","grammar:875:ex4:words:3:zh":"old","grammar:875:ex4:words:3:note":"ふるく; continuative form","grammar:875:ex4:words:3:pos":"adjective","grammar:875:ex4:words:4:zh":"from","grammar:875:ex4:words:4:note":"starting point","grammar:875:ex4:words:4:pos":"particle","grammar:875:ex4:words:5:zh":"being","grammar:875:ex4:words:5:note":"dictionary form","grammar:875:ex4:words:5:pos":"verb","grammar:875:ex4:points:0":"古くから: since long ago (古く ＝ continuative form＋から)","grammar:875:ex4:points:1":"ある: to exist","grammar:875:ex5:trans":"An old legend is still being passed down.","grammar:875:ex5:structure":"i-adjective＋noun＋が＋verb passive ている。 「語り継がれる」 is the passive, meaning to be passed down.","grammar:875:ex5:words:0:zh":"old","grammar:875:ex5:words:0:note":"ふるい","grammar:875:ex5:words:0:pos":"adjective","grammar:875:ex5:words:1:zh":"legend","grammar:875:ex5:words:1:note":"でんせつ","grammar:875:ex5:words:1:pos":"noun","grammar:875:ex5:words:2:zh":"(nominative)","grammar:875:ex5:words:2:pos":"particle","grammar:875:ex5:words:3:zh":"is passed down","grammar:875:ex5:words:3:note":"かたりつがれています; passive＋ている","grammar:875:ex5:words:3:pos":"verb","grammar:875:ex5:points:0":"語り継がれる: to be handed down (the passive of 語り継ぐ)","grammar:875:ex5:points:1":"〜ている: an ongoing state","exam:875:zh":"This house is an old house built a hundred years ago, so it isn't a house that was just built.","exam:875:why":"「古い」 can describe a house that was built long ago. 「若い」 is mainly used to describe people or living things as young, and isn't used to say that a house is old."},"876":{"example:876:exzh":"He admitted his mistake.","example:876:exzh2":"It's hard to admit that fact.","example:876:exzh3":"Her talent is recognized.","example:876:exzh4":"Let's acknowledge each other's opinions.","example:876:exzh5":"It's important to recognize success."},"877":{"example:877:exzh":"I have a lot of friends.","example:877:exzh2":"This school has a lot of students.","example:877:exzh3":"This job often takes a lot of time.","example:877:exzh4":"This town has a lot of tourists.","example:877:exzh5":"A lot of people gathered.","grammar:877:ex:trans":"I have a lot of friends.","grammar:877:ex:structure":"noun＋が＋多いです。 「多い」 works as a predicate, and the subject takes が.","grammar:877:ex:explain":"The point is how the i-adjective 「多い（おおい）」 behaves as a predicate: the thing whose number is described takes 「が」, so 「友達が多い」 means there are many friends. Note that 「多い」 normally does not directly modify a noun — 「多い友達」 is unnatural — and is mostly used as a predicate. Add 「です」 for the polite 「多いです」. The whole sentence means I have many friends.","grammar:877:ex:words:0:zh":"friend","grammar:877:ex:words:0:note":"ともだち","grammar:877:ex:words:0:pos":"noun","grammar:877:ex:words:1:zh":"(nominative)","grammar:877:ex:words:1:pos":"particle","grammar:877:ex:words:2:zh":"many","grammar:877:ex:words:2:note":"おおい","grammar:877:ex:words:2:pos":"adjective","grammar:877:ex:words:3:zh":"(polite form)","grammar:877:ex:words:3:pos":"copula","grammar:877:ex:points:0":"多い: many (as a predicate)","grammar:877:ex:points:1":"友達が多い: to have many friends","grammar:877:ex2:trans":"This school has many students.","grammar:877:ex2:structure":"placeには＋noun＋が＋多いです。 「〜には〜が多い」 means there are many … at a place.","grammar:877:ex2:words:0:zh":"this","grammar:877:ex2:words:0:pos":"pre-noun adjectival","grammar:877:ex2:words:1:zh":"school","grammar:877:ex2:words:1:note":"がっこう","grammar:877:ex2:words:1:pos":"noun","grammar:877:ex2:words:2:zh":"(location of existence＋emphasis)","grammar:877:ex2:words:2:pos":"particle","grammar:877:ex2:words:3:zh":"student","grammar:877:ex2:words:3:note":"せいと","grammar:877:ex2:words:3:pos":"noun","grammar:877:ex2:words:4:zh":"(nominative)","grammar:877:ex2:words:4:pos":"particle","grammar:877:ex2:words:5:zh":"many","grammar:877:ex2:words:5:note":"おおい","grammar:877:ex2:words:5:pos":"adjective","grammar:877:ex2:words:6:zh":"(polite form)","grammar:877:ex2:words:6:pos":"copula","grammar:877:ex2:points:0":"〜には〜が多い: many … at a place","grammar:877:ex2:points:1":"には: に＋は (emphasizing the place)","grammar:877:ex3:trans":"This job often takes a lot of time.","grammar:877:ex3:structure":"〜は［時間がかかる］ことが多いです","grammar:877:ex3:explain":"「この仕事は」 raises this job as the topic. 「時間がかかる」 means to take time, and that whole clause modifies 「こと」, forming the situation of taking time. 「ことが多い」 says this situation happens often, hence the translation it often takes a lot of time. The two 「が」 belong to two different layers: 「時間がかかる」 and 「ことが多い」.","grammar:877:ex3:words:0:zh":"this (job)","grammar:877:ex3:words:0:pos":"pre-noun adjectival","grammar:877:ex3:words:1:zh":"work","grammar:877:ex3:words:1:note":"しごと","grammar:877:ex3:words:1:pos":"noun","grammar:877:ex3:words:2:zh":"(topic)","grammar:877:ex3:words:2:pos":"particle","grammar:877:ex3:words:3:zh":"time","grammar:877:ex3:words:3:note":"じかん","grammar:877:ex3:words:3:pos":"noun","grammar:877:ex3:words:4:zh":"(nominative)","grammar:877:ex3:words:4:pos":"particle","grammar:877:ex3:words:5:zh":"to take, to require","grammar:877:ex3:words:5:pos":"verb","grammar:877:ex3:words:6:zh":"case","grammar:877:ex3:words:6:pos":"noun","grammar:877:ex3:words:7:zh":"(nominative)","grammar:877:ex3:words:7:pos":"particle","grammar:877:ex3:words:8:zh":"many / frequent","grammar:877:ex3:words:8:note":"おおい","grammar:877:ex3:words:8:pos":"i-adjective","grammar:877:ex3:words:9:zh":"(polite tone)","grammar:877:ex3:words:9:pos":"auxiliary verb","grammar:877:ex3:points:0":"「時間がかかる」 is the usual collocation for taking time, and it uses 「が」.","grammar:877:ex3:points:1":"「verb plain form＋ことが多い」 means a certain situation happens often.","grammar:877:ex4:trans":"This town has a lot of tourists.","grammar:877:ex4:structure":"〜は＋noun＋が＋多いです。 A big topic with は, then a small subject with が, plus 多い.","grammar:877:ex4:words:0:zh":"this","grammar:877:ex4:words:0:pos":"pre-noun adjectival","grammar:877:ex4:words:1:zh":"town","grammar:877:ex4:words:1:note":"まち","grammar:877:ex4:words:1:pos":"noun","grammar:877:ex4:words:2:zh":"(topic marker)","grammar:877:ex4:words:2:pos":"particle","grammar:877:ex4:words:3:zh":"tourist","grammar:877:ex4:words:3:note":"かんこうきゃく","grammar:877:ex4:words:3:pos":"noun","grammar:877:ex4:words:4:zh":"(nominative)","grammar:877:ex4:words:4:pos":"particle","grammar:877:ex4:words:5:zh":"many","grammar:877:ex4:words:5:note":"おおい","grammar:877:ex4:words:5:pos":"adjective","grammar:877:ex4:words:6:zh":"(polite form)","grammar:877:ex4:words:6:pos":"copula","grammar:877:ex4:points:0":"〜は〜が多い: (a place) has many …","grammar:877:ex4:points:1":"観光客が多い: many tourists","grammar:877:ex5:trans":"A lot of people gathered.","grammar:877:ex5:structure":"〔many people〕＋が＋集まりました。 「多くの」 is the natural way to modify a noun (not 多い人).","grammar:877:ex5:words:0:zh":"many","grammar:877:ex5:words:0:note":"おおく","grammar:877:ex5:words:0:pos":"noun","grammar:877:ex5:words:1:zh":"'s","grammar:877:ex5:words:1:pos":"particle","grammar:877:ex5:words:2:zh":"person","grammar:877:ex5:words:2:note":"ひと","grammar:877:ex5:words:2:pos":"noun","grammar:877:ex5:words:3:zh":"(nominative)","grammar:877:ex5:words:3:pos":"particle","grammar:877:ex5:words:4:zh":"gathered","grammar:877:ex5:words:4:note":"あつまりました","grammar:877:ex5:words:4:pos":"verb","grammar:877:ex5:points:0":"多くの＋noun: many … (use this form to modify a noun)","grammar:877:ex5:points:1":"集まる: to gather","exam:877:zh":"There were ten customers yesterday and a hundred today, so there are more customers today than yesterday.","exam:877:why":"「多い」 means a large number, and a hundred people is more than ten. 「少ない」 means a small number, which contradicts the numbers given.","exam_official:877:zh":"This shop has a lot of customers on Saturdays.","exam_official:877:why":"「多い」 is read 「おおい」. 「おい」 is missing one 「お」, so the length is different."},"878":{"example:878:exzh":"What do you think about that?","example:878:exzh2":"What do you think of him?","example:878:exzh3":"I think dreams are important.","example:878:exzh4":"I plan to do as many fun things as I can.","example:878:exzh5":"I think the past can't be changed.","grammar:878:ex:trans":"What do you think about that?","grammar:878:ex:structure":"〜をどう思いますか","grammar:878:ex:explain":"「あのこと」 means that matter, usually something both sides know about and can identify. 「を」 marks what is being evaluated or thought about. 「どう」 asks how, and 「思いますか」 politely asks for the other person's opinion. The sentence does not say 「あなた」, but in a direct question it is naturally understood as asking the listener.","grammar:878:ex:words:0:zh":"that","grammar:878:ex:words:0:pos":"pre-noun adjectival","grammar:878:ex:words:1:zh":"thing / matter","grammar:878:ex:words:1:pos":"noun","grammar:878:ex:words:2:zh":"(the thing being thought about or evaluated)","grammar:878:ex:words:2:pos":"particle","grammar:878:ex:words:3:zh":"how","grammar:878:ex:words:3:pos":"adverb","grammar:878:ex:words:4:zh":"think / consider","grammar:878:ex:words:4:note":"おもい","grammar:878:ex:words:4:pos":"verb","grammar:878:ex:words:5:zh":"(polite tone)","grammar:878:ex:words:5:pos":"auxiliary verb","grammar:878:ex:words:6:zh":"(question)","grammar:878:ex:words:6:pos":"particle","grammar:878:ex:points:0":"「〜をどう思いますか」 is used to ask for someone's opinion about a person or a thing.","grammar:878:ex:points:1":"「あのこと」 can refer to a matter both speaker and listener know about.","grammar:878:ex2:trans":"What do you think of him?","grammar:878:ex2:structure":"人のことをどう思いますか","grammar:878:ex2:explain":"Literally 「彼のこと」 is the things about him, but when asking about someone's thoughts or feelings it usually means him as a person, so it does not have to be translated as some particular matter concerning him. 「を」 marks what is being evaluated, and 「どう思いますか」 asks how the listener sees him. This sentence can ask for a general impression, or depending on the situation for a romantic opinion; the sentence alone does not settle it.","grammar:878:ex2:words:0:zh":"he","grammar:878:ex2:words:0:note":"かれ","grammar:878:ex2:words:0:pos":"pronoun","grammar:878:ex2:words:1:zh":"(links a person with matters concerning them)","grammar:878:ex2:words:1:pos":"particle","grammar:878:ex2:words:2:zh":"things about him / him as a person","grammar:878:ex2:words:2:pos":"noun","grammar:878:ex2:words:3:zh":"(the thing being thought about or evaluated)","grammar:878:ex2:words:3:pos":"particle","grammar:878:ex2:words:4:zh":"how","grammar:878:ex2:words:4:pos":"adverb","grammar:878:ex2:words:5:zh":"think / consider","grammar:878:ex2:words:5:note":"おもい","grammar:878:ex2:words:5:pos":"verb","grammar:878:ex2:words:6:zh":"(polite tone)","grammar:878:ex2:words:6:pos":"auxiliary verb","grammar:878:ex2:words:7:zh":"(question)","grammar:878:ex2:words:7:pos":"particle","grammar:878:ex2:points:0":"「人のこと」 is often used when talking about thoughts or feelings toward someone, and it is usually translated simply as that person.","grammar:878:ex2:points:1":"「〜をどう思いますか」 asks for an evaluation or impression of someone or something.","grammar:878:ex3:trans":"I think dreams are important.","grammar:878:ex3:structure":"〜は〜だと思います","grammar:878:ex3:explain":"「夢は」 makes dreams the topic. 「大切」 is a na-adjective, and as a plain-form predicate it becomes 「大切だ」. 「と」 quotes the judgment 「夢は大切だ」, and 「思います」 adds I think. The thinker 「私は」 is omitted, so this normally expresses the speaker's own view.","grammar:878:ex3:words:0:zh":"dream","grammar:878:ex3:words:0:note":"ゆめ","grammar:878:ex3:words:0:pos":"noun","grammar:878:ex3:words:1:zh":"(topic)","grammar:878:ex3:words:1:pos":"particle","grammar:878:ex3:words:2:zh":"important","grammar:878:ex3:words:2:note":"たいせつ","grammar:878:ex3:words:2:pos":"na-adjective","grammar:878:ex3:words:3:zh":"(plain form, affirmative)","grammar:878:ex3:words:3:pos":"auxiliary verb","grammar:878:ex3:words:4:zh":"(quotes the content of a thought)","grammar:878:ex3:words:4:pos":"particle","grammar:878:ex3:words:5:zh":"thinks","grammar:878:ex3:words:5:note":"おもい","grammar:878:ex3:words:5:pos":"verb","grammar:878:ex3:words:6:zh":"(polite ending)","grammar:878:ex3:words:6:pos":"auxiliary verb","grammar:878:ex3:points:0":"「plain form＋と思います」 expresses your own thoughts or judgment.","grammar:878:ex3:points:1":"When a noun or na-adjective in the affirmative present takes 「と思います」, keep 「だ」.","grammar:878:ex4:trans":"I intend to do as many fun things as I can.","grammar:878:ex4:structure":"できるだけ〜をしようと思います","grammar:878:ex4:explain":"「できるだけ」 modifies the action that follows and means as much as possible. 「楽しい」 directly modifies the noun 「こと」 to form fun things, and 「を」 marks what is done. 「しよう」 is the volitional form of 「する」, and with 「と思います」 it expresses the speaker's own plan; here 「しよう」 is not an invitation for the listener to join in.","grammar:878:ex4:words:0:zh":"as much as possible","grammar:878:ex4:words:0:pos":"adverb","grammar:878:ex4:words:1:zh":"fun / enjoyable","grammar:878:ex4:words:1:note":"たのしい","grammar:878:ex4:words:1:pos":"i-adjective","grammar:878:ex4:words:2:zh":"thing / matter","grammar:878:ex4:words:2:pos":"noun","grammar:878:ex4:words:3:zh":"(object)","grammar:878:ex4:words:3:pos":"particle","grammar:878:ex4:words:4:zh":"do","grammar:878:ex4:words:4:pos":"verb","grammar:878:ex4:words:5:zh":"(volitional)","grammar:878:ex4:words:5:pos":"auxiliary verb","grammar:878:ex4:words:6:zh":"(quotes the content of the plan)","grammar:878:ex4:words:6:pos":"particle","grammar:878:ex4:words:7:zh":"think / intend","grammar:878:ex4:words:7:note":"おもい","grammar:878:ex4:words:7:pos":"verb","grammar:878:ex4:words:8:zh":"(polite ending)","grammar:878:ex4:words:8:pos":"auxiliary verb","grammar:878:ex4:points:0":"「verb volitional form＋と思います」 means I intend to do…","grammar:878:ex4:points:1":"The volitional form of 「する」 is 「しよう」.","grammar:878:ex4:points:2":"「できるだけ」 means doing as much as your ability or circumstances allow.","grammar:878:ex5:trans":"I think the past cannot be changed.","grammar:878:ex5:structure":"〜は〜られないと思います","grammar:878:ex5:explain":"「過去は」 makes the past the topic. 「変える」 is a transitive verb meaning to change something; with the potential 「られる」 and the negative 「ない」 it becomes cannot be changed. 「と」 quotes the whole judgment, and 「思います」 expresses the speaker's own view.","grammar:878:ex5:words:0:zh":"the past","grammar:878:ex5:words:0:note":"かこ","grammar:878:ex5:words:0:pos":"noun","grammar:878:ex5:words:1:zh":"(topic)","grammar:878:ex5:words:1:pos":"particle","grammar:878:ex5:words:2:zh":"change","grammar:878:ex5:words:2:note":"かえ","grammar:878:ex5:words:2:pos":"verb","grammar:878:ex5:words:3:zh":"(potential: able to)","grammar:878:ex5:words:3:pos":"auxiliary verb","grammar:878:ex5:words:4:zh":"(negative)","grammar:878:ex5:words:4:pos":"auxiliary verb","grammar:878:ex5:words:5:zh":"(quotes the content of a thought)","grammar:878:ex5:words:5:pos":"particle","grammar:878:ex5:words:6:zh":"thinks","grammar:878:ex5:words:6:note":"おもい","grammar:878:ex5:words:6:pos":"verb","grammar:878:ex5:words:7:zh":"(polite ending)","grammar:878:ex5:words:7:pos":"auxiliary verb","grammar:878:ex5:points:0":"The potential form of 「変える」 is 「変えられる」, and its negative is 「変えられない」.","grammar:878:ex5:points:1":"「られる」 can also mark the passive, but in this sentence the meaning is the negative potential, cannot be changed.","exam:878:zh":"I haven't decided yet, but I think I'll go tomorrow.","exam:878:why":"「行こうと思う」 expresses an intention to go, which fits the situation of not having decided yet. 「聞く」 means to listen or to ask, so it can't express your own plans here."},"879":{"example:879:exzh":"I stayed at a hotel.","example:879:exzh2":"I'm looking for a good hotel.","example:879:exzh3":"There's a restaurant near the hotel.","example:879:exzh4":"This hotel is cheap.","example:879:exzh5":"We booked a hotel.","grammar:879:ex:trans":"I stayed at a hotel.","grammar:879:ex:structure":"〜に泊まりました","grammar:879:ex:explain":"The core is 「〜に泊まる」, meaning to stay or spend the night; the place you stay takes 「に」. The verb 「泊まる（とまる）」 specifically means to spend the night or stay over — unlike the general 「住む」 (to live), 「泊まる」 is for a short stay. The past polite form 「泊まりました」 shows the action is completed. The whole sentence means 'I stayed a night at a hotel'.","grammar:879:ex:words:0:zh":"hotel","grammar:879:ex:words:0:note":"loanword","grammar:879:ex:words:0:pos":"noun","grammar:879:ex:words:1:zh":"(location of existence)","grammar:879:ex:words:1:pos":"particle","grammar:879:ex:words:2:zh":"stayed","grammar:879:ex:words:2:note":"とまりました","grammar:879:ex:words:2:pos":"verb","grammar:879:ex:points:0":"❗〜に泊まる: to stay at… (「に」 marks where you stay).","grammar:879:ex:points:1":"泊まる: to spend the night; to stay.","grammar:879:ex2:trans":"I'm looking for a good hotel.","grammar:879:ex2:structure":"〜を探しています","grammar:879:ex2:words:0:zh":"good","grammar:879:ex2:words:0:pos":"adjective","grammar:879:ex2:words:1:zh":"hotel","grammar:879:ex2:words:1:note":"loanword","grammar:879:ex2:words:1:pos":"noun","grammar:879:ex2:words:2:zh":"(object marker)","grammar:879:ex2:words:2:pos":"particle","grammar:879:ex2:words:3:zh":"are looking for","grammar:879:ex2:words:3:note":"さがしています","grammar:879:ex2:words:3:pos":"verb","grammar:879:ex2:points:0":"いいホテル: a good hotel.","grammar:879:ex2:points:1":"〜ている: is looking for","grammar:879:ex3:trans":"There is a restaurant near the hotel.","grammar:879:ex3:structure":"〜の近くに〜があります","grammar:879:ex3:words:0:zh":"hotel","grammar:879:ex3:words:0:note":"loanword","grammar:879:ex3:words:0:pos":"noun","grammar:879:ex3:words:1:zh":"'s","grammar:879:ex3:words:1:pos":"particle","grammar:879:ex3:words:2:zh":"nearby","grammar:879:ex3:words:2:note":"ちかく","grammar:879:ex3:words:2:pos":"noun","grammar:879:ex3:words:3:zh":"(location of existence)","grammar:879:ex3:words:3:pos":"particle","grammar:879:ex3:words:4:zh":"restaurant","grammar:879:ex3:words:4:note":"loanword","grammar:879:ex3:words:4:pos":"noun","grammar:879:ex3:words:5:zh":"(nominative)","grammar:879:ex3:words:5:pos":"particle","grammar:879:ex3:words:6:zh":"there is / are","grammar:879:ex3:words:6:pos":"verb","grammar:879:ex3:points:0":"ホテルの近く: near the hotel.","grammar:879:ex3:points:1":"〜にあります: be at/in … (inanimate things).","grammar:879:ex4:trans":"This hotel is cheap.","grammar:879:ex4:structure":"〜は安いです","grammar:879:ex4:words:0:zh":"this","grammar:879:ex4:words:0:pos":"pre-noun adjectival","grammar:879:ex4:words:1:zh":"hotel","grammar:879:ex4:words:1:note":"loanword","grammar:879:ex4:words:1:pos":"noun","grammar:879:ex4:words:2:zh":"(topic)","grammar:879:ex4:words:2:pos":"particle","grammar:879:ex4:words:3:zh":"cheap","grammar:879:ex4:words:3:note":"やすい","grammar:879:ex4:words:3:pos":"adjective","grammar:879:ex4:words:4:zh":"(polite form)","grammar:879:ex4:words:4:pos":"copula","grammar:879:ex4:points:0":"安い: cheap.","grammar:879:ex4:points:1":"このホテル: this hotel.","grammar:879:ex5:trans":"We booked a hotel.","grammar:879:ex5:structure":"〜を予約しました","grammar:879:ex5:words:0:zh":"we","grammar:879:ex5:words:0:note":"わたしたち","grammar:879:ex5:words:0:pos":"pronoun","grammar:879:ex5:words:1:zh":"(topic)","grammar:879:ex5:words:1:pos":"particle","grammar:879:ex5:words:2:zh":"hotel","grammar:879:ex5:words:2:note":"loanword","grammar:879:ex5:words:2:pos":"noun","grammar:879:ex5:words:3:zh":"(object marker)","grammar:879:ex5:words:3:pos":"particle","grammar:879:ex5:words:4:zh":"booked","grammar:879:ex5:words:4:note":"よやくしました","grammar:879:ex5:words:4:pos":"verb","grammar:879:ex5:points:0":"ホテルを予約する: to book a hotel.","grammar:879:ex5:points:1":"予約する: to book; to reserve.","exam:879:zh":"On trips, I stay at a hotel near the station for the night.","exam:879:why":"「ホテル」 is a hotel that provides lodging and pairs naturally with 「泊まります」. A 「銀行」 handles financial business and isn't a place to stay on a trip."},"880":{"example:880:exzh":"Treatment is necessary.","example:880:exzh2":"He is receiving treatment.","example:880:exzh3":"Please get treatment as soon as possible.","example:880:exzh4":"The cost of treatment is high.","example:880:exzh5":"The effects of the treatment are already showing."},"881":{"example:881:exzh":"I go to university.","example:881:exzh2":"She graduated from university.","example:881:exzh3":"I study at university.","example:881:exzh4":"I met up with a friend from university.","example:881:exzh5":"The university campus is large.","grammar:881:ex:trans":"I attend university.","grammar:881:ex:structure":"〜に通っています","grammar:881:ex:explain":"The core is 「〜に通う」, meaning to go regularly to a place, especially for school or work; the destination takes 「に」. The verb 「通う（かよう）」 stresses repeated, regular coming and going, unlike the single trip of 「行く」. The sentence-final 「通っています」 (「〜ている」) shows an ongoing state, so 「大学に通っている」 means being enrolled at a university and going there regularly. The whole sentence means 'I attend university'.","grammar:881:ex:words:0:zh":"I","grammar:881:ex:words:0:note":"わたし","grammar:881:ex:words:0:pos":"pronoun","grammar:881:ex:words:1:zh":"(topic)","grammar:881:ex:words:1:pos":"particle","grammar:881:ex:words:2:zh":"university","grammar:881:ex:words:2:note":"だいがく","grammar:881:ex:words:2:pos":"noun","grammar:881:ex:words:3:zh":"(place you go to regularly)","grammar:881:ex:words:3:pos":"particle","grammar:881:ex:words:4:zh":"attend","grammar:881:ex:words:4:note":"かよっています","grammar:881:ex:words:4:pos":"verb","grammar:881:ex:points:0":"❗〜に通う: to go regularly to… (to attend school); use に.","grammar:881:ex:points:1":"大学に通う: to attend university.","grammar:881:ex2:trans":"She has graduated from university.","grammar:881:ex2:structure":"〜を卒業しました","grammar:881:ex2:words:0:zh":"she","grammar:881:ex2:words:0:note":"かのじょ","grammar:881:ex2:words:0:pos":"pronoun","grammar:881:ex2:words:1:zh":"(topic)","grammar:881:ex2:words:1:pos":"particle","grammar:881:ex2:words:2:zh":"university","grammar:881:ex2:words:2:note":"だいがく","grammar:881:ex2:words:2:pos":"noun","grammar:881:ex2:words:3:zh":"(object marker)","grammar:881:ex2:words:3:pos":"particle","grammar:881:ex2:words:4:zh":"graduated","grammar:881:ex2:words:4:note":"そつぎょうしました","grammar:881:ex2:words:4:pos":"verb","grammar:881:ex2:points:0":"❗大学を卒業する: to graduate from university (use を, for leaving).","grammar:881:ex2:points:1":"卒業する: to graduate.","grammar:881:ex3:trans":"I study at university.","grammar:881:ex3:structure":"〜で勉強しています","grammar:881:ex3:words:0:zh":"university","grammar:881:ex3:words:0:note":"だいがく","grammar:881:ex3:words:0:pos":"noun","grammar:881:ex3:words:1:zh":"(place)","grammar:881:ex3:words:1:pos":"particle","grammar:881:ex3:words:2:zh":"has been studying","grammar:881:ex3:words:2:note":"べんきょうしています","grammar:881:ex3:words:2:pos":"verb","grammar:881:ex3:points:0":"❓大学で: at university (「で」 marks the place).","grammar:881:ex3:points:1":"〜ている: ongoing / habitual","grammar:881:ex4:trans":"I met a university friend.","grammar:881:ex4:structure":"〜と会いました","grammar:881:ex4:words:0:zh":"university","grammar:881:ex4:words:0:note":"だいがく","grammar:881:ex4:words:0:pos":"noun","grammar:881:ex4:words:1:zh":"'s","grammar:881:ex4:words:1:pos":"particle","grammar:881:ex4:words:2:zh":"friend","grammar:881:ex4:words:2:note":"ともだち","grammar:881:ex4:words:2:pos":"noun","grammar:881:ex4:words:3:zh":"(object)","grammar:881:ex4:words:3:pos":"particle","grammar:881:ex4:words:4:zh":"met","grammar:881:ex4:words:4:note":"あいました","grammar:881:ex4:words:4:pos":"verb","grammar:881:ex4:points:0":"大学の友達: a university friend.","grammar:881:ex4:points:1":"〜と会う: to meet with…","grammar:881:ex5:trans":"The university campus is large.","grammar:881:ex5:structure":"〜は広いです","grammar:881:ex5:words:0:zh":"university","grammar:881:ex5:words:0:note":"だいがく","grammar:881:ex5:words:0:pos":"noun","grammar:881:ex5:words:1:zh":"'s","grammar:881:ex5:words:1:pos":"particle","grammar:881:ex5:words:2:zh":"campus","grammar:881:ex5:words:2:note":"loanword","grammar:881:ex5:words:2:pos":"noun","grammar:881:ex5:words:3:zh":"(topic)","grammar:881:ex5:words:3:pos":"particle","grammar:881:ex5:words:4:zh":"wide, vast","grammar:881:ex5:words:4:note":"ひろい","grammar:881:ex5:words:4:pos":"adjective","grammar:881:ex5:words:5:zh":"(polite form)","grammar:881:ex5:words:5:pos":"copula","grammar:881:ex5:points:0":"キャンパス: campus.","grammar:881:ex5:points:1":"広い: wide, vast.","exam:881:zh":"After graduating from high school, my older sister studied at university for four years.","exam:881:why":"After high school you usually go on to 「大学」, and a four-year course of study also fits. 「高校」 is the stage she has already graduated from."},"882":{"example:882:exzh":"Let's get off at the next station.","example:882:exzh2":"Please get off the bus.","example:882:exzh3":"Please be careful when you get off.","example:882:exzh4":"He got out of the taxi.","example:882:exzh5":"Please get off this bus.","grammar:882:ex:trans":"Let's get off at the next station.","grammar:882:ex:structure":"〜で降りましょう","grammar:882:ex:explain":"The key point is the verb 「降りる（おりる）」, meaning to get off (a vehicle, stairs, etc.); the place where you get off takes 「で」, because getting off is an action done at that spot, so 「次の駅で降りる」 means get off at the next station. 「〜ましょう」 is the polite volitional, suggesting let's … together. 「次の駅」 is modified with 「の」. The whole sentence invites the other person to get off at the next station together.","grammar:882:ex:words:0:zh":"next","grammar:882:ex:words:0:note":"つぎ","grammar:882:ex:words:0:pos":"noun","grammar:882:ex:words:1:zh":"'s","grammar:882:ex:words:1:pos":"particle","grammar:882:ex:words:2:zh":"station","grammar:882:ex:words:2:note":"えき","grammar:882:ex:words:2:pos":"noun","grammar:882:ex:words:3:zh":"(place)","grammar:882:ex:words:3:pos":"particle","grammar:882:ex:words:4:zh":"let's get off","grammar:882:ex:words:4:note":"おりましょう","grammar:882:ex:words:4:pos":"verb","grammar:882:ex:points:0":"❗降りる（おりる）: to get off (a vehicle, stairs); 〜で降りる = get off at … (で for place).","grammar:882:ex:points:1":"次の駅: the next station.","grammar:882:ex2:trans":"Please get off the bus.","grammar:882:ex2:structure":"〜を降りてください","grammar:882:ex2:words:0:zh":"bus","grammar:882:ex2:words:0:note":"loanword","grammar:882:ex2:words:0:pos":"noun","grammar:882:ex2:words:1:zh":"(the point of departure)","grammar:882:ex2:words:1:pos":"particle","grammar:882:ex2:words:2:zh":"down","grammar:882:ex2:words:2:note":"おりて","grammar:882:ex2:words:2:pos":"verb","grammar:882:ex2:words:3:zh":"please","grammar:882:ex2:words:3:pos":"auxiliary verb","grammar:882:ex2:points:0":"❗〜を降りる: to get down from … (バスを降りる = get off the bus; を marks the point you leave).","grammar:882:ex2:points:1":"降りる → 降りて + ください.","grammar:882:ex3:trans":"Please be careful when getting off.","grammar:882:ex3:structure":"〜ときは注意してください","grammar:882:ex3:words:0:zh":"Get off","grammar:882:ex3:words:0:note":"おりる","grammar:882:ex3:words:0:pos":"verb","grammar:882:ex3:words:1:zh":"time","grammar:882:ex3:words:1:pos":"noun","grammar:882:ex3:words:2:zh":"(topic)","grammar:882:ex3:words:2:pos":"particle","grammar:882:ex3:words:3:zh":"be careful of","grammar:882:ex3:words:3:note":"ちゅういして","grammar:882:ex3:words:3:pos":"verb","grammar:882:ex3:words:4:zh":"please","grammar:882:ex3:words:4:pos":"auxiliary verb","grammar:882:ex3:points:0":"❗〜ときは: when …","grammar:882:ex3:points:1":"注意する: to be careful.","grammar:882:ex4:trans":"He got out of the taxi.","grammar:882:ex4:structure":"〜を降りました","grammar:882:ex4:words:0:zh":"he","grammar:882:ex4:words:0:note":"かれ","grammar:882:ex4:words:0:pos":"pronoun","grammar:882:ex4:words:1:zh":"(topic)","grammar:882:ex4:words:1:pos":"particle","grammar:882:ex4:words:2:zh":"taxi","grammar:882:ex4:words:2:note":"loanword","grammar:882:ex4:words:2:pos":"noun","grammar:882:ex4:words:3:zh":"(the point of departure)","grammar:882:ex4:words:3:pos":"particle","grammar:882:ex4:words:4:zh":"fell","grammar:882:ex4:words:4:note":"おりました","grammar:882:ex4:words:4:pos":"verb","grammar:882:ex4:points:0":"タクシーを降りる: get out of a taxi.","grammar:882:ex4:points:1":"降りる → 降りました.","grammar:882:ex5:trans":"Please get off this bus.","grammar:882:ex5:structure":"〜を降りてください","grammar:882:ex5:explain":"「このバス」 means this bus. Although 「降りる」 is an intransitive verb, it can still take 「を」 to mark the vehicle you are leaving; this 「を」 is not the ordinary object marker of a transitive verb. 「降りてください」 is the te-form plus 「ください」, a way to ask someone to get off.","grammar:882:ex5:words:0:zh":"this (vehicle)","grammar:882:ex5:words:0:pos":"pre-noun adjectival","grammar:882:ex5:words:1:zh":"bus","grammar:882:ex5:words:1:pos":"noun","grammar:882:ex5:words:2:zh":"(the place or vehicle being left)","grammar:882:ex5:words:2:pos":"particle","grammar:882:ex5:words:3:zh":"Get off","grammar:882:ex5:words:3:note":"おり","grammar:882:ex5:words:3:pos":"verb","grammar:882:ex5:words:4:zh":"(links to a request)","grammar:882:ex5:words:4:pos":"particle","grammar:882:ex5:words:5:zh":"please","grammar:882:ex5:words:5:pos":"verb","grammar:882:ex5:points:0":"「means of transport + を降りる」 means to get off that vehicle, with 「を」 marking what you are leaving.","grammar:882:ex5:points:1":"「降りる」 is an ichidan (ru-) verb, and its te-form is 「降りて」.","grammar:882:ex5:points:2":"「te-form verb + ください」 means please do something."},"883":{"example:883:exzh":"I'll send an email.","example:883:exzh2":"Did you check the email?","example:883:exzh3":"I got an email from a friend.","example:883:exzh4":"This email is important.","example:883:exzh5":"Please check the email quickly.","grammar:883:ex:trans":"I'll send an email.","grammar:883:ex:structure":"〜を送ります","grammar:883:ex:explain":"「メール」 is a loanword meaning email. The pattern is the basic 「〜を送ります」: the object 「メール」 takes 「を」, and the verb 「送る（おくる）」 means to send; the polite 「送ります」 expresses intent or a future action. The whole sentence means 'I'll send an email' — an everyday phrase for communication.","grammar:883:ex:words:0:zh":"email","grammar:883:ex:words:0:note":"loanword","grammar:883:ex:words:0:pos":"noun","grammar:883:ex:words:1:zh":"(object marker)","grammar:883:ex:words:1:pos":"particle","grammar:883:ex:words:2:zh":"send","grammar:883:ex:words:2:note":"おくります","grammar:883:ex:words:2:pos":"verb","grammar:883:ex:points:0":"メールを送る: to send an email.","grammar:883:ex:points:1":"送る→送ります。","grammar:883:ex2:trans":"Did you check the email?","grammar:883:ex2:structure":"〜を確認しましたか","grammar:883:ex2:words:0:zh":"email","grammar:883:ex2:words:0:note":"loanword","grammar:883:ex2:words:0:pos":"noun","grammar:883:ex2:words:1:zh":"(object marker)","grammar:883:ex2:words:1:pos":"particle","grammar:883:ex2:words:2:zh":"confirmed","grammar:883:ex2:words:2:note":"かくにんしました","grammar:883:ex2:words:2:pos":"verb","grammar:883:ex2:words:3:zh":"(question)","grammar:883:ex2:words:3:pos":"particle","grammar:883:ex2:points:0":"メールを確認する: to check an email.","grammar:883:ex2:points:1":"〜ましたか: did…?","grammar:883:ex3:trans":"An email came from a friend.","grammar:883:ex3:structure":"〜から〜が来ました","grammar:883:ex3:words:0:zh":"friend","grammar:883:ex3:words:0:note":"ともだち","grammar:883:ex3:words:0:pos":"noun","grammar:883:ex3:words:1:zh":"from","grammar:883:ex3:words:1:pos":"particle","grammar:883:ex3:words:2:zh":"email","grammar:883:ex3:words:2:note":"loanword","grammar:883:ex3:words:2:pos":"noun","grammar:883:ex3:words:3:zh":"(nominative)","grammar:883:ex3:words:3:pos":"particle","grammar:883:ex3:words:4:zh":"came","grammar:883:ex3:words:4:note":"きました","grammar:883:ex3:words:4:pos":"verb","grammar:883:ex3:points:0":"❗〜からメールが来る: an email comes from… (「から」 marks the source).","grammar:883:ex3:points:1":"来る → 来ました.","grammar:883:ex4:trans":"This email is important.","grammar:883:ex4:structure":"〜は重要です","grammar:883:ex4:words:0:zh":"this","grammar:883:ex4:words:0:pos":"pre-noun adjectival","grammar:883:ex4:words:1:zh":"email","grammar:883:ex4:words:1:note":"loanword","grammar:883:ex4:words:1:pos":"noun","grammar:883:ex4:words:2:zh":"(topic)","grammar:883:ex4:words:2:pos":"particle","grammar:883:ex4:words:3:zh":"important","grammar:883:ex4:words:3:note":"じゅうよう","grammar:883:ex4:words:3:pos":"na-adjective","grammar:883:ex4:words:4:zh":"(polite form)","grammar:883:ex4:words:4:pos":"copula","grammar:883:ex4:points:0":"このメール: this email.","grammar:883:ex4:points:1":"重要です: is important.","grammar:883:ex5:trans":"Please check the email quickly.","grammar:883:ex5:structure":"急いで〜てください","grammar:883:ex5:words:0:zh":"quickly","grammar:883:ex5:words:0:note":"いそいで","grammar:883:ex5:words:0:pos":"verb","grammar:883:ex5:words:1:zh":"email","grammar:883:ex5:words:1:note":"loanword","grammar:883:ex5:words:1:pos":"noun","grammar:883:ex5:words:2:zh":"(object marker)","grammar:883:ex5:words:2:pos":"particle","grammar:883:ex5:words:3:zh":"check","grammar:883:ex5:words:3:pos":"verb","grammar:883:ex5:words:4:zh":"please","grammar:883:ex5:words:4:pos":"auxiliary verb","grammar:883:ex5:points:0":"❗急いで: quickly; in a hurry (the te-form of 急ぐ used as an adverb).","grammar:883:ex5:points:1":"チェックする: to check."},"884":{"example:884:exzh":"The yearly income increased.","example:884:exzh2":"He goes on a trip once a year.","example:884:exzh3":"Let's set some goals for the year.","example:884:exzh4":"There are a lot of annual events.","example:884:exzh5":"She works 365 days a year."},"885":{"example:885:exzh":"My memory came back.","example:885:exzh2":"His memory is fuzzy.","example:885:exzh3":"This memory is important.","example:885:exzh4":"Let's keep going, trusting our memory.","example:885:exzh5":"I recall memories of the past."},"886":{"example:886:exzh":"May I use this card?","example:886:exzh2":"I have a credit card.","example:886:exzh3":"This card is valid.","example:886:exzh4":"I got a membership card.","example:886:exzh5":"I paid with a card.","grammar:886:ex:trans":"May I use this card?","grammar:886:ex:structure":"〜てもいいですか","grammar:886:ex:explain":"The core is the permission pattern 「〜てもいいですか」, built from a verb's te-form plus 「もいいですか」; it politely asks the other person's permission — may I…? The te-form of 「使う」 is 「使って」, so adding it gives may I use. 「カード」 takes 「を」 to mark the object. The whole sentence politely asks whether I can use this card, and it is the standard everyday way to ask for permission.","grammar:886:ex:words:0:zh":"this","grammar:886:ex:words:0:pos":"pre-noun adjectival","grammar:886:ex:words:1:zh":"card","grammar:886:ex:words:1:note":"loanword","grammar:886:ex:words:1:pos":"noun","grammar:886:ex:words:2:zh":"(object marker)","grammar:886:ex:words:2:pos":"particle","grammar:886:ex:words:3:zh":"use","grammar:886:ex:words:3:note":"つかって","grammar:886:ex:words:3:pos":"verb","grammar:886:ex:words:4:zh":"(also)","grammar:886:ex:words:4:pos":"particle","grammar:886:ex:words:5:zh":"good","grammar:886:ex:words:5:pos":"adjective","grammar:886:ex:words:6:zh":"is","grammar:886:ex:words:6:pos":"copula","grammar:886:ex:words:7:zh":"(question)","grammar:886:ex:words:7:pos":"particle","grammar:886:ex:points:0":"❗〜てもいいですか: may I …? (permission).","grammar:886:ex:points:1":"カードを使う: to use a card.","grammar:886:ex2:trans":"I have a credit card.","grammar:886:ex2:structure":"〜を持っています (has 〜)","grammar:886:ex2:words:0:zh":"credit card","grammar:886:ex2:words:0:note":"loanword","grammar:886:ex2:words:0:pos":"noun","grammar:886:ex2:words:1:zh":"(object marker)","grammar:886:ex2:words:1:pos":"particle","grammar:886:ex2:words:2:zh":"own, have","grammar:886:ex2:words:2:note":"もっています","grammar:886:ex2:words:2:pos":"verb","grammar:886:ex2:points:0":"クレジットカード: credit card.","grammar:886:ex2:points:1":"〜を持っている: to have….","grammar:886:ex3:trans":"This card is valid.","grammar:886:ex3:structure":"〜は有効です","grammar:886:ex3:words:0:zh":"this","grammar:886:ex3:words:0:pos":"pre-noun adjectival","grammar:886:ex3:words:1:zh":"card","grammar:886:ex3:words:1:note":"loanword","grammar:886:ex3:words:1:pos":"noun","grammar:886:ex3:words:2:zh":"(topic)","grammar:886:ex3:words:2:pos":"particle","grammar:886:ex3:words:3:zh":"valid","grammar:886:ex3:words:3:note":"ゆうこう","grammar:886:ex3:words:3:pos":"na-adjective","grammar:886:ex3:words:4:zh":"(polite form)","grammar:886:ex3:words:4:pos":"copula","grammar:886:ex3:points:0":"有効: valid.","grammar:886:ex3:points:1":"このカード: this card.","grammar:886:ex4:trans":"I got a membership card.","grammar:886:ex4:structure":"〜を作りました","grammar:886:ex4:words:0:zh":"membership card","grammar:886:ex4:words:0:note":"かいいんカード","grammar:886:ex4:words:0:pos":"noun","grammar:886:ex4:words:1:zh":"(object marker)","grammar:886:ex4:words:1:pos":"particle","grammar:886:ex4:words:2:zh":"got (one made)","grammar:886:ex4:words:2:note":"つくりました","grammar:886:ex4:words:2:pos":"verb","grammar:886:ex4:points:0":"❗カードを作る: to get a card made (using 作る).","grammar:886:ex4:points:1":"会員カード: membership card.","grammar:886:ex5:trans":"I paid with a card.","grammar:886:ex5:structure":"〜で〜をしました","grammar:886:ex5:words:0:zh":"card","grammar:886:ex5:words:0:note":"loanword","grammar:886:ex5:words:0:pos":"noun","grammar:886:ex5:words:1:zh":"(means)","grammar:886:ex5:words:1:pos":"particle","grammar:886:ex5:words:2:zh":"payment","grammar:886:ex5:words:2:note":"しはらい","grammar:886:ex5:words:2:pos":"noun","grammar:886:ex5:words:3:zh":"(object marker)","grammar:886:ex5:words:3:pos":"particle","grammar:886:ex5:words:4:zh":"did","grammar:886:ex5:words:4:pos":"verb","grammar:886:ex5:points:0":"❓カードで: with a card (で marks the means).","grammar:886:ex5:points:1":"支払いをする: to pay.","exam:886:zh":"When you withdraw money at the bank, you put this card into the machine.","exam:886:why":"「カード」 means card, here the card used for withdrawals. 「切符」 is a ticket, which can't be used to withdraw money at a bank."},"887":{"example:887:exzh":"He is in the sales department.","example:887:exzh2":"This department is very busy.","example:887:exzh3":"I talked with the department head.","example:887:exzh4":"A new member joined.","example:887:exzh5":"The department meeting is tomorrow.","grammar:887:ex:trans":"He is in the sales department.","grammar:887:ex:structure":"〜にいます","grammar:887:ex:explain":"The key point is that 「部（ぶ）」 means department, as in 「営業部」 (sales department). The pattern is the existence sentence 「〜にいます」: the location takes 「に」, and people take 「いる」 (here the polite 「います」). 「営業部にいる」 means a person is in the sales department. Note that people and animals take 「いる」, while only inanimate things take 「ある」. The whole sentence says that he belongs to and is stationed in the sales department.","grammar:887:ex:words:0:zh":"he","grammar:887:ex:words:0:note":"かれ","grammar:887:ex:words:0:pos":"pronoun","grammar:887:ex:words:1:zh":"(topic)","grammar:887:ex:words:1:pos":"particle","grammar:887:ex:words:2:zh":"sales department","grammar:887:ex:words:2:note":"えいぎょうぶ","grammar:887:ex:words:2:pos":"noun","grammar:887:ex:words:3:zh":"(location of existence)","grammar:887:ex:words:3:pos":"particle","grammar:887:ex:words:4:zh":"exist","grammar:887:ex:words:4:pos":"verb","grammar:887:ex:points:0":"❗部（ぶ）: department (営業部 = sales department).","grammar:887:ex:points:1":"〜にいる: to be in… (for people).","grammar:887:ex2:trans":"This department is very busy.","grammar:887:ex2:structure":"〜はとても〜です","grammar:887:ex2:words:0:zh":"this","grammar:887:ex2:words:0:pos":"pre-noun adjectival","grammar:887:ex2:words:1:zh":"department","grammar:887:ex2:words:1:note":"ぶ","grammar:887:ex2:words:1:pos":"noun","grammar:887:ex2:words:2:zh":"(topic)","grammar:887:ex2:words:2:pos":"particle","grammar:887:ex2:words:3:zh":"extremely","grammar:887:ex2:words:3:pos":"adverb","grammar:887:ex2:words:4:zh":"busy","grammar:887:ex2:words:4:note":"いそがしい","grammar:887:ex2:words:4:pos":"adjective","grammar:887:ex2:words:5:zh":"(polite form)","grammar:887:ex2:words:5:pos":"copula","grammar:887:ex2:points:0":"この部: this department.","grammar:887:ex2:points:1":"忙しい: busy.","grammar:887:ex3:trans":"I spoke with the department head.","grammar:887:ex3:structure":"〜と話しました","grammar:887:ex3:words:0:zh":"department head","grammar:887:ex3:words:0:note":"ぶちょう","grammar:887:ex3:words:0:pos":"noun","grammar:887:ex3:words:1:zh":"(object)","grammar:887:ex3:words:1:pos":"particle","grammar:887:ex3:words:2:zh":"said","grammar:887:ex3:words:2:note":"はなしました","grammar:887:ex3:words:2:pos":"verb","grammar:887:ex3:points:0":"部長: department head, department manager.","grammar:887:ex3:points:1":"〜と話す: to talk with…","grammar:887:ex4:trans":"A new department member joined.","grammar:887:ex4:structure":"〜が来ました","grammar:887:ex4:words:0:zh":"new","grammar:887:ex4:words:0:note":"あたらしい","grammar:887:ex4:words:0:pos":"adjective","grammar:887:ex4:words:1:zh":"department member","grammar:887:ex4:words:1:note":"ぶいん","grammar:887:ex4:words:1:pos":"noun","grammar:887:ex4:words:2:zh":"(nominative)","grammar:887:ex4:words:2:pos":"particle","grammar:887:ex4:words:3:zh":"came","grammar:887:ex4:words:3:note":"きました","grammar:887:ex4:words:3:pos":"verb","grammar:887:ex4:points:0":"部員: department member (部 + 員).","grammar:887:ex4:points:1":"来る → 来ました.","grammar:887:ex5:trans":"The department meeting is tomorrow.","grammar:887:ex5:structure":"〜は明日です","grammar:887:ex5:words:0:zh":"department","grammar:887:ex5:words:0:note":"ぶ","grammar:887:ex5:words:0:pos":"noun","grammar:887:ex5:words:1:zh":"'s","grammar:887:ex5:words:1:pos":"particle","grammar:887:ex5:words:2:zh":"meeting","grammar:887:ex5:words:2:note":"かいぎ","grammar:887:ex5:words:2:pos":"noun","grammar:887:ex5:words:3:zh":"(topic)","grammar:887:ex5:words:3:pos":"particle","grammar:887:ex5:words:4:zh":"tomorrow","grammar:887:ex5:words:4:note":"あした","grammar:887:ex5:words:4:pos":"noun","grammar:887:ex5:words:5:zh":"is","grammar:887:ex5:words:5:pos":"copula","grammar:887:ex5:points:0":"部の会議: department meeting.","grammar:887:ex5:points:1":"明日: tomorrow."},"888":{"example:888:exzh":"He always lies.","example:888:exzh2":"I saw through her lie easily.","example:888:exzh3":"Lying is not good.","example:888:exzh4":"To be honest, I don't want to lie.","example:888:exzh5":"If a lie is found out, you lose trust."},"890":{"example:890:exzh":"This is a very important matter.","example:890:exzh2":"She is a very kind person.","example:890:exzh3":"I faced a very difficult problem.","example:890:exzh4":"This is a very delicious dish.","example:890:exzh5":"I'm extremely tired."},"891":{"example:891:exzh":"The wall is dirty.","example:891:exzh2":"I hung a picture on the wall.","example:891:exzh3":"This wall is thick.","example:891:exzh4":"There's a hole in the wall.","example:891:exzh5":"I'll paint the brand-new wall.","grammar:891:ex:trans":"The wall is dirty.","grammar:891:ex:structure":"〜が汚れています","grammar:891:ex:explain":"The key point is the intransitive verb 「汚れる（よごれる）」, meaning to become dirty — a natural change, with the subject marked by 「が」. When it takes 「〜ている」 to become 「汚れている」, it does not describe an action in progress but a resulting state that continues: the wall is already in a dirty state. This intransitive verb + ている pattern for states is very common; 「窓が開いている」 works the same way. The whole sentence means the wall has become dirty, or is dirty.","grammar:891:ex:words:0:zh":"wall","grammar:891:ex:words:0:note":"かべ","grammar:891:ex:words:0:pos":"noun","grammar:891:ex:words:1:zh":"(nominative)","grammar:891:ex:words:1:pos":"particle","grammar:891:ex:words:2:zh":"is dirty","grammar:891:ex:words:2:note":"よごれています","grammar:891:ex:words:2:pos":"verb","grammar:891:ex:points:0":"❗汚れる (intransitive verb, to become dirty); 〜ている = 汚れている describes a state.","grammar:891:ex:points:1":"壁が汚れる: the wall gets dirty.","grammar:891:ex2:trans":"I hung a picture on the wall.","grammar:891:ex2:structure":"〜に〜を掛けました","grammar:891:ex2:words:0:zh":"I","grammar:891:ex2:words:0:note":"わたし","grammar:891:ex2:words:0:pos":"pronoun","grammar:891:ex2:words:1:zh":"(topic)","grammar:891:ex2:words:1:pos":"particle","grammar:891:ex2:words:2:zh":"wall","grammar:891:ex2:words:2:note":"かべ","grammar:891:ex2:words:2:pos":"noun","grammar:891:ex2:words:3:zh":"(the surface it is attached to)","grammar:891:ex2:words:3:pos":"particle","grammar:891:ex2:words:4:zh":"picture","grammar:891:ex2:words:4:note":"え","grammar:891:ex2:words:4:pos":"noun","grammar:891:ex2:words:5:zh":"(object marker)","grammar:891:ex2:words:5:pos":"particle","grammar:891:ex2:words:6:zh":"hung","grammar:891:ex2:words:6:note":"かけました","grammar:891:ex2:words:6:pos":"verb","grammar:891:ex2:points:0":"❗掛ける (transitive verb, to hang something up); 壁に絵を掛ける: to hang a picture on the wall.","grammar:891:ex2:points:1":"掛ける→掛けました。","grammar:891:ex3:trans":"This wall is thick.","grammar:891:ex3:structure":"〜は厚いです","grammar:891:ex3:words:0:zh":"this","grammar:891:ex3:words:0:pos":"pre-noun adjectival","grammar:891:ex3:words:1:zh":"wall","grammar:891:ex3:words:1:note":"かべ","grammar:891:ex3:words:1:pos":"noun","grammar:891:ex3:words:2:zh":"(topic)","grammar:891:ex3:words:2:pos":"particle","grammar:891:ex3:words:3:zh":"thick","grammar:891:ex3:words:3:note":"あつい","grammar:891:ex3:words:3:pos":"adjective","grammar:891:ex3:words:4:zh":"(polite form)","grammar:891:ex3:words:4:pos":"copula","grammar:891:ex3:points:0":"厚い: thick.","grammar:891:ex3:points:1":"この壁: this wall.","grammar:891:ex4:trans":"There is a hole in the wall.","grammar:891:ex4:structure":"〜に〜が開いています","grammar:891:ex4:words:0:zh":"wall","grammar:891:ex4:words:0:note":"かべ","grammar:891:ex4:words:0:pos":"noun","grammar:891:ex4:words:1:zh":"(location of existence)","grammar:891:ex4:words:1:pos":"particle","grammar:891:ex4:words:2:zh":"hole","grammar:891:ex4:words:2:note":"あな","grammar:891:ex4:words:2:pos":"noun","grammar:891:ex4:words:3:zh":"(nominative)","grammar:891:ex4:words:3:pos":"particle","grammar:891:ex4:words:4:zh":"are blooming","grammar:891:ex4:words:4:note":"あいています","grammar:891:ex4:words:4:pos":"verb","grammar:891:ex4:points:0":"❗穴が開く: (for there to be) a hole (intransitive 開く).","grammar:891:ex4:points:1":"壁に穴が開く: there is a hole in the wall.","grammar:891:ex5:trans":"Paint the brand-new wall.","grammar:891:ex5:structure":"〜にペンキを塗ります","grammar:891:ex5:words:0:zh":"brand-new","grammar:891:ex5:words:0:note":"まあたらしい","grammar:891:ex5:words:0:pos":"adjective","grammar:891:ex5:words:1:zh":"wall","grammar:891:ex5:words:1:note":"かべ","grammar:891:ex5:words:1:pos":"noun","grammar:891:ex5:words:2:zh":"(object)","grammar:891:ex5:words:2:pos":"particle","grammar:891:ex5:words:3:zh":"paint","grammar:891:ex5:words:3:note":"loanword","grammar:891:ex5:words:3:pos":"noun","grammar:891:ex5:words:4:zh":"(object marker)","grammar:891:ex5:words:4:pos":"particle","grammar:891:ex5:words:5:zh":"to paint (apply)","grammar:891:ex5:words:5:note":"ぬります","grammar:891:ex5:words:5:pos":"verb","grammar:891:ex5:points:0":"❗真新しい: brand-new (真 + 新しい).","grammar:891:ex5:points:1":"❗壁にペンキを塗る: to paint a wall."},"892":{"example:892:exzh":"My little sister is doing her homework.","example:892:exzh2":"My little sister is 14 years old.","example:892:exzh3":"I played with my little sister.","example:892:exzh4":"She is my little sister.","example:892:exzh5":"My little sister has an anime she likes.","grammar:892:ex:trans":"My little sister is doing her homework.","grammar:892:ex:structure":"〜が〜をしています","grammar:892:ex:explain":"The key point is that 「妹（いもうと）」 is the humble word for one's own younger sister; for someone else's younger sister you use 「妹さん」. 「宿題をする」 means to do homework, with the object marked by 「を」. At the end, 「しています」 from 「〜ている」 shows an action in progress, so 「宿題をしている」 means is doing homework. The subject 「妹」 takes 「が」, highlighting what is happening. The whole sentence means my little sister is doing her homework.","grammar:892:ex:words:0:zh":"younger sister","grammar:892:ex:words:0:note":"いもうと","grammar:892:ex:words:0:pos":"noun","grammar:892:ex:words:1:zh":"(nominative)","grammar:892:ex:words:1:pos":"particle","grammar:892:ex:words:2:zh":"homework","grammar:892:ex:words:2:note":"しゅくだい","grammar:892:ex:words:2:pos":"noun","grammar:892:ex:words:3:zh":"(object marker)","grammar:892:ex:words:3:pos":"particle","grammar:892:ex:words:4:zh":"is doing","grammar:892:ex:words:4:pos":"verb","grammar:892:ex:points:0":"❗妹（いもうと）: (humble) one's own younger sister; for someone else's younger sister use 妹さん.","grammar:892:ex:points:1":"宿題をする: to do homework.","grammar:892:ex2:trans":"My little sister is 14 years old.","grammar:892:ex2:structure":"〜は〜歳です","grammar:892:ex2:words:0:zh":"I","grammar:892:ex2:words:0:note":"わたし","grammar:892:ex2:words:0:pos":"pronoun","grammar:892:ex2:words:1:zh":"'s","grammar:892:ex2:words:1:pos":"particle","grammar:892:ex2:words:2:zh":"younger sister","grammar:892:ex2:words:2:note":"いもうと","grammar:892:ex2:words:2:pos":"noun","grammar:892:ex2:words:3:zh":"(topic)","grammar:892:ex2:words:3:pos":"particle","grammar:892:ex2:words:4:zh":"fourteen years old","grammar:892:ex2:words:4:note":"じゅうよんさい","grammar:892:ex2:words:4:pos":"noun","grammar:892:ex2:words:5:zh":"is","grammar:892:ex2:words:5:pos":"copula","grammar:892:ex2:points:0":"14歳: fourteen years old.","grammar:892:ex2:points:1":"私の妹: my little sister.","grammar:892:ex3:trans":"I played with my little sister.","grammar:892:ex3:structure":"〜と一緒に遊びました","grammar:892:ex3:words:0:zh":"younger sister","grammar:892:ex3:words:0:note":"いもうと","grammar:892:ex3:words:0:pos":"noun","grammar:892:ex3:words:1:zh":"with","grammar:892:ex3:words:1:pos":"particle","grammar:892:ex3:words:2:zh":"together","grammar:892:ex3:words:2:note":"いっしょに","grammar:892:ex3:words:2:pos":"adverb","grammar:892:ex3:words:3:zh":"hung out / played","grammar:892:ex3:words:3:note":"あそびました","grammar:892:ex3:words:3:pos":"verb","grammar:892:ex3:points:0":"妹と一緒に: together with my little sister.","grammar:892:ex3:points:1":"遊ぶ→遊びました。","grammar:892:ex4:trans":"She is my little sister.","grammar:892:ex4:structure":"〜は〜の妹です","grammar:892:ex4:words:0:zh":"she","grammar:892:ex4:words:0:note":"かのじょ","grammar:892:ex4:words:0:pos":"pronoun","grammar:892:ex4:words:1:zh":"(topic)","grammar:892:ex4:words:1:pos":"particle","grammar:892:ex4:words:2:zh":"I","grammar:892:ex4:words:2:note":"わたし","grammar:892:ex4:words:2:pos":"pronoun","grammar:892:ex4:words:3:zh":"'s","grammar:892:ex4:words:3:pos":"particle","grammar:892:ex4:words:4:zh":"younger sister","grammar:892:ex4:words:4:note":"いもうと","grammar:892:ex4:words:4:pos":"noun","grammar:892:ex4:words:5:zh":"is","grammar:892:ex4:words:5:pos":"copula","grammar:892:ex4:points:0":"私の妹: my little sister.","grammar:892:ex4:points:1":"彼女は: she (topic).","grammar:892:ex5:trans":"My little sister has an anime she likes.","grammar:892:ex5:structure":"〜が好きな〜があります","grammar:892:ex5:words:0:zh":"younger sister","grammar:892:ex5:words:0:note":"いもうと","grammar:892:ex5:words:0:pos":"noun","grammar:892:ex5:words:1:zh":"(nominative)","grammar:892:ex5:words:1:pos":"particle","grammar:892:ex5:words:2:zh":"to like","grammar:892:ex5:words:2:note":"すき","grammar:892:ex5:words:2:pos":"na-adjective","grammar:892:ex5:words:3:zh":"(attributive form)","grammar:892:ex5:words:3:pos":"auxiliary verb","grammar:892:ex5:words:4:zh":"anime","grammar:892:ex5:words:4:note":"loanword","grammar:892:ex5:words:4:pos":"noun","grammar:892:ex5:words:5:zh":"(nominative)","grammar:892:ex5:words:5:pos":"particle","grammar:892:ex5:words:6:zh":"there is / are","grammar:892:ex5:words:6:pos":"verb","grammar:892:ex5:points:0":"❗妹が好きなアニメ: the anime my little sister likes (the subject inside a noun-modifying clause takes が).","grammar:892:ex5:points:1":"アニメ: anime.","exam:892:zh":"A female sibling three years younger than me is my younger sister.","exam:892:why":"「妹」 means younger sister, which matches the conditions of being female and younger. 「姉」 is older sister, who is older than you."},"893":{"example:893:exzh":"Understanding cultural differences is important.","example:893:exzh2":"There are many differences between the two countries.","example:893:exzh3":"He and I have different ways of thinking.","example:893:exzh4":"There's a clear difference in this issue.","example:893:exzh5":"We must respect differences.","grammar:893:ex:trans":"Understanding cultural differences is important.","grammar:893:ex:structure":"〜ことが大切です","grammar:893:ex:explain":"There are two key points. First, 「違い（ちがい）」 is the noun form of the verb 「違う」, meaning difference, so 「文化の違い」 means cultural differences. Second, 「〜ことが大切です」: the formal noun 「こと」 nominalizes the verb 「理解する」 into the act of understanding…, and 「が」 then links it to the na-adjective 「大切」 for evaluation. The whole sentence means that understanding cultural differences is important.","grammar:893:ex:words:0:zh":"culture","grammar:893:ex:words:0:note":"ぶんか","grammar:893:ex:words:0:pos":"noun","grammar:893:ex:words:1:zh":"'s","grammar:893:ex:words:1:pos":"particle","grammar:893:ex:words:2:zh":"difference","grammar:893:ex:words:2:note":"ちがい","grammar:893:ex:words:2:pos":"noun","grammar:893:ex:words:3:zh":"(object marker)","grammar:893:ex:words:3:pos":"particle","grammar:893:ex:words:4:zh":"understanding","grammar:893:ex:words:4:note":"りかいする","grammar:893:ex:words:4:pos":"verb","grammar:893:ex:words:5:zh":"(nominalizer)","grammar:893:ex:words:5:pos":"noun","grammar:893:ex:words:6:zh":"(nominative)","grammar:893:ex:words:6:pos":"particle","grammar:893:ex:words:7:zh":"important","grammar:893:ex:words:7:note":"たいせつ","grammar:893:ex:words:7:pos":"na-adjective","grammar:893:ex:words:8:zh":"(polite form)","grammar:893:ex:words:8:pos":"copula","grammar:893:ex:points:0":"違い（ちがい）: difference (noun form of 違う).","grammar:893:ex:points:1":"〜ことが大切です: doing … is important.","grammar:893:ex2:trans":"There are many differences between the two countries.","grammar:893:ex2:structure":"〜には〜があります (〜 has 〜)","grammar:893:ex2:words:0:zh":"two","grammar:893:ex2:words:0:note":"ふたつ","grammar:893:ex2:words:0:pos":"noun","grammar:893:ex2:words:1:zh":"'s","grammar:893:ex2:words:1:pos":"particle","grammar:893:ex2:words:2:zh":"country","grammar:893:ex2:words:2:note":"くに","grammar:893:ex2:words:2:pos":"noun","grammar:893:ex2:words:3:zh":"(scope)","grammar:893:ex2:words:3:pos":"particle","grammar:893:ex2:words:4:zh":"(contrast)","grammar:893:ex2:words:4:pos":"particle","grammar:893:ex2:words:5:zh":"a lot","grammar:893:ex2:words:5:note":"おおく","grammar:893:ex2:words:5:pos":"noun","grammar:893:ex2:words:6:zh":"'s","grammar:893:ex2:words:6:pos":"particle","grammar:893:ex2:words:7:zh":"difference","grammar:893:ex2:words:7:note":"ちがい","grammar:893:ex2:words:7:pos":"noun","grammar:893:ex2:words:8:zh":"(nominative)","grammar:893:ex2:words:8:pos":"particle","grammar:893:ex2:words:9:zh":"there is / are","grammar:893:ex2:words:9:pos":"verb","grammar:893:ex2:points:0":"二つの国: two countries.","grammar:893:ex2:points:1":"〜には〜がある: … has…, there is… in…","grammar:893:ex3:trans":"His way of thinking and mine differ.","grammar:893:ex3:structure":"〜には違いがある","grammar:893:ex3:words:0:zh":"he","grammar:893:ex3:words:0:note":"かれ","grammar:893:ex3:words:0:pos":"pronoun","grammar:893:ex3:words:1:zh":"with","grammar:893:ex3:words:1:pos":"particle","grammar:893:ex3:words:2:zh":"I","grammar:893:ex3:words:2:note":"わたし","grammar:893:ex3:words:2:pos":"pronoun","grammar:893:ex3:words:3:zh":"'s","grammar:893:ex3:words:3:pos":"particle","grammar:893:ex3:words:4:zh":"idea","grammar:893:ex3:words:4:note":"かんがえかた","grammar:893:ex3:words:4:pos":"noun","grammar:893:ex3:words:5:zh":"(scope)","grammar:893:ex3:words:5:pos":"particle","grammar:893:ex3:words:6:zh":"(contrast)","grammar:893:ex3:words:6:pos":"particle","grammar:893:ex3:words:7:zh":"difference","grammar:893:ex3:words:7:note":"ちがい","grammar:893:ex3:words:7:pos":"noun","grammar:893:ex3:words:8:zh":"(nominative)","grammar:893:ex3:words:8:pos":"particle","grammar:893:ex3:words:9:zh":"there is / are","grammar:893:ex3:words:9:pos":"verb","grammar:893:ex3:points:0":"❗考え方: way of thinking (考える + 方).","grammar:893:ex3:points:1":"〜には違いがある: there is a difference in…","grammar:893:ex4:trans":"There is a clear difference in this issue.","grammar:893:ex4:structure":"〜には〜な違いがあります","grammar:893:ex4:words:0:zh":"this","grammar:893:ex4:words:0:pos":"pre-noun adjectival","grammar:893:ex4:words:1:zh":"problem","grammar:893:ex4:words:1:note":"もんだい","grammar:893:ex4:words:1:pos":"noun","grammar:893:ex4:words:2:zh":"(scope)","grammar:893:ex4:words:2:pos":"particle","grammar:893:ex4:words:3:zh":"(contrast)","grammar:893:ex4:words:3:pos":"particle","grammar:893:ex4:words:4:zh":"clear","grammar:893:ex4:words:4:note":"めいかく","grammar:893:ex4:words:4:pos":"na-adjective","grammar:893:ex4:words:5:zh":"(attributive form)","grammar:893:ex4:words:5:pos":"auxiliary verb","grammar:893:ex4:words:6:zh":"difference","grammar:893:ex4:words:6:note":"ちがい","grammar:893:ex4:words:6:pos":"noun","grammar:893:ex4:words:7:zh":"(nominative)","grammar:893:ex4:words:7:pos":"particle","grammar:893:ex4:words:8:zh":"there is / are","grammar:893:ex4:words:8:pos":"verb","grammar:893:ex4:points:0":"明確な違い: a clear difference.","grammar:893:ex4:points:1":"明確: clear.","grammar:893:ex5:trans":"We must respect differences.","grammar:893:ex5:structure":"〜をしなければなりません","grammar:893:ex5:words:0:zh":"difference","grammar:893:ex5:words:0:note":"ちがい","grammar:893:ex5:words:0:pos":"noun","grammar:893:ex5:words:1:zh":"(object marker)","grammar:893:ex5:words:1:pos":"particle","grammar:893:ex5:words:2:zh":"must respect","grammar:893:ex5:words:2:note":"そんちょうしなければなりません","grammar:893:ex5:words:2:pos":"verb","grammar:893:ex5:points:0":"違いを尊重する: to respect differences.","grammar:893:ex5:points:1":"〜なければなりません: must …"},"894":{"example:894:exzh":"I still owe him money that I borrowed.","example:894:exzh2":"I still owe a friend money that I borrowed.","example:894:exzh3":"I plan to pay back the money I borrowed.","example:894:exzh4":"May I pay back the money I borrowed with this?","example:894:exzh5":"I forgot to pay back the money I borrowed.","grammar:894:ex:trans":"I still have money I borrowed from him that I haven't paid back.","grammar:894:ex:structure":"人にはお金の借りがあります","grammar:894:ex:explain":"「彼に」 marks him as the person owed, and the 「は」 after it brings that person up as the topic. 「お金の借り」 narrows 「借り」 to a debt of money, and 「が」 marks the thing that exists. 「あります」 says that this debt still exists, so the whole sentence means I still owe him money; the person who owes is omitted and understood from context.","grammar:894:ex:words:0:zh":"he","grammar:894:ex:words:0:note":"かれ","grammar:894:ex:words:0:pos":"pronoun","grammar:894:ex:words:1:zh":"(the person owed)","grammar:894:ex:words:1:pos":"particle","grammar:894:ex:words:2:zh":"(topic, contrast)","grammar:894:ex:words:2:pos":"particle","grammar:894:ex:words:3:zh":"(beautifying prefix)","grammar:894:ex:words:3:pos":"prefix","grammar:894:ex:words:4:zh":"money","grammar:894:ex:words:4:note":"かね","grammar:894:ex:words:4:pos":"noun","grammar:894:ex:words:5:zh":"(specifies what kind of debt)","grammar:894:ex:words:5:pos":"particle","grammar:894:ex:words:6:zh":"an unpaid debt","grammar:894:ex:words:6:note":"かり","grammar:894:ex:words:6:pos":"noun","grammar:894:ex:words:7:zh":"(nominative)","grammar:894:ex:words:7:pos":"particle","grammar:894:ex:words:8:zh":"there is / are","grammar:894:ex:words:8:pos":"verb","grammar:894:ex:words:9:zh":"(polite tone)","grammar:894:ex:words:9:pos":"auxiliary verb","grammar:894:ex:points:0":"「人に借りがある」 means to owe someone money or a favor.","grammar:894:ex:points:1":"Here 「借り」 is a noun meaning a debt that has not yet been repaid.","grammar:894:ex:points:2":"「には」 is made of 「に」 plus 「は」; it keeps the marking-the-target function and makes that person the topic.","grammar:894:ex2:trans":"I still have money I borrowed from a friend that I haven't paid back.","grammar:894:ex2:structure":"友達にはお金の借りがあります","grammar:894:ex2:explain":"「友達には」 indicates that the person owed is a friend, where 「に」 marks the target and 「は」 raises it as the topic. 「お金の借りがあります」 means there is a money debt that has not been repaid. The sentence never says I explicitly, but in this context it is normally understood that the speaker borrowed money from a friend and has not paid it back.","grammar:894:ex2:words:0:zh":"friend","grammar:894:ex2:words:0:note":"ともだち","grammar:894:ex2:words:0:pos":"noun","grammar:894:ex2:words:1:zh":"(the person owed)","grammar:894:ex2:words:1:pos":"particle","grammar:894:ex2:words:2:zh":"(topic, contrast)","grammar:894:ex2:words:2:pos":"particle","grammar:894:ex2:words:3:zh":"(beautifying prefix)","grammar:894:ex2:words:3:pos":"prefix","grammar:894:ex2:words:4:zh":"money","grammar:894:ex2:words:4:note":"かね","grammar:894:ex2:words:4:pos":"noun","grammar:894:ex2:words:5:zh":"(specifies what kind of debt)","grammar:894:ex2:words:5:pos":"particle","grammar:894:ex2:words:6:zh":"an unpaid debt","grammar:894:ex2:words:6:note":"かり","grammar:894:ex2:words:6:pos":"noun","grammar:894:ex2:words:7:zh":"(nominative)","grammar:894:ex2:words:7:pos":"particle","grammar:894:ex2:words:8:zh":"there is / are","grammar:894:ex2:words:8:pos":"verb","grammar:894:ex2:words:9:zh":"(polite tone)","grammar:894:ex2:words:9:pos":"auxiliary verb","grammar:894:ex2:points:0":"「友達に借りがある」 means you owe a friend money or a favor — not that the friend owes you.","grammar:894:ex2:points:1":"「お金の借り」 makes it clear that the debt is about money.","grammar:894:ex2:points:2":"「借りがある」 describes a debt that still exists now.","grammar:894:ex3:trans":"I intend to pay back the money I borrowed.","grammar:894:ex3:structure":"〜を返すつもりです","grammar:894:ex3:explain":"「お金の借り」 refers to a money debt, and 「を」 marks what is to be repaid. 「返す」 is a transitive verb and is followed directly by 「つもりです」, showing that the speaker intends to do this. The pattern expresses intention; it does not mean the money has already been repaid.","grammar:894:ex3:words:0:zh":"(beautifying prefix)","grammar:894:ex3:words:0:pos":"prefix","grammar:894:ex3:words:1:zh":"money","grammar:894:ex3:words:1:note":"かね","grammar:894:ex3:words:1:pos":"noun","grammar:894:ex3:words:2:zh":"(specifies what kind of debt)","grammar:894:ex3:words:2:pos":"particle","grammar:894:ex3:words:3:zh":"a loan, a debt","grammar:894:ex3:words:3:note":"かり","grammar:894:ex3:words:3:pos":"noun","grammar:894:ex3:words:4:zh":"(object)","grammar:894:ex3:words:4:pos":"particle","grammar:894:ex3:words:5:zh":"atone for","grammar:894:ex3:words:5:note":"かえす","grammar:894:ex3:words:5:pos":"verb","grammar:894:ex3:words:6:zh":"intend to","grammar:894:ex3:words:6:pos":"noun","grammar:894:ex3:words:7:zh":"(polite tone)","grammar:894:ex3:words:7:pos":"auxiliary verb","grammar:894:ex3:points:0":"「verb dictionary form + つもりです」 expresses a plan you already have.","grammar:894:ex3:points:1":"「借りを返す」 means to repay a debt, and can also be used for returning a favor.","grammar:894:ex4:trans":"May I pay back the money I borrowed with this?","grammar:894:ex4:structure":"これで〜を返してもいいですか","grammar:894:ex4:explain":"「これで」 means with this, as the means of repayment; what it actually refers to depends on the situation. 「お金の借りを返す」 means to repay the money debt. 「返してもいいですか」 asks whether the other person permits or accepts this, so the point is getting consent, not asking whether you are able to repay.","grammar:894:ex4:words:0:zh":"this","grammar:894:ex4:words:0:pos":"pronoun","grammar:894:ex4:words:1:zh":"(the means, the thing used)","grammar:894:ex4:words:1:pos":"particle","grammar:894:ex4:words:2:zh":"(beautifying prefix)","grammar:894:ex4:words:2:pos":"prefix","grammar:894:ex4:words:3:zh":"money","grammar:894:ex4:words:3:note":"かね","grammar:894:ex4:words:3:pos":"noun","grammar:894:ex4:words:4:zh":"(specifies what kind of debt)","grammar:894:ex4:words:4:pos":"particle","grammar:894:ex4:words:5:zh":"a loan, a debt","grammar:894:ex4:words:5:note":"かり","grammar:894:ex4:words:5:pos":"noun","grammar:894:ex4:words:6:zh":"(object)","grammar:894:ex4:words:6:pos":"particle","grammar:894:ex4:words:7:zh":"atone for","grammar:894:ex4:words:7:note":"かえし","grammar:894:ex4:words:7:pos":"verb","grammar:894:ex4:words:8:zh":"(links to the permission pattern)","grammar:894:ex4:words:8:pos":"particle","grammar:894:ex4:words:9:zh":"(even if — forms the permission pattern)","grammar:894:ex4:words:9:pos":"particle","grammar:894:ex4:words:10:zh":"it's okay","grammar:894:ex4:words:10:pos":"i-adjective","grammar:894:ex4:words:11:zh":"(polite tone)","grammar:894:ex4:words:11:pos":"auxiliary verb","grammar:894:ex4:words:12:zh":"(question)","grammar:894:ex4:words:12:pos":"particle","grammar:894:ex4:points:0":"「verb te-form + もいいですか」 is used to ask whether one may do something.","grammar:894:ex4:points:1":"The 「で」 in 「これで」 marks the means or thing used to repay.","grammar:894:ex4:points:2":"The te-form of 「返す」 is 「返して」, not 「返すて」.","grammar:894:ex5:trans":"I forgot to pay back the money I borrowed.","grammar:894:ex5:structure":"〜を返すのを忘れた","grammar:894:ex5:explain":"The first 「の」 links 「お金」 to 「借り」, giving a debt of money; the second 「の」 nominalizes the whole action 「お金の借りを返す」. That nominalized phrase then takes 「を」 with 「忘れた」, meaning forgot to repay. 「忘れた」 is the plain past form.","grammar:894:ex5:words:0:zh":"(beautifying prefix)","grammar:894:ex5:words:0:pos":"prefix","grammar:894:ex5:words:1:zh":"money","grammar:894:ex5:words:1:note":"かね","grammar:894:ex5:words:1:pos":"noun","grammar:894:ex5:words:2:zh":"(specifies what kind of debt)","grammar:894:ex5:words:2:pos":"particle","grammar:894:ex5:words:3:zh":"a loan, a debt","grammar:894:ex5:words:3:note":"かり","grammar:894:ex5:words:3:pos":"noun","grammar:894:ex5:words:4:zh":"(the object of repayment)","grammar:894:ex5:words:4:pos":"particle","grammar:894:ex5:words:5:zh":"atone for","grammar:894:ex5:words:5:note":"かえす","grammar:894:ex5:words:5:pos":"verb","grammar:894:ex5:words:6:zh":"(nominalizes the action)","grammar:894:ex5:words:6:pos":"particle","grammar:894:ex5:words:7:zh":"(the object of forgetting)","grammar:894:ex5:words:7:pos":"particle","grammar:894:ex5:words:8:zh":"forgot","grammar:894:ex5:words:8:note":"わすれ","grammar:894:ex5:words:8:pos":"verb","grammar:894:ex5:words:9:zh":"(past)","grammar:894:ex5:words:9:pos":"auxiliary verb","grammar:894:ex5:points:0":"「verb dictionary form + のを忘れる」 means to forget to do something.","grammar:894:ex5:points:1":"The two 「を」 mark, respectively, what is being repaid and what was forgotten.","grammar:894:ex5:points:2":"「返すのを忘れた」 means forgot to repay, while 「返したのを忘れた」 means forgot that you had already repaid."},"895":{"example:895:exzh":"I wasted time.","example:895:exzh2":"Let's stop wasting money.","example:895:exzh3":"I felt that those efforts were in vain.","example:895:exzh4":"You should avoid pointless arguments.","example:895:exzh5":"Even if people say it's a waste, I don't mind."},"896":{"example:896:exzh":"Please wait there.","example:896:exzh2":"Please wait a moment.","example:896:exzh3":"I couldn't wait for him, so I went on ahead.","example:896:exzh4":"You just have to wait a little while.","example:896:exzh5":"Can I wait here?","grammar:896:ex:trans":"Please wait there.","grammar:896:ex:structure":"placeに＋〔いて〕＋待ってください。 「そこにいて」 links with the te-form, and 「待ってください」 means please wait.","grammar:896:ex:explain":"Two key points. First, 「〜にいる」 says a person is somewhere, so 「そこにいる」 means being there, with the location marked by 「に」. Second, te-form linking: the te-form of 「いる」, 「いて」, connects being there with the following 「待つ」, so 「いて待ってください」 means stay there and wait. 「待って」 is the te-form of 「待つ」 plus 「ください」, which makes a request. The whole sentence means please wait there.","grammar:896:ex:words:0:zh":"there","grammar:896:ex:words:0:pos":"pronoun","grammar:896:ex:words:1:zh":"(the place where something exists)","grammar:896:ex:words:1:pos":"particle","grammar:896:ex:words:2:zh":"stay (and)","grammar:896:ex:words:2:note":"いて; the te-form of いる","grammar:896:ex:words:2:pos":"verb","grammar:896:ex:words:3:zh":"wait","grammar:896:ex:words:3:note":"まって; te-form","grammar:896:ex:words:3:pos":"verb","grammar:896:ex:words:4:zh":"please","grammar:896:ex:words:4:note":"〜てください","grammar:896:ex:words:4:pos":"verb","grammar:896:ex:points:0":"〜にいる: (a person) is somewhere","grammar:896:ex:points:1":"te-form linking: いて待つ (stay there and wait)","grammar:896:ex2:trans":"Please wait a moment.","grammar:896:ex2:structure":"verb te-form＋ください。","grammar:896:ex2:words:0:zh":"wait","grammar:896:ex2:words:0:note":"まって; te-form","grammar:896:ex2:words:0:pos":"verb","grammar:896:ex2:words:1:zh":"please","grammar:896:ex2:words:1:note":"〜てください","grammar:896:ex2:words:1:pos":"verb","grammar:896:ex2:points:0":"待つ→待って: te-form (sokuon change)","grammar:896:ex2:points:1":"〜てください: please do…","grammar:896:ex3:trans":"I could not wait for him, so I went on ahead.","grammar:896:ex3:structure":"nounを＋〔negative potential te-form〕、先に＋行った。 「待てなくて」 gives the reason: because I could not wait.","grammar:896:ex3:words:0:zh":"he","grammar:896:ex3:words:0:note":"かれ","grammar:896:ex3:words:0:pos":"pronoun","grammar:896:ex3:words:1:zh":"(object marker)","grammar:896:ex3:words:1:pos":"particle","grammar:896:ex3:words:2:zh":"could not wait (and so)","grammar:896:ex3:words:2:note":"またなくて; negative potential te-form, showing cause","grammar:896:ex3:words:2:pos":"verb","grammar:896:ex3:words:3:zh":"first","grammar:896:ex3:words:3:note":"さきに","grammar:896:ex3:words:3:pos":"adverb","grammar:896:ex3:words:4:zh":"went","grammar:896:ex3:words:4:note":"いった","grammar:896:ex3:words:4:pos":"verb","grammar:896:ex3:points:0":"待てる: can wait (potential form)","grammar:896:ex3:points:1":"〜なくて: (cause) because one cannot…","grammar:896:ex4:trans":"You just have to wait a little.","grammar:896:ex4:structure":"〔verb ba-form〕＋いい。 「〜ばいい」 means it is enough to… / you should just…","grammar:896:ex4:words:0:zh":"a little","grammar:896:ex4:words:0:note":"すこし","grammar:896:ex4:words:0:pos":"adverb","grammar:896:ex4:words:1:zh":"if you wait","grammar:896:ex4:words:1:note":"まてば; ba-form conditional","grammar:896:ex4:words:1:pos":"verb","grammar:896:ex4:words:2:zh":"good / fine","grammar:896:ex4:words:2:note":"〜ばいい ＝ just … / it is enough to …","grammar:896:ex4:words:2:pos":"adjective","grammar:896:ex4:points:0":"〜ばいい: just do … (advice / solution)","grammar:896:ex4:points:1":"待てば: if you wait (ba-form conditional)","grammar:896:ex5:trans":"Can I wait here?","grammar:896:ex5:structure":"placeで＋verb potential form＋か。 「待てる」 is the potential form, can wait.","grammar:896:ex5:words:0:zh":"here","grammar:896:ex5:words:0:pos":"pronoun","grammar:896:ex5:words:1:zh":"(place of the action)","grammar:896:ex5:words:1:pos":"particle","grammar:896:ex5:words:2:zh":"can wait","grammar:896:ex5:words:2:note":"まてる; potential form","grammar:896:ex5:words:2:pos":"verb","grammar:896:ex5:words:3:zh":"(question)","grammar:896:ex5:words:3:pos":"particle","grammar:896:ex5:points:0":"待てる: can wait (potential form)","grammar:896:ex5:points:1":"で: place of action (waiting here)","exam:896:zh":"My friend hasn't come yet, so I'll wait here a little longer.","exam:896:why":"「待つ」 means to wait, which fits the situation where the friend hasn't arrived yet. 「帰る」 means to go home, which can't express staying here waiting for a friend."},"897":{"example:897:exzh":"This manifestation has a special meaning.","example:897:exzh2":"I can't understand the expression of his feelings.","example:897:exzh3":"This painting is an expression of joy, and it's very beautiful.","example:897:exzh4":"Once one appears, everyone takes notice.","example:897:exzh5":"Seeing this phenomenon, I became interested."},"898":{"example:898:exzh":"Please be careful not to get sick.","example:898:exzh2":"Please be careful not to get sick.","example:898:exzh3":"This disease is contagious.","example:898:exzh4":"When you're sick, please go to the hospital as soon as possible.","example:898:exzh5":"She recovered from her illness.","grammar:898:ex:trans":"Please be careful not to get sick.","grammar:898:ex:structure":"〜に気を付けてください","grammar:898:ex:explain":"At the core is the idiom 「〜に気を付ける」, meaning to be careful, to watch out, to take care; the thing you are careful about takes 「に」. Literally 「気を付ける」 means to keep something in mind, so 「病気（びょうき）に気を付ける」 means to be careful not to get sick, that is, to look after your health. The pattern 「〜てください」 (気を付けて + ください) makes a request. The whole sentence is a common way to show concern and remind someone to take care of themselves.","grammar:898:ex:words:0:zh":"illness","grammar:898:ex:words:0:note":"びょうき","grammar:898:ex:words:0:pos":"noun","grammar:898:ex:words:1:zh":"(object)","grammar:898:ex:words:1:pos":"particle","grammar:898:ex:words:2:zh":"be careful of","grammar:898:ex:words:2:note":"きをつけて","grammar:898:ex:words:2:pos":"set phrase","grammar:898:ex:words:3:zh":"please","grammar:898:ex:words:3:pos":"auxiliary verb","grammar:898:ex:points:0":"❗〜に気を付ける: to be careful of…, to watch out for… (the target takes に).","grammar:898:ex:points:1":"病気（びょうき）: illness, sickness.","grammar:898:ex2:trans":"Please be careful not to get sick.","grammar:898:ex2:structure":"〜ないように気を付けてください","grammar:898:ex2:words:0:zh":"illness","grammar:898:ex2:words:0:note":"びょうき","grammar:898:ex2:words:0:pos":"noun","grammar:898:ex2:words:1:zh":"(result)","grammar:898:ex2:words:1:pos":"particle","grammar:898:ex2:words:2:zh":"not to become","grammar:898:ex2:words:2:pos":"verb","grammar:898:ex2:words:3:zh":"so as not to","grammar:898:ex2:words:3:pos":"particle","grammar:898:ex2:words:4:zh":"be careful of","grammar:898:ex2:words:4:note":"きをつけて","grammar:898:ex2:words:4:pos":"set phrase","grammar:898:ex2:words:5:zh":"please","grammar:898:ex2:words:5:pos":"auxiliary verb","grammar:898:ex2:points:0":"❗〜ないように: so as not to …; to avoid ….","grammar:898:ex2:points:1":"病気になる: to get sick (に + なる).","grammar:898:ex3:trans":"This disease is contagious.","grammar:898:ex3:structure":"〜は伝染する","grammar:898:ex3:words:0:zh":"this","grammar:898:ex3:words:0:pos":"pre-noun adjectival","grammar:898:ex3:words:1:zh":"disease","grammar:898:ex3:words:1:note":"びょうき","grammar:898:ex3:words:1:pos":"noun","grammar:898:ex3:words:2:zh":"(topic)","grammar:898:ex3:words:2:pos":"particle","grammar:898:ex3:words:3:zh":"contagious","grammar:898:ex3:words:3:note":"でんせんする","grammar:898:ex3:words:3:pos":"verb","grammar:898:ex3:points:0":"伝染する: to be contagious, to spread.","grammar:898:ex3:points:1":"この病気: this disease.","grammar:898:ex4:trans":"When you are sick, please go to the hospital as soon as possible.","grammar:898:ex4:structure":"名詞のときは、早めに〜に行ってください","grammar:898:ex4:explain":"「病気のときは」 first sets up the situation of being sick. 「早めに」 modifies the action of going to the hospital, meaning don't put it off too long. The 「に」 in 「病院に」 marks the destination. 「行ってください」 is made of the te-form of 「行く」 plus the request marker 「ください」, meaning please go.","grammar:898:ex4:words:0:zh":"illness","grammar:898:ex4:words:0:note":"びょうき","grammar:898:ex4:words:0:pos":"noun","grammar:898:ex4:words:1:zh":"(links nouns)","grammar:898:ex4:words:1:pos":"particle","grammar:898:ex4:words:2:zh":"time","grammar:898:ex4:words:2:pos":"noun","grammar:898:ex4:words:3:zh":"(topic; sets up the situation)","grammar:898:ex4:words:3:pos":"particle","grammar:898:ex4:words:4:zh":"a little early; ahead of time","grammar:898:ex4:words:4:note":"はやめ","grammar:898:ex4:words:4:pos":"noun","grammar:898:ex4:words:5:zh":"(manner and timing of the action)","grammar:898:ex4:words:5:pos":"particle","grammar:898:ex4:words:6:zh":"hospital","grammar:898:ex4:words:6:note":"びょういん","grammar:898:ex4:words:6:pos":"noun","grammar:898:ex4:words:7:zh":"(destination)","grammar:898:ex4:words:7:pos":"particle","grammar:898:ex4:words:8:zh":"go","grammar:898:ex4:words:8:note":"いっ","grammar:898:ex4:words:8:pos":"verb","grammar:898:ex4:words:9:zh":"(links to the request expression)","grammar:898:ex4:words:9:pos":"particle","grammar:898:ex4:words:10:zh":"please","grammar:898:ex4:words:10:pos":"verb","grammar:898:ex4:points:0":"When a noun connects to 「とき」, use 「noun + の + とき」, meaning when….","grammar:898:ex4:points:1":"「早めに」 means a little earlier than usual or than scheduled; here it can be read as as soon as possible.","grammar:898:ex4:points:2":"The te-form of 「行く」 is 「行って」, and adding 「ください」 makes a request.","grammar:898:ex5:trans":"She has recovered from her illness.","grammar:898:ex5:structure":"〜から回復した","grammar:898:ex5:words:0:zh":"she","grammar:898:ex5:words:0:note":"かのじょ","grammar:898:ex5:words:0:pos":"pronoun","grammar:898:ex5:words:1:zh":"(topic)","grammar:898:ex5:words:1:pos":"particle","grammar:898:ex5:words:2:zh":"disease","grammar:898:ex5:words:2:note":"びょうき","grammar:898:ex5:words:2:pos":"noun","grammar:898:ex5:words:3:zh":"from","grammar:898:ex5:words:3:pos":"particle","grammar:898:ex5:words:4:zh":"recovered","grammar:898:ex5:words:4:note":"かいふくした","grammar:898:ex5:words:4:pos":"verb","grammar:898:ex5:points:0":"❗〜から回復する: to recover from… (から marks the starting point).","grammar:898:ex5:points:1":"回復する: to recover, to get better.","exam:898:zh":"My father is in the hospital because he's sick, so I go to visit him every day.","exam:898:why":"「病気で入院する」 means to be hospitalized because of illness. 「仕事」 can be connected to hospitals, but it doesn't fit the situation here of being in the hospital and having visitors."},"899":{"example:899:exzh":"The bomb exploded.","example:899:exzh2":"This movie is a story about a bomb.","example:899:exzh3":"The police safely disposed of the bomb.","example:899:exzh4":"He's good at designing bombs.","example:899:exzh5":"I learned about the dangers of bombs."}};